/* ============================================================
 *  ★ SX — SUN direct-API transform layer
 *  ยิงตรงไป 3301 แล้วแปลง raw response → shape ที่ renderer คาดหวัง
 *  (mirror ตรรกะใน DashboardView.java — ทำแทน servlet บน 8084)
 * ============================================================ */
// unwrap envelope { ..., result:<T> } → คืน result ?? data ?? resp
function _sunUnwrap(resp){
  if(resp == null) return resp;
  if(resp.result !== undefined && resp.result !== null) return resp.result;
  if(resp.data   !== undefined && resp.data   !== null) return resp.data;
  return resp;
}
function _sxNum(x){ return (x==null || isNaN(x)) ? 0 : Number(x); }
function _sxFmt(n){ return Number(n||0).toLocaleString('en-US'); }

var SX = {
  // /overview → KPI cards { total,totalFmt, closed,closedFmt, closedPct,closedPctFmt,
  //                         avgDays,avgDaysFmt, countries, topCountry, csClose,csCloseFmt }
  overview: function(resp){
    var r = _sunUnwrap(resp) || {};
    var total     = _sxNum((r.alllead||{}).total);
    var closed    = _sxNum((r.close_success||{}).total);
    var closedPct = _sxNum((r.close_success||{}).percent);
    if(!closedPct && total>0) closedPct = Math.round(closed/total*1000)/10;
    var avgDays   = _sxNum((r.avgDaysToClose||{}).total);
    var countries = _sxNum((r.country||{}).countryCount);
    var topCntry  = (r.country||{}).topCountry || '';
    var csClose   = _sxNum((r.cs_close||{}).total);
    // ★ milestones[] อาจอยู่นอก envelope (resp.milestones) หรือข้างใน (r.milestones หลัง unwrap) — เช็คทั้งคู่
    var milestones = Array.isArray((resp||{}).milestones) ? resp.milestones
                    : (Array.isArray(r.milestones) ? r.milestones : []);
    return {
      total: total,         totalFmt: _sxFmt(total),
      closed: closed,       closedFmt: _sxFmt(closed),
      closedPct: closedPct, closedPctFmt: String(closedPct),
      avgDays: avgDays,     avgDaysFmt: String(avgDays),
      countries: countries, topCountry: topCntry,
      csClose: csClose,     csCloseFmt: _sxFmt(csClose),
      milestones: milestones
    };
  }
};

// ==== GLOBAL API LOADING — track in-flight env.fetch() calls + show top bar ====
//   Monkey-patch window.fetch — เพิ่ม counter + toggle #globalApiLoading class
//   - counter++ ก่อน env.fetch() เริ่ม → แสดง bar
//   - counter-- หลัง env.fetch() เสร็จ (resolve หรือ reject) → ซ่อน bar เมื่อ counter=0
//   - debounce 180ms ก่อนซ่อน → กัน flicker ตอน fetch ต่อเนื่อง
(function _setupGlobalApiLoadingTracker() {
  var _inFlightCount = 0;
  var _hideTimer = null;

  function _refreshLoadingUI() {
    var el = document.getElementById('globalApiLoading');
    if (!el) return;
    if (_inFlightCount > 0) {
      if (_hideTimer) { clearTimeout(_hideTimer); _hideTimer = null; }
      el.classList.add('is-loading');
      el.setAttribute('aria-hidden', 'false');
    } else {
      // debounce ซ่อน 180ms — กัน flicker ระหว่าง chain ของ fetch ต่อเนื่อง
      if (_hideTimer) clearTimeout(_hideTimer);
      _hideTimer = tmo(function () {
        el.classList.remove('is-loading');
        el.setAttribute('aria-hidden', 'true');
      }, 180);
    }
  }

  var _origFetch = env.fetch;
  env = Object.assign({}, env, { fetch: function () {
    _inFlightCount++;
    _refreshLoadingUI();
    var p = _origFetch.apply(null, arguments);
    var done = function () {
      _inFlightCount = Math.max(0, _inFlightCount - 1);
      _refreshLoadingUI();
    };
    p.then(done, done);
    return p;
  } });
  console.log('[Dashboard] global fetch loading tracker installed');
})();

