function renderProvinceFilter() {
  // จังหวัดอาจเยอะ → ใช้ <select> แทน pills
  const provincesSet = new Set();
  let hasEmpty = false;
  RAW_DATA.forEach(r => {
    const p = (r.province || '').trim();
    if (p) provincesSet.add(p);
    else hasEmpty = true;
  });
  const provinces = [...provincesSet].sort((a,b) => a.localeCompare(b, 'th'));

  ['provinceFilter', 'provinceFilterSteps'].forEach(selectId => {
    const sel = byId(selectId); if (!sel) return;
    sel.innerHTML = '';
    // option "ทั้งหมด"
    const allOpt = document.createElement('option');
    allOpt.value = 'all';
    allOpt.textContent = 'ทั้งหมด (' + RAW_DATA.length + ')';
    sel.appendChild(allOpt);
    // จังหวัดทั้งหมด พร้อม count
    provinces.forEach(p => {
      const count = RAW_DATA.filter(r => (r.province||'').trim() === p).length;
      const opt = document.createElement('option');
      opt.value = p;
      opt.textContent = p + ' (' + count + ')';
      sel.appendChild(opt);
    });
    // (ไม่ระบุ)
    if (hasEmpty) {
      const count = RAW_DATA.filter(r => !(r.province||'').trim()).length;
      const opt = document.createElement('option');
      opt.value = '(ไม่ระบุ)';
      opt.textContent = '(ไม่ระบุ) (' + count + ')';
      sel.appendChild(opt);
    }
    // Set current value + active styling
    sel.value = state.provinceFilter;
    sel.classList.toggle('has-value', state.provinceFilter !== 'all');

    // Bind change once (remove old listener by cloning)
    if (!sel.dataset.bound) {
      sel.addEventListener('change', (e) => {
        state.provinceFilter = e.target.value;
        updateAll();
      });
      sel.dataset.bound = '1';
    }
  });
}

function renderJobFilter() {
  // อาชีพผู้กู้ — ใช้ <select>
  const jobsSet = new Set();
  let hasEmpty = false;
  RAW_DATA.forEach(r => {
    const j = (r.job || '').trim();
    if (j) jobsSet.add(j);
    else hasEmpty = true;
  });
  const jobs = [...jobsSet].sort((a,b) => a.localeCompare(b, 'th'));

  ['jobFilter', 'jobFilterSteps'].forEach(selectId => {
    const sel = byId(selectId); if (!sel) return;
    sel.innerHTML = '';
    const allOpt = document.createElement('option');
    allOpt.value = 'all';
    allOpt.textContent = 'ทั้งหมด (' + RAW_DATA.length + ')';
    sel.appendChild(allOpt);
    jobs.forEach(j => {
      const count = RAW_DATA.filter(r => (r.job||'').trim() === j).length;
      const opt = document.createElement('option');
      opt.value = j;
      opt.textContent = j + ' (' + count + ')';
      sel.appendChild(opt);
    });
    if (hasEmpty) {
      const count = RAW_DATA.filter(r => !(r.job||'').trim()).length;
      const opt = document.createElement('option');
      opt.value = '(ไม่ระบุ)';
      opt.textContent = '(ไม่ระบุ) (' + count + ')';
      sel.appendChild(opt);
    }
    sel.value = state.jobFilter;
    sel.classList.toggle('has-value', state.jobFilter !== 'all');

    if (!sel.dataset.bound) {
      sel.addEventListener('change', (e) => {
        state.jobFilter = e.target.value;
        updateAll();
      });
      sel.dataset.bound = '1';
    }
  });
}
// ==== ECharts color palette + shared font ====
const EC_COLORS = {
  PLS: '#4f7cff', CS: '#00d4a8', AN: '#9C6F63', LS: '#ffb84d', FI: '#ef4444', LE: '#a26bff', CRM: '#f01685',
  primary: '#4f7cff',
  bar: ['#4f7cff','#00d4a8','#ffb84d','#a26bff','#f01685','#ff7eb6'],
  country: ['#e23e57','#e2417c','#d4459a','#bd4ab1','#9e51c0','#7c57c8','#5e5cc8','#4f7cff','#3a90d5','#3aa6d5']
};
/* palette กลาง 12 สีของ activity group badge (ดู CLAUDE.md ข้อ 2) — ใช้ให้สอดคล้องกันทุกที่ที่โชว์สีกลุ่ม/ขั้นตอน */
const STEPPER_PALETTE = {
  1: ['#0C8E6A'],
  2: ['#0C8E6A','#6043B6'],
  3: ['#0C8E6A','#0D61CF','#6043B6'],
  4: ['#0C8E6A','#1A8FE3','#0D61CF','#6043B6'],
  5: ['#0C8E6A','#0AA77C','#1A8FE3','#0D61CF','#6043B6'],
  6: ['#0C8E6A','#0AA77C','#1A8FE3','#0D61CF','#6043B6','#7F63D2'],
  7: ['#0C8E6A','#0AA77C','#00C08B','#1A8FE3','#0D61CF','#6043B6','#7F63D2'],
  8: ['#0C8E6A','#0AA77C','#00C08B','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2'],
  9: ['#0C8E6A','#0AA77C','#00C08B','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2','#B7A4EF'],
  10: ['#0C8E6A','#0AA77C','#00C08B','#62E1B3','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2','#B7A4EF'],
  11: ['#0C8E6A','#0AA77C','#00C08B','#62E1B3','#80E8FF','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2','#B7A4EF'],
  12: ['#0C8E6A','#0AA77C','#00C08B','#62E1B3','#80E8FF','#1DCBF1','#009ED0','#1A8FE3','#0D61CF','#6043B6','#7F63D2','#B7A4EF']
};
function stepperColor(total, idx) {
  var row = STEPPER_PALETTE[Math.min(total, 12)] || STEPPER_PALETTE[12];
  return row[Math.min(idx, row.length - 1)] || '#0C8E6A';
}
const EC_FONT = { fontFamily: "'Noto Sans Thai','Be Vietnam Pro',sans-serif" };
/* ★ สี "ตัวหนังสือหลัก" ของกราฟ ECharts (legend/แกน/label ตัวเลข) — เดิม hardcode '#0f172a' (เกือบดำ) ทุกจุด
   ไม่ตอบสนอง data-theme เลย (ตรงกับ memory เรื่อง ecInk ที่หายไปตอน merge r2001) contrast บนพื้นการ์ดมืดแค่ 1.22
   แก้ให้เป็นฟังก์ชันอ่าน data-theme สด ๆ ตอน render แต่ละครั้ง + เรียก renderAllCharts() ใหม่ตอนสลับธีม (ด้านล่างสุดของไฟล์) */
function ecInk() { return document.documentElement.getAttribute('data-theme') === 'dark' ? '#E5E7EB' : '#0f172a'; }
const EC_TOOLTIP = {
  backgroundColor: '#0f172a', borderColor: '#0f172a', borderWidth: 0,
  textStyle: Object.assign({ color: '#fff', fontSize: 12 }, EC_FONT),
  padding: [8, 12]
};

const echartsInstances = {};
function _initEC(id) {
  const el = document.getElementById(id);
  if (!el) return null;
  // ★ ถ้า container ขนาด 0 (CSS ยังไม่ apply / tab inactive) — ECharts จะ init แต่ canvas ว่างเปล่า
  //   schedule resize() หลัง CSS apply เสร็จ + ลองหลายรอบรับมือ render lag บนเครื่องช้า
  if (echartsInstances[id]) { try { echartsInstances[id].dispose(); } catch(e){} }
  const inst = env.echarts.init(el, null, { renderer: 'canvas' });
  echartsInstances[id] = inst;
  // ★ ตรวจ container ขนาด — ถ้าเป็น 0 ตอน init → resize ใหม่เมื่อ layout พร้อม
  if (el.clientWidth === 0 || el.clientHeight === 0) {
    var tries = 0;
    var retry = function () {
      if (el.clientWidth > 0 && el.clientHeight > 0) {
        try { inst.resize(); } catch (e) {}
      } else if (++tries < 20) {
        tmo(retry, 100);   // ลองทุก 100ms นาน 2 วินาที max
      }
    };
    tmo(retry, 50);
  }
  return inst;
}

