// ==== Group donut ====
function renderGroupChart() {
  const inst = _initEC('chartGroup');
  if (!inst) return;
  const groupList = ECDATA.group || [];
  // ★ ใช้สีตามกลุ่ม (CS/AN/PLS/LS/FI/LE/CRM) จาก STATUS_DEPT_COLORS แทน stepperColor เดิม
  //   (stepperColor ไล่สีตาม index — ไม่ตรงกับ legend CS=เขียว/AN=น้ำตาล/PLS=น้ำเงิน/LS=ส้ม/FI=แดง/
  //   LE=ม่วง/CRM=ชมพู ที่ user ต้องการให้ตรงกับกราฟ "กลุ่มสถานะ" ตามภาพที่ส่งมา — สีชุดนี้เป็นสีมาตรฐาน
  //   ของแอปที่ใช้อยู่แล้วกับ pipeline table header/status table ที่อื่น) fallback เป็น stepperColor
  //   เผื่อกรณีมี group code ที่ไม่รู้จัก (กัน error ไม่มีสี)
  const items = groupList.map(function (g, idx) {
    var dc = STATUS_DEPT_COLORS[String(g.name || '').toUpperCase()];
    var color = dc ? dc.col : stepperColor(groupList.length, idx);
    return { name: g.name, value: g.value, itemStyle: { color: color } };
  });
  inst.setOption({
    tooltip: Object.assign({ trigger: 'item', formatter: function (p) { return p.name + ': ' + p.value + ' (' + p.percent + '%)'; } }, EC_TOOLTIP),
    legend: {
      orient: 'horizontal', bottom: 4, icon: 'circle',
      textStyle: Object.assign({ color: ecInk(), fontSize: 11, fontWeight: 600 }, EC_FONT),
      itemGap: 14, itemWidth: 10, itemHeight: 10
    },
    /* radius/center เล็กลง+ขยับขึ้น กันชนกับ legend 7 รายการที่ wrap 2 แถวด้านล่าง (ต้องคู่กับ .chart-canvas-wrap.tall) */
    series: [{
      type: 'pie', radius: ['52%', '70%'], center: ['50%', '36%'],
      avoidLabelOverlap: false, label: { show: false }, labelLine: { show: false },
      data: items
    }]
  });
}

// ==== CS Performance horizontal bar (with % labels) ====
function renderCSChart() {
  const inst = _initEC('chartCS');
  if (!inst) return;
  const d = ECDATA.cs || { yAxis: [], values: [], total: 0 };
  // ★ Ensure d.values is an array before calling reduce
  const valsArray = Array.isArray(d.values) ? d.values : [];
  const total = d.total || (valsArray.length > 0 ? valsArray.reduce(function (a, b) { return a + b; }, 0) : 0) || 1;
  // ECharts บน horizontal bar: yAxis แบบ category ต้องเรียงจาก ล่าง→บน
  // ของเรา values[0] = ค่ามากสุด ต้องโชว์อยู่ "บนสุด"
  const yLabels = d.yAxis.slice().reverse();
  const vals    = d.values.slice().reverse();
  const colors  = vals.map(function (_, i) { return EC_COLORS.bar[(vals.length - 1 - i) % EC_COLORS.bar.length]; });
  inst.setOption({
    grid: { left: 80, right: 70, top: 8, bottom: 28 },
    tooltip: Object.assign({ trigger: 'axis', axisPointer: { type: 'shadow' },
      formatter: function (p) {
        const v = p[0].value;
        return p[0].name + ': ' + v + ' ลีด · ' + (v * 100 / total).toFixed(1) + '%';
      }
    }, EC_TOOLTIP),
    xAxis: {
      type: 'value', max: Math.ceil(Math.max.apply(null, vals.concat([1])) * 1.22),
      splitLine: { lineStyle: { color: 'rgba(15,23,42,0.05)' } },
      axisLine: { show: false }, axisTick: { show: false },
      axisLabel: Object.assign({ color: '#94a3b8', fontSize: 11 }, EC_FONT)
    },
    yAxis: {
      type: 'category', data: yLabels,
      axisLine: { show: false }, axisTick: { show: false },
      axisLabel: Object.assign({ color: ecInk(), fontSize: 13, fontWeight: 600 }, EC_FONT)
    },
    series: [{
      type: 'bar', data: vals.map(function (v, i) { return { value: v, itemStyle: { color: colors[i], borderRadius: [0, 8, 8, 0] } }; }),
      barMaxWidth: 26,
      label: {
        show: true, position: 'right', distance: 8,
        formatter: function (p) { return (p.value * 100 / total).toFixed(1) + '%'; },
        color: ecInk(), fontSize: 12, fontWeight: 700, fontFamily: EC_FONT.fontFamily
      }
    }]
  });
}

