  var businessPalette = ['#00d4a8','#4f7cff','#ffb84d','#ff5f6d','#a26bff','#3ad6dd'];
  var channelPalette = ['#ffb84d','#4f7cff','#00d4a8','#ff5f6d','#a26bff','#3ad6dd'];
