  renderLeadBreakdownPie('chartLeadBreakdownBusinessType', 'businesstype', businessPalette);
  renderLeadBreakdownBar('chartLeadBreakdownDistrict', 'district', piePalette);
  renderLeadBreakdownPie('chartLeadBreakdownChannel', 'channel', channelPalette);
