// ==== Custom HTML funnel renderer (driven by EL JSON) ====
// items: [{name, total, closed, sharePct, barPct, closedOnly}, ...]
function renderFunnelRows(wrapId, items, palette) {
  const wrap = document.getElementById(wrapId);
  if (!wrap) return;
  wrap.innerHTML = '';
  if (!items || items.length === 0) {
    wrap.innerHTML = '<div class="text-muted text-center py-4">' + DBSUN_I18N.noData + '</div>';
    return;
  }
  items.forEach(function (d, i) {
    const closedOnly = !!d.closedOnly;
    const text  = closedOnly ? (DBSUN_I18N.closed + ' ' + d.closed) : (d.total + ' ' + DBSUN_I18N.leadsUnit + ' · ' + DBSUN_I18N.closed + ' ' + d.closed);
    const c1 = palette[i % palette.length];
    const c2 = palette[(i + 1) % palette.length];
    const row = document.createElement('div');
    row.className = 'funnel-row';
    // ★ Flat structure — 4 columns ตรงกับ CSS Grid:
    //   [ label ] [ bar-track > bar ] [ bar-text ] [ pct ]
    //   tooltip บน row ทั้งแถวเพื่อแสดง full name หรือ text ที่อาจตัดด้วย ellipsis
    var fullName = String(d.name || '');
    row.setAttribute('title', fullName + ' — ' + text + ' (' + d.sharePct.toFixed(1) + '%)');
    row.innerHTML =
      '<div class="funnel-label">' + escapeHtml(fullName) + '</div>' +
      '<div class="funnel-bar-track">' +
        '<div class="funnel-bar" style="width:' + d.barPct + '%; background: linear-gradient(90deg, ' + c1 + ', ' + c2 + ')"></div>' +
      '</div>' +
      '<div class="funnel-bar-text">' + text + '</div>' +
      '<div class="funnel-pct">' + d.sharePct.toFixed(1) + '%</div>';
    wrap.appendChild(row);
  });
}

function renderFunnel() {
  renderFunnelRows('funnelView', ECDATA.sourceFunnel,
    ['#4f7cff','#00d4a8','#ffb84d','#ff5f6d','#a26bff','#ff7eb6','#3ad6dd']);
}

// ★ Loading state สำหรับ funnel chart — เลียนแบบ ECharts inst.showLoading() ทุกประการ
//   พฤติกรรมเดียวกับ ECharts:
//     1. เพิ่ม overlay (mask + spinner + text) เป็น sibling ทับบนข้อมูลเก่า
//        — ไม่ลบข้อมูลเก่าทิ้ง (เหมือน showLoading ที่ทับ canvas)
//     2. ผู้ใช้เห็นข้อมูลเดิม + spinner ด้านบน → context ไม่หาย
//     3. เมื่อ data ใหม่มา renderFunnelRows() ทำ innerHTML='' → ลบทั้ง rows เก่า + overlay
//   on=true   → ensure overlay exists (idempotent — ไม่ duplicate)
//   on=false  → ลบ overlay (ใช้ตอน error หรือ explicit clear)
function showFunnelLoading(wrapId, on) {
  var wrap = document.getElementById(wrapId);
  if (!wrap) return;
  // หา overlay เดิม (ถ้ามี)
  var existing = wrap.querySelector(':scope > .ec-loading-overlay');
  if (on) {
    if (existing) return;  // มีอยู่แล้ว — idempotent
    var ov = document.createElement('div');
    ov.className = 'ec-loading-overlay';
    ov.setAttribute('aria-live', 'polite');
    ov.setAttribute('aria-busy', 'true');
    ov.innerHTML =
      '<div class="ec-loading-spinner" aria-hidden="true"></div>' +
      '<div class="ec-loading-text">กำลังโหลด…</div>';
    wrap.appendChild(ov);
  } else {
    if (existing) existing.remove();
  }
}
function renderFunnelCS() {
  // ★ ใช้สีตามรูป: ฟ้า → ฟ้าอ่อน → น้ำเงิน-เหลือง gradient (matching screenshot)
  renderFunnelRows('funnelCsView', ECDATA.csFunnel,
    ['#00d4a8','#4f7cff','#ffb84d','#ff5f6d','#a26bff']);
  // subtitle ถูก inject ผ่าน EL แล้ว (#{dashboardView.csFunnelSubtitle}) — ไม่ overwrite
}
function renderFunnelCountry() {
  // gradient palette แดง → ม่วง matching country chart
  const n = (ECDATA.countryFunnel || []).length;
  const palette = [];
  for (let i = 0; i < Math.max(n, 1); i++) {
    const t = i / Math.max(n - 1, 1);
    palette.push('hsl(' + (350 - t * 60) + ', 80%, 60%)');
  }
  renderFunnelRows('funnelCountryView', ECDATA.countryFunnel, palette);
  // subtitle ถูก inject ผ่าน EL แล้ว (#{dashboardView.countryFunnelSubtitle}) — ไม่ overwrite
}

