// ==== KPIs ====
function renderKPIs(data) {
  byId('kpiTotal').textContent = fmt(data.length);
  // ปิดสำเร็จ = แถวที่มีวันที่เก็บเงิน (payment_date ไม่ว่าง)
  const closed = data.filter(r => r.payment_date && String(r.payment_date).trim() !== '').length;
  byId('kpiClosed').textContent = fmt(closed);
  byId('kpiClosedPct').textContent = data.length ? (closed * 100 / data.length).toFixed(1) : '0.0';

  const diffs = data.map(r => daysBetween(r.contact_date, r.payment_date)).filter(d => d !== null && d >= 0);
  const avg = diffs.length ? diffs.reduce((a,b)=>a+b,0) / diffs.length : 0;
  byId('kpiAvgDays').textContent = avg.toFixed(1);

  const countries = new Set(data.map(r => r.country).filter(Boolean));
  byId('kpiCountries').textContent = countries.size;
  const top = mostCommon(data.map(r => r.country).filter(Boolean));
  byId('kpiTopCountry').textContent = top ? (DBSUN_I18N.rank1 + ' ' + top.k) : '—';

  byId('totalRecords').textContent = fmt(data.length);
  const hasFilter = state.monthFilter!=='all' || state.groupFilter!=='all' || state.csFilter!=='all' || state.sourceFilter!=='all';
  byId('kpiTotalSub').textContent = hasFilter ? 'ในช่วงที่เลือก' : 'ข้อมูลทั้งหมด';

  // Last updated
  if (META.generatedAt) {
    const d = new Date(META.generatedAt);
    const now = new Date();
    const diff = Math.round((now - d) / 1000);
    let ago;
    if (diff < 60) ago = `อัปเดตเมื่อสักครู่`;
    else if (diff < 3600) ago = `อัปเดต ${Math.floor(diff/60)} นาทีที่แล้ว`;
    else ago = `อัปเดต ${d.toLocaleString('th-TH', { hour: '2-digit', minute: '2-digit' })}`;
    byId('lastUpdated').textContent = ago;
  }
}

// ==== TABLE ====
function badgeClass(g) {
  return ({ PLS:'badge-pls', CS:'badge-cs', LS:'badge-ls', LE:'badge-le' })[g] || 'badge-soft';
}

function renderTable(data) {
  const total = data.length;
  const rowEl = byId('rowCount'); if(rowEl) rowEl.textContent = `${fmt(total)} รายการ`;
  const tblEl = byId('tableCount'); if(tblEl) tblEl.textContent = `${fmt(total)} รายการ`;

  const totalPages = Math.max(1, Math.ceil(total / state.pageSize));
  if (state.page > totalPages) state.page = totalPages;
  const start = (state.page - 1) * state.pageSize;
  const slice = data.slice(start, start + state.pageSize);

  const tbody = byId('tableBody');
  if (!tbody) return;
  if (slice.length === 0) {
    tbody.innerHTML = `<tr><td colspan="12" class="text-center py-5 text-muted">${DBSUN_I18N.noData}</td></tr>`;
  } else {
    tbody.innerHTML = slice.map(r => `
      <tr>
        <td style="white-space:nowrap; color:var(--ink-soft); font-variant-numeric: tabular-nums;">${escapeHtml(r.contact_date)}</td>
        <td style="font-weight:600;">${escapeHtml(r.code)}</td>
        <td>${escapeHtml(r.firstname)} ${escapeHtml(r.lastname)}</td>
        <td><span style="font-size:12px; color:var(--ink-soft);">${escapeHtml(r.country)}</span></td>
        <td><span style="font-size:12px; color:var(--ink-soft);">${escapeHtml(r.province||'-')}</span></td>
        <td><span style="font-size:12px;">${escapeHtml(r.source||'-')}</span></td>
        <td>${escapeHtml(r.cs)}</td>
        <td style="white-space:nowrap; color:var(--ink-soft); font-variant-numeric: tabular-nums;">${escapeHtml(r.payment_date||'-')}</td>
        <td><span class="badge-soft ${badgeClass(r.group)}">${escapeHtml(r.group)}</span></td>
        <td style="font-size:12px; color:var(--ink-soft);">${escapeHtml(r.step)}</td>
        <td style="font-size:12px; color:var(--ink-soft);">${escapeHtml(r.job||'-')}</td>
        <td style="font-size:12px; color:var(--ink-soft);">${escapeHtml(r.position||'-')}</td>
      </tr>
    `).join('');
  }

  // Pagination
  const pag = byId('pagination'); if(!pag) return; pag.innerHTML = '';
  if (totalPages > 1) {
    pag.appendChild(mkPageBtn('‹', state.page-1, state.page === 1));
    pageNumbersFor(state.page, totalPages).forEach(p => {
      if (p === '…') {
        const span = document.createElement('span');
        span.textContent = '…';
        span.style.cssText = 'padding:0 6px; color:var(--ink-mute);';
        pag.appendChild(span);
      } else {
        pag.appendChild(mkPageBtn(p, p, false, p === state.page));
      }
    });
    pag.appendChild(mkPageBtn('›', state.page+1, state.page === totalPages));
  }
}
function mkPageBtn(label, page, disabled, active) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'page-btn' + (active ? ' active' : '');
  b.textContent = label;
  b.disabled = !!disabled;
  if (!disabled) b.addEventListener('click', () => { state.page = page; renderTable(getFilteredData()); window.scrollTo({ top: byId('tableBody').offsetTop - 100, behavior: 'smooth' }); });
  return b;
}
function pageNumbersFor(current, total) {
  if (total <= 7) return Array.from({length: total}, (_,i)=>i+1);
  if (current <= 4) return [1,2,3,4,5,'…',total];
  if (current >= total-3) return [1,'…',total-4,total-3,total-2,total-1,total];
  return [1,'…',current-1,current,current+1,'…',total];
}

// ==== PIPELINE TAB ====
const PIPELINE_GROUPS = ['CS', 'AN', 'PLS', 'LS', 'FI', 'LE', 'CRM'];
const MONTH_NAMES_TH = ['มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน',
                       'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'];

// people = array of { key, code, firstname, lastname, contact_date }
function buildPipelineMatrix(data) {
  const matrix = {};
  for (let m = 1; m <= 12; m++) {
    const mm = String(m).padStart(2, '0');
    matrix[mm] = {};
    PIPELINE_GROUPS.forEach(g => matrix[mm][g] = new Map()); // Map: key → person
  }

  data.forEach(r => {
    const monthKey = (r.contact_date || '').slice(5, 7); // 'YYYY-MM-DD' → 'MM'
    if (!matrix[monthKey]) return; // เดือนผิดรูป
    const group = (r.group || '').trim();
    if (!matrix[monthKey][group]) return; // ไม่อยู่ใน 5 กลุ่มหลัก

    // unique key = ชื่อ + นามสกุล (rtrimmed)
    const first = (r.firstname || '').trim();
    const last = (r.lastname || '').trim();
    const key = (first + '|' + last).trim();
    if (!key || key === '|') return; // ไม่มีชื่อ ข้าม

    // เก็บแค่ครั้งแรกที่เจอ — ลบซ้ำ
    if (!matrix[monthKey][group].has(key)) {
      matrix[monthKey][group].set(key, {
        key,
        code: r.code || '',
        firstname: first,
        lastname: last,
        contact_date: r.contact_date || '',
        step: (r.step || '').trim(),
      });
    }
  });

  return matrix;
}

// เก็บข้อมูลจาก getStatusData (เรียกเฉพาะตอนเปิด tab ครั้งแรก ของแต่ละปี)
const STATUS_CACHE = {}; // year → result
let STATUS_LOADED_YEAR = null; // ปีที่ load แล้วล่าสุด
// ปีที่มีชีท status (จะ sync จาก server response ครั้งแรก)
let STATUS_AVAILABLE_YEARS = ['2024', '2025', '2026'];

// Render pill ปีในแถบ filter ของ tab สถานะ
function renderStatusYearFilters() {
  const wrap = byId('statusYearFilters');
  if (!wrap) return;
  wrap.innerHTML = '';
  STATUS_AVAILABLE_YEARS.forEach(y => {
    const btn = mkPill('ปี ' + y, y, state.statusYear === y);
    btn.addEventListener('click', () => {
      if (state.statusYear === y) return; // คลิกซ้ำ ข้าม
      state.statusYear = y;
      renderStatusYearFilters();
      loadStatusForCurrentYear(false);
    });
    wrap.appendChild(btn);
  });
}

function loadStatusForCurrentYear(forceRefresh) {
  const year = state.statusYear;

  // ถ้าปีที่เลือกไม่มีชีท status → แสดง empty state แทน error
  if (STATUS_AVAILABLE_YEARS.indexOf(year) < 0) {
    STATUS_LOADED_YEAR = year;
    byId('statusYear').textContent = year;
    byId('statusYearSub').textContent = year;
    byId('statusGenAt').textContent = '—';
    byId('statusTotal').textContent = '0';
    byId('statusOpenCount').textContent = '0';
    byId('statusCompleteCount').textContent = '0';
    byId('statusEmpCount').textContent = '0';
    byId('statusAvgOpen').textContent = '0';
    byId('statusAvgComplete').textContent = '0';
    byId('statusBody').innerHTML =
      `<tr><td colspan="8" class="text-center py-5 text-muted">` +
      `<i class="fa-solid fa-circle-info me-2"></i>` +
      `ไม่มีข้อมูลประวัติขั้นตอนสำหรับปี ${escapeHtml(year)} — ` +
      `ปีที่รองรับ: ${STATUS_AVAILABLE_YEARS.join(', ')}` +
      `</td></tr>`;
    return;
  }

  // ใช้ cache ฝั่ง client ถ้ามี (ไม่ต้องเรียก server ซ้ำเมื่อสลับ tab กลับ)
  if (!forceRefresh && STATUS_CACHE[year]) {
    renderStatus(STATUS_CACHE[year]);
    return;
  }

  // Show loading state
//  byId('statusBody').innerHTML = '<tr><td colspan="8" class="text-center py-5 text-muted">กำลังโหลดข้อมูล...</td></tr>';
  byId('statusTotal').textContent = '—';
  byId('statusOpenCount').textContent = '—';
  byId('statusCompleteCount').textContent = '—';
  byId('statusEmpCount').textContent = '—';

  // Compute status summary from RAW_DATA (client-side aggregation — no server call)
  tmo(() => {
    try {
      const rowsOfYear = RAW_DATA.filter(r => (r.contact_date || '').slice(0, 4) === year);
      const customers = rowsOfYear.map(r => ({
        code: r.code, name: (r.firstname + ' ' + r.lastname).trim(),
        group: r.group, lastStatus: r.last_step, cs: r.cs,
        contactDate: r.contact_date, paymentDate: r.payment_date
      }));
      // perEmployee summary
      const empMap = {};
      rowsOfYear.forEach(r => {
        if (!r.cs) return;
        if (!empMap[r.cs]) empMap[r.cs] = { emp: r.cs, total: 0, completed: 0, open: 0 };
        empMap[r.cs].total++;
        if (r.payment_date) empMap[r.cs].completed++;
        else if (r.group === 'CS') empMap[r.cs].open++;
      });
      const perEmployee = Object.values(empMap).sort((a, b) => b.total - a.total);
      const completed = rowsOfYear.filter(r => r.payment_date).length;
      const openCS    = rowsOfYear.filter(r => !r.payment_date && r.group === 'CS').length;
      const res = {
        meta: { year: year, totalCustomers: rowsOfYear.length, openCS: openCS,
                completed: completed, overallAvgOpen: 0, overallAvgComplete: 0,
                generatedAt: new Date().toISOString() },
        perEmployee: perEmployee,
        customers: customers
      };
      STATUS_CACHE[year] = res;
      STATUS_LOADED_YEAR = year;
      renderStatus(res);
    } catch (e) {
      byId('statusBody').innerHTML = `<tr><td colspan="8" class="text-center py-5 text-muted">✗ ${escapeHtml(e.message)}</td></tr>`;
      showToast('✗ ' + e.message, 'error');
    }
  }, 80);
}

function renderStatus(res) {
  if (!res) return;
  const meta = res.meta || {};
  const perEmp = res.perEmployee || [];
  const customers = res.customers || [];

  // Update header (year + generated-at) เท่านั้น — ไม่แตะ statusBody
  if (byId('statusYear'))    byId('statusYear').textContent = meta.year || '--';
  if (byId('statusYearSub')) byId('statusYearSub').textContent = meta.year || '--';
  if (byId('statusGenAt'))   byId('statusGenAt').textContent = meta.generatedAt
    ? new Date(meta.generatedAt).toLocaleString('th-TH', { dateStyle: 'medium', timeStyle: 'short' })
    : '--';

  // ★ EARLY RETURN — ข้าม mock leaderboard render ทั้งหมด
  //   statusBody ถูก control โดย renderStatusTable() ที่ใช้ข้อมูลจริงจาก /dashboard/employee-performance
  //   ถ้าให้ฟังก์ชันนี้ render ต่อ → จะทับ loading state หรือทับข้อมูล API
  return;

  // ↓ DEAD CODE ตั้งใจไว้ — เก็บไว้เป็นเอกสารแสดงโครงสร้างเก่า (ไม่ทำงาน)
  // KPIs
  byId('statusTotal').textContent = fmt(meta.totalCustomers || 0);
  byId('statusOpenCount').textContent = fmt(meta.openCS || 0);
  byId('statusCompleteCount').textContent = fmt(meta.completed || 0);
  byId('statusEmpCount').textContent = fmt(perEmp.length);
  byId('statusAvgOpen').textContent = (meta.overallAvgOpen || 0).toFixed(1);
  byId('statusAvgComplete').textContent = (meta.overallAvgComplete || 0).toFixed(1);

  // Leaderboard
  const tbody = byId('statusBody');
  if (perEmp.length === 0) {
    tbody.innerHTML = '<tr><td colspan="7" class="text-center py-5 text-muted">' + DBSUN_I18N.noData + '</td></tr>';
    return;
  }

  // เก็บ customer index by code สำหรับ popup
  const customerByCode = {};
  customers.forEach(c => customerByCode[c.code] = c);
  STATUS_CACHE[meta.year]._customerByCode = customerByCode;

  // 7 days threshold = WARN level for avg
  const warn = (avg) => avg > 14 ? 'status-avg-warn' : (avg > 0 && avg < 7 ? 'status-avg-ok' : '');

  tbody.innerHTML = perEmp.map(e => `
    <tr>
      <td class="st-emp" data-emp="${escapeHtml(e.emp)}">${escapeHtml(e.emp)}</td>
      <td>${fmt(e.total)}</td>
      <td>${e.openCount > 0
        ? `<span class="status-cell-open" data-emp="${escapeHtml(e.emp)}" data-type="open">${fmt(e.openCount)}</span>`
        : `<span class="status-cell-open empty">0</span>`
      }</td>
      <td class="${warn(e.avgOpenDays)}">${e.avgOpenDays > 0 ? e.avgOpenDays.toFixed(1) + ' วัน' : '—'}</td>
      <td>${e.completedCount > 0
        ? `<span class="status-cell-done" data-emp="${escapeHtml(e.emp)}" data-type="done">${fmt(e.completedCount)}</span>`
        : `<span class="status-cell-done empty">0</span>`
      }</td>
      <td class="${warn(e.avgCompleteDays)}">${e.avgCompleteDays > 0 ? e.avgCompleteDays.toFixed(1) + ' วัน' : '—'}</td>
      <td>${fmt(e.transitionCount)}</td>
    </tr>
  `).join('');

  // Bind clicks — เปิด popup เมื่อคลิกชื่อหรือตัวเลข
  tbody.querySelectorAll('.st-emp').forEach(el => {
    el.addEventListener('click', () => openStatusModal(el.dataset.emp, 'all'));
  });
  tbody.querySelectorAll('.status-cell-open:not(.empty)').forEach(el => {
    el.addEventListener('click', (e) => {
      e.stopPropagation();
      openStatusModal(el.dataset.emp, 'open');
    });
  });
  tbody.querySelectorAll('.status-cell-done:not(.empty)').forEach(el => {
    el.addEventListener('click', (e) => {
      e.stopPropagation();
      openStatusModal(el.dataset.emp, 'done');
    });
  });
}

function openStatusModal(empName, type) {
  // type: 'all' | 'open' | 'done'
  // ใช้ state.statusYear (ปีปัจจุบันที่กำลังดู) ไม่ใช่ STATUS_LOADED_YEAR (ที่อาจ stale)
  const year = state.statusYear;
  const data = STATUS_CACHE[year];
  if (!data) return;

  const empData = (data.perEmployee || []).find(e => e.emp === empName);
  if (!empData) return;

  let codes = [];
  let typeLabel = '';
  if (type === 'open') {
    codes = empData.openCustomerCodes || [];
    typeLabel = 'ค้างทำ (CS)';
  } else if (type === 'done') {
    codes = empData.completedCustomerCodes || [];
    typeLabel = 'ทำต่อแล้ว';
  } else {
    codes = empData.customerCodes || [];
    typeLabel = DBSUN_I18N.all;
  }

  const customerByCode = data._customerByCode || {};
  const people = codes.map(c => customerByCode[c]).filter(Boolean);

  // เรียง: วันค้างเยอะ → น้อย (สำหรับ open), หรือ contactdate ใหม่สุด (อื่นๆ)
  if (type === 'open') {
    people.sort((a, b) => (b.openDays || 0) - (a.openDays || 0));
  } else {
    people.sort((a, b) => (b.contactdate || '').localeCompare(a.contactdate || ''));
  }

  byId('pipelineModalTitle').textContent = empName;
  byId('pipelineModalSub').textContent = `${typeLabel} · ${people.length} คน · ปี ${year}`;
  byId('pipelineModalSearch').value = '';
  byId('pipelineModalSearch').placeholder = 'ค้นหา ชื่อ / รหัส...';

  renderStatusList(people);
  _pipelineCurrentPeople = people;  // reuse search variable

  // Use existing pipeline modal
  const modal = byId('pipelineModal');
  modal.classList.add('show');
  modal.setAttribute('aria-hidden', 'false');
  tmo(() => byId('pipelineModalSearch').focus(), 100);

  // Override list rendering for status (different fields than pipeline)
  _pipelineModalRenderer = renderStatusList;
}

function renderStatusList(people) {
  const list = byId('pipelineList');
  if (people.length === 0) {
    list.innerHTML = '<li class="text-muted text-center py-4">ไม่พบรายชื่อ</li>';
    return;
  }
  list.innerHTML = people.map(p => {
    const status = (p.lastStatus || '').toLowerCase();
    const badgeClass = ['cs','pls','ls','le','crm','fi'].includes(status) ? 'pl-badge-' + status : '';
    let dayInfo;
    if (p.openDays !== null && p.openDays !== undefined) {
      dayInfo = `<span class="pl-days" style="color:var(--c2);">⏳ ค้าง ${p.openDays} วัน</span>`;
    } else if (p.transitionCount > 0) {
      dayInfo = `<span class="pl-days" style="color:var(--c3);">✓ เฉลี่ย ${p.avgTransitionDays} วัน</span>`;
    } else {
      dayInfo = `<span class="pl-days">—</span>`;
    }
    // แสดงชื่อเด่น รหัสเป็น sub-info ด้านล่าง
    const nameText = p.name || '(ไม่ระบุชื่อ)';
    return `
      <li>
        <div class="pl-person">
          <span class="pl-name">${escapeHtml(nameText)}</span>
          <span class="pl-code-sub">${escapeHtml(p.code)}</span>
        </div>
        <span class="pl-badge ${badgeClass}">${escapeHtml(p.lastStatus)}</span>
        ${dayInfo}
      </li>
    `;
  }).join('');
}

let _pipelineModalRenderer = null; // ใช้ render แทน default ใน popup search

function renderPipeline() {
  // ECData edition: อ่านจาก ECDATA2.pipelineTable (จาก DashboardView)
  const pt = (ECDATA2 && ECDATA2.pipelineTable) || { groups: [], months: [], totals: {}, grandTotal: 0 };
  const groups = (Array.isArray(pt.groups) && pt.groups.length)
      ? pt.groups
      : ((Array.isArray(pt.departments) && pt.departments.length) ? pt.departments : ['CS','AN','PLS','LS','FI','LE','CRM']);
  const months = (Array.isArray(pt.months) && pt.months.length)
      ? pt.months
      : (Array.isArray(pt.rows) ? pt.rows : []);
  // ★ กัน pt.totals หายไปจาก data shape ที่ไม่คาดคิด — ถ้าไม่ guard ตรงนี้ การอ่าน pt.totals[d]
  //   ด้านล่างจะ throw กลางฟังก์ชัน (หลัง render ตัวเลขเสร็จแล้ว แต่ก่อนถึงโค้ด bind click)
  //   ผลคือ "ตัวเลขขึ้นแต่กดไม่ได้เลย" เพราะ event listener ไม่เคยถูกผูก
  const totals = (pt.totals && typeof pt.totals === 'object') ? pt.totals : {};
  const headRow = document.getElementById('pipelineHeadRow');
  const tbody = document.getElementById('pipelineBody');
  const tfoot = document.getElementById('pipelineFoot');
  if (!tbody || !tfoot) return;

  if (headRow) {
    var headHtml = '<th class="pl-col-month">' + DBSUN_I18N.month + '</th>';
    groups.forEach(function (g) {
      var color = (STATUS_DEPT_COLORS[g] && STATUS_DEPT_COLORS[g].col)
          || (pt.deptColors && pt.deptColors[g])
          || 'var(--ink)';
      headHtml += '<th data-group="' + escapeHtml(g) + '" style="color:' + escapeHtml(color) + '">' + escapeHtml(g) + '</th>';
    });
    headHtml += '<th class="pl-col-total">' + DBSUN_I18N.total + '</th>';
    headRow.innerHTML = headHtml;
  }

  // Render body rows
  var rowsHtml = '';
  months.forEach(function (r) {
    var cells = '';
    var values = r.values || {};
    groups.forEach(function (d) {
      var v = (values[d] != null) ? parseInt(values[d], 10) || 0 : 0;
      var isEmpty = v === 0;
      if (isEmpty) {
        cells += '<td><span class="pipeline-cell empty">0</span></td>';
      } else {
        cells += '<td><span class="pipeline-cell" data-month="' + escapeHtml(r.month) + '" data-group="' + escapeHtml(d) + '">' + v + '</span></td>';
      }
    });
    var total = (r.total != null) ? r.total : groups.reduce(function (sum, d) {
      return sum + ((values[d] != null) ? parseInt(values[d], 10) || 0 : 0);
    }, 0);
    rowsHtml +=
      '<tr>' +
        '<td class="pl-month">' + escapeHtml(r.label || r.monthLabel || r.month || '-') + '</td>' +
        cells +
        '<td class="pl-total">' + total + '</td>' +
      '</tr>';
  });
  tbody.innerHTML = rowsHtml || (
    '<tr><td colspan="' + (groups.length + 2) + '" class="text-center py-5 text-muted">' + DBSUN_I18N.noData + '</td></tr>'
  );

  // Footer (totals) — คำนวณจากการรวม values ของแต่ละเดือน (ไม่อาศัย pt.totals ที่อาจว่าง)
  //   ★ ใช้ label (monthLabel) เป็นแหล่งความจริง สำหรับแสดงแต่ละเดือน + label จากแต่ละแถว
  var columnTotals = {};
  groups.forEach(function (d) { columnTotals[d] = 0; });
  months.forEach(function (r) {
    var values = r.values || {};
    groups.forEach(function (d) {
      var v = (values[d] != null) ? parseInt(values[d], 10) || 0 : 0;
      columnTotals[d] += v;
    });
  });

  var footCells = '';
  var computedGrandTotal = 0;
  groups.forEach(function (d) {
    var t = columnTotals[d] || 0;
    footCells += '<td>' + t + '</td>';
    computedGrandTotal += t;
  });
  tfoot.innerHTML =
    '<tr>' +
      '<td>รวมทั้งปี (unique)</td>' +
      footCells +
      '<td style="color:var(--c5)">' + (pt.grandTotal != null ? pt.grandTotal : computedGrandTotal) + '</td>' +
    '</tr>';

  // Bind clickable cells → open popup
  tbody.querySelectorAll('.pipeline-cell:not(.empty)').forEach(function (el) {
    el.addEventListener('click', function () {
      var mm    = el.dataset.month;
      var group = el.dataset.group;
      openPipelineModal(mm, group);
    });
  });

  // ★ Render pagination ปุ่ม 1-N (อ่าน totalPages จาก ECDATA2.pipelineTable)
  renderPipelinePagination();
}

//   เมื่อกดปุ่ม → เรียก /dashboard/pipeline?page=N → update ECDATA2.pipelineTable → re-render matrix
var _pipelineCurrentPage = 1;
function renderPipelinePagination() {
  var nav = document.getElementById('pipelinePagination');
  if (!nav) return;
  var pt = (typeof ECDATA2 === 'object' && ECDATA2 && ECDATA2.pipelineTable) || {};
  var totalPages = parseInt(pt.totalPages, 10) || 1;
  // limit ที่ user ขอ — ปุ่ม 1-10 (แต่ถ้า totalPages < 10 ก็แสดงตามที่มี)
  var maxShow = Math.min(totalPages, 10);
  if (pt.currentPage) _pipelineCurrentPage = parseInt(pt.currentPage, 10) || 1;

  var html = '';
  // Prev
  html += '<button type="button" class="pg-btn pg-prev" data-page="' + (_pipelineCurrentPage - 1) + '" '
        + (_pipelineCurrentPage <= 1 ? 'disabled="disabled"' : '') + '><i class="fa-solid fa-chevron-left"></i></button>';
  // Page numbers 1..maxShow
  for (var p = 1; p <= maxShow; p++) {
    var active = (p === _pipelineCurrentPage) ? ' active' : '';
    html += '<button type="button" class="pg-btn' + active + '" data-page="' + p + '">' + p + '</button>';
  }
  if (totalPages > maxShow) {
    html += '<span class="pg-ellipsis">...</span>';
    html += '<button type="button" class="pg-btn" data-page="' + totalPages + '">' + totalPages + '</button>';
  }
  // Next
  html += '<button type="button" class="pg-btn pg-next" data-page="' + (_pipelineCurrentPage + 1) + '" '
        + (_pipelineCurrentPage >= totalPages ? 'disabled="disabled"' : '') + '><i class="fa-solid fa-chevron-right"></i></button>';

  nav.innerHTML = html;
  // Bind clicks
  nav.querySelectorAll('.pg-btn:not([disabled])').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var page = parseInt(btn.dataset.page, 10) || 1;
      if (page < 1 || page > totalPages || page === _pipelineCurrentPage) return;
      fetchPipelinePage(page);
    });
  });
}

// Fetch pipeline data for specific page → update ECDATA2.pipelineTable → re-render
function fetchPipelinePage(page) {
  try {
    // ★ Map page → year: page 1 = current year (2026), page 2 = 2025, page 3 = 2024, ...
    //   formula: year = currentYear - (page - 1)
    //   user requirement: คลิกปุ่ม 1 → เดือนแสดงปี 2026, ปุ่ม 2 → 2025, ปุ่ม 3 → 2024
    var currentYr_var = new Date().getFullYear();
    var yearForPage = currentYr_var - (page - 1);

    var basePath = '';
    var qs = '?year='          + encodeURIComponent(yearForPage)
           + '&month='         + encodeURIComponent((FILTERS && FILTERS.month)         || 'all')
           + '&fromdate='      + encodeURIComponent((FILTERS && FILTERS.fromdate)      || 'all')
           + '&todate='        + encodeURIComponent((FILTERS && FILTERS.todate)        || 'all')
           + '&datebasis='     + encodeURIComponent((FILTERS && FILTERS.datebasis)     || 'contact')
           + '&employee='      + encodeURIComponent((FILTERS && FILTERS.employee)      || 'all')
           + '&chanel='        + encodeURIComponent((FILTERS && FILTERS.chanel)        || 'all')
           + '&country='       + encodeURIComponent((FILTERS && FILTERS.country)       || 'all')
           + '&occupation='    + encodeURIComponent((FILTERS && FILTERS.occupation)    || 'all')
           + '&province='      + encodeURIComponent((FILTERS && FILTERS.province)      || 'all')
           + '&activitygroup=' + encodeURIComponent((FILTERS && FILTERS.activity_group)|| 'all')
           + '&movementtype='  + encodeURIComponent((FILTERS && FILTERS.movementtype)  || 'all')
           + '&page='          + encodeURIComponent(page);
    var url = _sunEndpoint('pipeline', qs);
    console.log('[Dashboard] pipeline page=' + page + ' → year=' + yearForPage + ' → fetch', url);

    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        data = _sunUnwrap(data) || {};
        if (!data || (!data.months && !data.rows)) {
          console.warn('[Dashboard] pipeline page: bad shape', data);
          return;
        }
        if (typeof ECDATA2 !== 'object' || !ECDATA2) { window.ECDATA2 = {}; }
        ECDATA2.pipelineTable = data;
        _pipelineCurrentPage = parseInt(data.currentPage, 10) || page;
        renderPipeline();
      })
      .catch(function (err) { console.error('[Dashboard] pipeline page failed:', err); });
  } catch (e) {
    console.error('[Dashboard] fetchPipelinePage threw:', e);
  }
}

/* ===================================================================
 *  ลูกค้าตามกลุ่มขั้นตอน (Customer-by-step-group)
 *  - อ่านข้อมูลจาก ECDATA2.customerGroup (รูปแบบ รายชื่อลูกค้าแยกตามกลุ่มขั้นตอน.txt)
 *    { currentPage, totalPages, columnName:[...], customerList:[...] }
 *  - 5 คอลั่มน์แรกของ columnName (fixed):
 *      รหัส(code) / ชื่อลูกค้า(name) / อาชีพ(occupation) / ประเทศ(country) /
 *      ผู้รับผิดชอบล่าสุด(latestAssignToName)
 *    ที่เหลือ = กลุ่มขั้นตอน (CS, AN, PLS, LS, FI, LE, CRM) แต่ละกลุ่มแสดง 4 sub-columns:
 *      วันที่เริ่ม(dateIn) / วันที่สิ้นสุด(dateout) / ผู้รับผิดชอบ(assignToName) / วันที่ใช้(dateTotal)
 *    + คอลั่มน์ "รวม" (total)
 * =================================================================== */
var _CSG_FIXED_MAP = ['name', 'code', 'occupation', 'country'];   // ใช้กับ statusByCustomer
var _CSG_SUBS = [
  { key: 'dateIn',    label: 'วันที่เริ่ม' },
  { key: 'dateout',   label: 'วันที่สิ้นสุด' },
  { key: 'dateTotal', label: 'วันที่ใช้' }
];
// ★ เฉพาะแท็บ "ลูกค้าตามกลุ่มขั้นตอน" — 5 fixed + 4 sub-columns (มีคอลั่มน์ผู้รับผิดชอบ)
var _CGRP_FIXED = [
  { keys: ['code'] },
  { keys: ['name'] },
  { keys: ['occupation'] },
  { keys: ['country'] },
  { keys: ['latestAssignToName', 'latestassignToName', 'latestAssignTo', 'latestassignto'] }
];
var _CGRP_SUBS = [
  { keys: ['dateIn'],                      label: 'วันที่เริ่ม' },
  { keys: ['dateout', 'dateOut'],          label: 'วันที่สิ้นสุด' },
  { keys: ['assignToName', 'AssignToName'], label: 'ผู้รับผิดชอบ' },
  { keys: ['dateTotal'],                   label: 'วันที่ใช้' }
];
// resolve ค่าจาก object ตามลำดับ keys ที่เป็นไปได้
function _pickVal(obj, keys) {
  if (!obj) return null;
  for (var i = 0; i < keys.length; i++) {
    var v = obj[keys[i]];
    if (v != null && v !== '') return v;
  }
  return null;
}
//   ประเทศ → country, ผู้รับผิดชอบล่าสุด → latestassignToName
function _fixedFieldKeys(label) {
  var l = String(label || '');
  if (l.indexOf('ติดต่อครั้งแรก') !== -1 || l.indexOf('ติดต่อครั้ง') !== -1)
    return ['firstContact', 'firstcontact', 'first_contact'];
  if (l.indexOf('รหัส') !== -1)   return ['code'];
  if (l.indexOf('ชื่อ') !== -1)   return ['name'];
  if (l.indexOf('อาชีพ') !== -1)  return ['occupation'];
  if (l.indexOf('ประเทศ') !== -1) return ['country'];
  if (l.indexOf('ผู้รับผิดชอบ') !== -1)
    return ['latestAssignToName', 'latestassignToName', 'latestAssignTo', 'latestassignto'];
  return null;   // ไม่ใช่คอลั่มน์ fixed (เป็นกลุ่ม/สถานะ)
}
// ★ นับจำนวนคอลั่มน์ fixed ที่อยู่หน้าสุด (ก่อนคอลั่มน์กลุ่ม/สถานะ) จาก columnName
function _countFixedCols(columnName) {
  var n = 0;
  for (var i = 0; i < columnName.length; i++) {
    if (_fixedFieldKeys(columnName[i]) != null) n++;
    else break;
  }
  return n;
}
var _customerGroupCurrentPage = 1;
var _csgSearchTerm = '';
var _csgSortDir = 'desc';   // ★ ทิศการเรียงตาม total: 'desc' = มาก→น้อย (default), 'asc' = น้อย→มาก

function _csgData() {
  var src = (typeof ECDATA2 === 'object' && ECDATA2 && ECDATA2.customerGroup) || {};
  // รองรับกรณี payload ถูกห่อด้วย { result: {...} }
  if (src && src.result && (src.result.customerList || src.result.columnName)) src = src.result;
  return src || {};
}

function applyCustomerGroupSearch() {
  var inp = document.getElementById('customerGroupSearchInput');
  _csgSearchTerm = inp ? (inp.value || '').trim() : '';
  // ★ ส่งคำค้นหาไปที่ API (server-side search) แล้วเริ่มที่หน้า 1
  fetchCustomerGroupPage(1);
}

function renderCustomerGroup() {
  var data = _csgData();
  var columnName = Array.isArray(data.columnName) && data.columnName.length
      ? data.columnName
      : ['ติดต่อครั้งแรก', 'รหัส', 'ชื่อลูกค้า', 'อาชีพ', 'ประเทศ', 'ผู้รับผิดชอบล่าสุด',
         'CS', 'AN', 'PLS', 'LS', 'FI', 'LE', 'CRM'];
  var list = Array.isArray(data.customerList) ? data.customerList : [];

  // ★ Apply sort (toggle จากปุ่ม customerGroup sort) — เรียงตาม total
  if (_csgSortDir) {
    var _cgDir = (_csgSortDir === 'asc') ? 1 : -1;
    list = list.slice().sort(function (a, b) {
      var na = Number((a && a.total) || 0), nb = Number((b && b.total) || 0);
      return _cgDir * (na - nb);
    });
  }

  // ★ จำนวนคอลั่มน์ fixed คำนวณจาก columnName (รองรับการเพิ่ม/ลดคอลั่มน์จาก API)
  var FIXED_N = _countFixedCols(columnName) || _CGRP_FIXED.length;
  var fixedLabels = columnName.slice(0, FIXED_N);
  var groupKeys   = columnName.slice(FIXED_N);

  // ★ แสดงจำนวนข้อมูลทั้งหมดจาก API (totalRecords)
  var _cgTotalEl = document.getElementById('customerGroupTotalLabel');
  if (_cgTotalEl) {
    var _cgTotal = (data.totalRecords != null) ? data.totalRecords
                 : (Array.isArray(data.customerList) ? data.customerList.length : 0);
    _cgTotalEl.textContent = 'ข้อมูลทั้งหมด : ' + (typeof fmt === 'function' ? fmt(_cgTotal) : _cgTotal);
  }

  var thead = document.getElementById('customerGroupHead');
  var tbody = document.getElementById('customerGroupBody');
  if (!thead || !tbody) return;

  var totalCols = fixedLabels.length + (groupKeys.length * _CGRP_SUBS.length) + 1;

  // ---- thead (2 rows) ----
  var row1 = '';
  fixedLabels.forEach(function (lab, i) {
    row1 += '<th class="csg-fixed" rowspan="2">' + escapeHtml(lab) + '</th>';
  });
  // ★ 01/09/2026 — ย้าย "จำนวนวันรวม" มาต่อจากคอลัมน์ fixed ตัวสุดท้าย (ผู้รับผิดชอบล่าสุด)
  //   ตามที่ user สั่ง — เดิมอยู่ท้ายสุดถัดจากกลุ่มขั้นตอนทั้งหมด
  //   และปักนิ่งไม่ให้เลื่อนซ้าย-ขวา (ดู CSS #customerGroupTable ... .csg-col-total ใน dashboard.xhtml)
  row1 += '<th class="csg-col-total" rowspan="2">จำนวนวันรวม</th>';
  groupKeys.forEach(function (g) {
    var color = (STATUS_DEPT_COLORS[g] && STATUS_DEPT_COLORS[g].col) || 'var(--ink)';
    // ★ ไม่ใส่สีพื้นหลัง — ใช้สีกับตัวอักษรแทน (พื้นหลังเหมือนคอลั่มน์อื่น ๆ)
    row1 += '<th colspan="' + _CGRP_SUBS.length + '" '
          + 'style="color:' + escapeHtml(color) + ';">' + escapeHtml(g) + '</th>';
  });

  var row2 = '';
  groupKeys.forEach(function (g, gi) {
    _CGRP_SUBS.forEach(function (sub, si) {
      var startCls = (si === 0) ? ' csg-sub-start' : '';
      row2 += '<th class="csg-sub' + startCls + '">' + escapeHtml(sub.label) + '</th>';
    });
  });
  thead.innerHTML = '<tr>' + row1 + '</tr><tr>' + row2 + '</tr>';

  // ---- tbody ----
  if (!list.length) {
    tbody.innerHTML = '<tr><td colspan="' + totalCols + '" class="text-center py-5 text-muted">' + DBSUN_I18N.noData + '</td></tr>';
    renderCustomerGroupPagination();
    return;
  }

  var rowsHtml = '';
  list.forEach(function (c) {
    var cells = '';
    // ★ เซลล์ fixed: จับคู่ field ตามป้ายหัวคอลั่มน์ (รหัส→code, ชื่อลูกค้า→name, ติดต่อครั้งแรก→firstContact)
    fixedLabels.forEach(function (lab, idx) {
      var keys = _fixedFieldKeys(lab) || (_CGRP_FIXED[idx] && _CGRP_FIXED[idx].keys) || ['code'];
      var v = _pickVal(c, keys);
      cells += '<td class="csg-fixed">' + escapeHtml(v != null ? v : '-') + '</td>';
    });
    // ★ 01/09/2026 — ย้ายมาต่อจากคอลัมน์ fixed ตัวสุดท้าย ให้ตรงลำดับกับหัวตาราง (ดูคอมเมนต์ที่ thead)
    cells += '<td class="csg-total">' + escapeHtml(c.total != null ? c.total : '-') + '</td>';
    groupKeys.forEach(function (g) {
      var gObj = c[g] || {};
      _CGRP_SUBS.forEach(function (sub, si) {
        var startCls = (si === 0) ? ' csg-grp-start' : '';
        var val = _pickVal(gObj, sub.keys);
        cells += '<td class="csg-grp-cell' + startCls + '">'
              + escapeHtml((val != null && val !== '') ? val : '-') + '</td>';
      });
    });
    rowsHtml += '<tr>' + cells + '</tr>';
  });
  tbody.innerHTML = rowsHtml;

  renderCustomerGroupPagination();
}

function renderCustomerGroupPagination() {
  var nav = document.getElementById('customerGroupPagination');
  if (!nav) return;
  var data = _csgData();
  var totalPages = parseInt(data.totalPages, 10) || 1;
  var maxShow = Math.min(totalPages, 10);
  if (data.currentPage) _customerGroupCurrentPage = parseInt(data.currentPage, 10) || 1;

  var html = '';
  html += '<button type="button" class="pg-btn pg-prev" data-page="' + (_customerGroupCurrentPage - 1) + '" '
        + (_customerGroupCurrentPage <= 1 ? 'disabled="disabled"' : '') + '><i class="fa-solid fa-chevron-left"></i></button>';
  for (var p = 1; p <= maxShow; p++) {
    var active = (p === _customerGroupCurrentPage) ? ' active' : '';
    html += '<button type="button" class="pg-btn' + active + '" data-page="' + p + '">' + p + '</button>';
  }
  if (totalPages > maxShow) {
    html += '<span class="pg-ellipsis">...</span>';
    html += '<button type="button" class="pg-btn" data-page="' + totalPages + '">' + totalPages + '</button>';
  }
  html += '<button type="button" class="pg-btn pg-next" data-page="' + (_customerGroupCurrentPage + 1) + '" '
        + (_customerGroupCurrentPage >= totalPages ? 'disabled="disabled"' : '') + '><i class="fa-solid fa-chevron-right"></i></button>';

  nav.innerHTML = html;
  nav.querySelectorAll('.pg-btn:not([disabled])').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var page = parseInt(btn.dataset.page, 10) || 1;
      if (page < 1 || page > totalPages || page === _customerGroupCurrentPage) return;
      fetchCustomerGroupPage(page);
    });
  });
}

// Fetch customer-by-step-group data for a page → update ECDATA2.customerGroup → re-render
function fetchCustomerGroupPage(page) {
  try {
    var basePath = '';
    var qs = '?year='          + encodeURIComponent((FILTERS && FILTERS.year)           || '2026')
           + '&month='         + encodeURIComponent((FILTERS && FILTERS.month)          || 'all')
           + '&fromdate='      + encodeURIComponent((FILTERS && FILTERS.fromdate)       || 'all')
           + '&todate='        + encodeURIComponent((FILTERS && FILTERS.todate)         || 'all')
           + '&datebasis='     + encodeURIComponent((FILTERS && FILTERS.datebasis)      || 'contact')
           + '&employee='      + encodeURIComponent((FILTERS && FILTERS.employee)       || 'all')
           + '&chanel='        + encodeURIComponent((FILTERS && FILTERS.chanel)         || 'all')
           + '&country='       + encodeURIComponent((FILTERS && FILTERS.country)        || 'all')
           + '&occupation='    + encodeURIComponent((FILTERS && FILTERS.occupation)     || 'all')
           + '&province='      + encodeURIComponent((FILTERS && FILTERS.province)       || 'all')
           + '&activitygroup=' + encodeURIComponent((FILTERS && FILTERS.activity_group) || 'all')
           + '&movementtype='  + encodeURIComponent((FILTERS && FILTERS.movementtype)   || 'all')
           + '&search='        + encodeURIComponent(_csgSearchTerm || '')
           + '&page='          + encodeURIComponent(page)
           + '&perPage=50';    // ★ ตาม curl spec — จำนวนแถวต่อหน้า
    var url = _sunEndpoint('customer_step_groups', qs);
    console.log('[Dashboard] customerGroup page=' + page + ' → fetch', url);

    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        // ★ unwrap envelope จาก direct upstream ({ ..., result: {...} })
        data = _sunUnwrap(data);
        if (typeof ECDATA2 !== 'object' || !ECDATA2) { window.ECDATA2 = {}; }
        ECDATA2.customerGroup = (data && typeof data === 'object') ? data
          : { currentPage: page, totalPages: 1, columnName: [], customerList: [] };
        _customerGroupCurrentPage = parseInt((ECDATA2.customerGroup && ECDATA2.customerGroup.currentPage), 10) || page;
        renderCustomerGroup();
      })
      .catch(function (err) {
        console.error('[Dashboard] customerGroup page failed:', err);
        if (typeof ECDATA2 !== 'object' || !ECDATA2) { window.ECDATA2 = {}; }
        ECDATA2.customerGroup = { currentPage: page, totalPages: 1, columnName: [], customerList: [] };
        _customerGroupCurrentPage = page;
        renderCustomerGroup();
      });
  } catch (e) {
    console.error('[Dashboard] fetchCustomerGroupPage threw:', e);
  }
}

// palette สำหรับหัวคอลั่มน์สถานะ (วนซ้ำตามจำนวน step)
var _SBC_PALETTE = ['#4f7cff', '#00d4a8', '#ffb84d', '#a26bff', '#f01685',
                    '#9C6F63', '#3ad6dd', '#ef4444', '#22c55e', '#f59e0b',
                    '#0ea5e9', '#d946ef'];
var _statusByCustomerCurrentPage = 1;
var _sbcSearchTerm = '';
var _sbcSortDir = 'desc';   // ★ ทิศการเรียงตาม total: 'desc' = มาก→น้อย (default), 'asc' = น้อย→มาก

function _sbcData() {
  var src = (typeof ECDATA2 === 'object' && ECDATA2 && ECDATA2.statusByCustomer) || {};
  if (src && src.result && (src.result.customerList || src.result.columnName)) src = src.result;
  return src || {};
}

function applyStatusByCustomerSearch() {
  var inp = document.getElementById('statusByCustomerSearchInput');
  _sbcSearchTerm = inp ? (inp.value || '').trim() : '';
  // ★ ส่งคำค้นหาไปที่ API (server-side search) แล้วเริ่มที่หน้า 1
  fetchStatusByCustomerPage(1);
}

function renderStatusByCustomer() {
  var data = _sbcData();
  var columnName = Array.isArray(data.columnName) && data.columnName.length
      ? data.columnName
      : ['ชื่อลูกค้า', 'รหัส', 'อาชีพ', 'ประเทศ'];
  var list = Array.isArray(data.customerList) ? data.customerList : [];

  // ★ Apply sort (toggle จากปุ่ม statusByCustomer sort) — เรียงตาม total
  if (_sbcSortDir) {
    var _dir = (_sbcSortDir === 'asc') ? 1 : -1;
    list = list.slice().sort(function (a, b) {
      var na = Number((a && a.total) || 0), nb = Number((b && b.total) || 0);
      return _dir * (na - nb);
    });
  }

  // ★ จำนวนคอลั่มน์ fixed คำนวณจาก columnName (รองรับคอลั่มน์ใหม่ เช่น "ติดต่อครั้งแรก")
  var FIXED_N = _countFixedCols(columnName) || 4;
  var fixedLabels = columnName.slice(0, FIXED_N);
  var stepLabels  = columnName.slice(FIXED_N);           // หัวคอลั่มน์สถานะ (ป้ายชื่อ)
  var stepKeys    = stepLabels.map(function (lab, i) { return 'step' + (i + 1); }); // key ข้อมูล

  // ★ แสดงจำนวนข้อมูลทั้งหมดจาก API (totalRecords)
  var _sbcTotalEl = document.getElementById('statusByCustomerTotalLabel');
  if (_sbcTotalEl) {
    var _sbcTotal = (data.totalRecords != null) ? data.totalRecords
                  : (Array.isArray(data.customerList) ? data.customerList.length : 0);
    _sbcTotalEl.textContent = 'ข้อมูลทั้งหมด : ' + (typeof fmt === 'function' ? fmt(_sbcTotal) : _sbcTotal);
  }

  var thead = document.getElementById('statusByCustomerHead');
  var tbody = document.getElementById('statusByCustomerBody');
  if (!thead || !tbody) return;

  var totalCols = fixedLabels.length + (stepKeys.length * _CGRP_SUBS.length) + 1;

  // ---- thead (2 rows) ----
  var row1 = '';
  fixedLabels.forEach(function (lab) {
    row1 += '<th class="csg-fixed" rowspan="2">' + escapeHtml(lab) + '</th>';
  });
  // ★ 01/09/2026 — ย้าย "จำนวนวันรวม" มาต่อจากคอลัมน์ fixed ตัวสุดท้าย (ประเทศ) ตามที่ user สั่ง
  //   เดิมอยู่ท้ายสุดถัดจากคอลัมน์สถานะทั้งหมด
  //   และปักนิ่งไม่ให้เลื่อนซ้าย-ขวา (ดู CSS #statusByCustomerTable ... .csg-col-total ใน dashboard.xhtml)
  row1 += '<th class="csg-col-total" rowspan="2">จำนวนวันรวม</th>';
  stepLabels.forEach(function (lab, gi) {
    // ★ ไม่ใส่สีพื้นหลัง — ให้หัวคอลั่มน์สถานะมีสไตล์เหมือนคอลั่มน์อื่น ๆ
    row1 += '<th colspan="' + _CGRP_SUBS.length + '">' + escapeHtml(lab) + '</th>';
  });

  var row2 = '';
  stepKeys.forEach(function (k, gi) {
    _CGRP_SUBS.forEach(function (sub, si) {
      var startCls = (si === 0) ? ' csg-sub-start' : '';
      row2 += '<th class="csg-sub' + startCls + '">' + escapeHtml(sub.label) + '</th>';
    });
  });
  thead.innerHTML = '<tr>' + row1 + '</tr><tr>' + row2 + '</tr>';

  // ---- tbody ----
  if (!list.length) {
    tbody.innerHTML = '<tr><td colspan="' + totalCols + '" class="text-center py-5 text-muted">' + DBSUN_I18N.noData + '</td></tr>';
    renderStatusByCustomerPagination();
    return;
  }

  var rowsHtml = '';
  list.forEach(function (c) {
    var cells = '';
    // ★ เซลล์ fixed: จับคู่ field ตามป้ายหัวคอลั่มน์ (ติดต่อครั้งแรก→firstContact, รหัส→code, ชื่อลูกค้า→name)
    fixedLabels.forEach(function (lab, idx) {
      var keys = _fixedFieldKeys(lab) || [(_CSG_FIXED_MAP[idx] || _CSG_FIXED_MAP[0])];
      var v = _pickVal(c, keys);
      cells += '<td class="csg-fixed">' + escapeHtml(v != null ? v : '-') + '</td>';
    });
    // ★ 01/09/2026 — ย้ายมาต่อจากคอลัมน์ fixed ตัวสุดท้าย ให้ตรงลำดับกับหัวตาราง (ดูคอมเมนต์ที่ thead)
    cells += '<td class="csg-total">' + escapeHtml(c.total != null ? c.total : '-') + '</td>';
    stepKeys.forEach(function (k) {
      var gObj = c[k] || {};
      _CGRP_SUBS.forEach(function (sub, si) {
        var startCls = (si === 0) ? ' csg-grp-start' : '';
        var val = _pickVal(gObj, sub.keys);
        cells += '<td class="csg-grp-cell' + startCls + '">'
              + escapeHtml((val != null && val !== '') ? val : '-') + '</td>';
      });
    });
    rowsHtml += '<tr>' + cells + '</tr>';
  });
  tbody.innerHTML = rowsHtml;

  renderStatusByCustomerPagination();
}

function renderStatusByCustomerPagination() {
  var nav = document.getElementById('statusByCustomerPagination');
  if (!nav) return;
  var data = _sbcData();
  var totalPages = parseInt(data.totalPages, 10) || 1;
  var maxShow = Math.min(totalPages, 10);
  if (data.currentPage) _statusByCustomerCurrentPage = parseInt(data.currentPage, 10) || 1;

  var html = '';
  html += '<button type="button" class="pg-btn pg-prev" data-page="' + (_statusByCustomerCurrentPage - 1) + '" '
        + (_statusByCustomerCurrentPage <= 1 ? 'disabled="disabled"' : '') + '><i class="fa-solid fa-chevron-left"></i></button>';
  for (var p = 1; p <= maxShow; p++) {
    var active = (p === _statusByCustomerCurrentPage) ? ' active' : '';
    html += '<button type="button" class="pg-btn' + active + '" data-page="' + p + '">' + p + '</button>';
  }
  if (totalPages > maxShow) {
    html += '<span class="pg-ellipsis">...</span>';
    html += '<button type="button" class="pg-btn" data-page="' + totalPages + '">' + totalPages + '</button>';
  }
  html += '<button type="button" class="pg-btn pg-next" data-page="' + (_statusByCustomerCurrentPage + 1) + '" '
        + (_statusByCustomerCurrentPage >= totalPages ? 'disabled="disabled"' : '') + '><i class="fa-solid fa-chevron-right"></i></button>';

  nav.innerHTML = html;
  nav.querySelectorAll('.pg-btn:not([disabled])').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var page = parseInt(btn.dataset.page, 10) || 1;
      if (page < 1 || page > totalPages || page === _statusByCustomerCurrentPage) return;
      fetchStatusByCustomerPage(page);
    });
  });
}

// Fetch status-by-customer data for a page → update ECDATA2.statusByCustomer → re-render
function fetchStatusByCustomerPage(page) {
  try {
    var basePath = '';
    var qs = '?year='          + encodeURIComponent((FILTERS && FILTERS.year)           || '2026')
           + '&month='         + encodeURIComponent((FILTERS && FILTERS.month)          || 'all')
           + '&fromdate='      + encodeURIComponent((FILTERS && FILTERS.fromdate)       || 'all')
           + '&todate='        + encodeURIComponent((FILTERS && FILTERS.todate)         || 'all')
           + '&datebasis='     + encodeURIComponent((FILTERS && FILTERS.datebasis)      || 'contact')
           + '&employee='      + encodeURIComponent((FILTERS && FILTERS.employee)       || 'all')
           + '&chanel='        + encodeURIComponent((FILTERS && FILTERS.chanel)         || 'all')
           + '&country='       + encodeURIComponent((FILTERS && FILTERS.country)        || 'all')
           + '&occupation='    + encodeURIComponent((FILTERS && FILTERS.occupation)     || 'all')
           + '&province='      + encodeURIComponent((FILTERS && FILTERS.province)       || 'all')
           + '&activitygroup=' + encodeURIComponent((FILTERS && FILTERS.activity_group) || 'all')
           + '&movementtype='  + encodeURIComponent((FILTERS && FILTERS.movementtype)   || 'all')
           + '&search='        + encodeURIComponent(_sbcSearchTerm || '')
           + '&page='          + encodeURIComponent(page)
           + '&perPage=50'      // ★ ตาม curl spec — จำนวนแถวต่อหน้า
           // ★ ค่าจาก dropdown "ขั้นตอน" (multi-select) — 'all' หรือ 'CS01,CS02'
           + '&activitystep='  + encodeURIComponent((typeof _sbcStepSel !== 'undefined' && _sbcStepSel) || 'all');
    var url = _sunEndpoint('customer_status_list', qs);
    console.log('[Dashboard] statusByCustomer page=' + page + ' → fetch', url);

    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        // ★ unwrap envelope จาก direct upstream ({ ..., result: {...} })
        data = _sunUnwrap(data);
        if (typeof ECDATA2 !== 'object' || !ECDATA2) { window.ECDATA2 = {}; }
        ECDATA2.statusByCustomer = (data && typeof data === 'object') ? data
          : { currentPage: page, totalPages: 1, columnName: [], customerList: [] };
        _statusByCustomerCurrentPage = parseInt((ECDATA2.statusByCustomer && ECDATA2.statusByCustomer.currentPage), 10) || page;
        renderStatusByCustomer();
      })
      .catch(function (err) {
        console.error('[Dashboard] statusByCustomer page failed:', err);
        if (typeof ECDATA2 !== 'object' || !ECDATA2) { window.ECDATA2 = {}; }
        ECDATA2.statusByCustomer = { currentPage: page, totalPages: 1, columnName: [], customerList: [] };
        _statusByCustomerCurrentPage = page;
        renderStatusByCustomer();
      });
  } catch (e) {
    console.error('[Dashboard] fetchStatusByCustomerPage threw:', e);
  }
}

let _pipelineCurrentPeople = []; // เก็บ people ปัจจุบันใน modal สำหรับ search

// ★ Thai month abbreviations (1=ม.ค., ..., 12=ธ.ค.)
var _THAI_MONTHS_FULL = ['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน',
                          'กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];

// ★ Pipeline modal context — เก็บ group/year/month/page เพื่อ reuse ตอนเปลี่ยนหน้า
var _pipelineCtx = { group: '', year: '', month: 0, page: 1, totalPages: 1 };

function openPipelineModal(monthKey, group) {
  // ★ monthKey เป็น string "01"-"12" → แปลงเป็น int 1-12 สำหรับส่ง API
  var monthNum = parseInt(monthKey, 10) || 0;
  var monthLabel = (monthNum >= 1 && monthNum <= 12)
      ? _THAI_MONTHS_FULL[monthNum - 1]
      : monthKey;

  // ★ ใช้ "ปี" จาก main pipelinePagination current page
  //   pipeline page 1 → year = currentYear (2026)
  //   pipeline page 2 → year = currentYear-1 (2025)
  //   pipeline page 3 → year = currentYear-2 (2024)
  //   formula: year = currentYear - (_pipelineCurrentPage - 1)
  //   (เหมือนกับ fetchPipelinePage ที่ map page→year)
  var currentYr_var = new Date().getFullYear();
  var pipelinePage = (typeof _pipelineCurrentPage !== 'undefined' && _pipelineCurrentPage > 0)
                     ? _pipelineCurrentPage : 1;
  var yearSel = String(currentYr_var - (pipelinePage - 1));
  console.log('[Dashboard] openPipelineModal — pipelinePage=' + pipelinePage
              + ' → baseYear=' + yearSel);

  // ★ บันทึก context ไว้ใช้ paginate + reset status flag (popup นี้เป็น pipeline mode)
  _pipelineCtx = { group: group, year: yearSel, month: monthNum, page: 1, totalPages: 1 };
  _statusModalContext = false;

  // ★ Set title ใน format "GROUP - เดือน ปี"
  var titleEl = document.getElementById('pipelineModalTitle');
  var subEl   = document.getElementById('pipelineModalSub');
  if (titleEl) titleEl.textContent = group + ' - ' + monthLabel + ' ' + yearSel;
  if (subEl)   subEl.textContent   = 'กำลังโหลดข้อมูล…';

  // Reset search
  _pipelineCurrentPeople = [];
  _pipelineModalRenderer = null;
  var si = document.getElementById('pipelineModalSearch');
  if (si) {
    si.value = '';
    si.placeholder = 'ค้นหาชื่อ / รหัส / ขั้นตอน / ผู้รับผิดชอบ / อาชีพ / ประเทศ...';
  }

  // Loading state — ทั้ง legacy list + tbody
  var list = document.getElementById('pipelineList');
  if (list) list.innerHTML = '<li class="text-muted text-center py-4">กำลังโหลด...</li>';
  var tbody = document.getElementById('pipelineListBody');
  if (tbody) tbody.innerHTML = '<tr><td colspan="9" class="text-muted text-center py-4">กำลังโหลด...</td></tr>';

  // ★ แสดง table popup ซ่อน legacy list
  var listTbl = document.getElementById('pipelineListTable');
  if (listTbl) listTbl.style.display = '';
  if (list) list.style.display = 'none';

  // ★ Reset pagination footer
  var pagEl = document.getElementById('pipelineModalPagination');
  if (pagEl) { pagEl.innerHTML = ''; pagEl.style.display = 'none'; }

  // ★ Show modal ก่อน fetch — แสดงทันที + แสดง loading
  var modal = document.getElementById('pipelineModal');
  if (modal) {
    // ★ ย้าย modal ไปไว้ระดับ body (เหมือน filterModal) — escape ancestor ที่มี transform
    //   (pandora layout) ไม่งั้น position:fixed จะอ้างอิง ancestor นั้นแทน viewport จริง
    //   ทำให้ popup Pipeline ไม่อยู่กลางจอตามที่ user แจ้ง
    _dbHostModalAtBody(modal);
    modal.classList.add('show');
    modal.setAttribute('aria-hidden', 'false');
    tmo(function () { if (si) si.focus(); }, 100);
  }

  // ★ Fetch รายละเอียดหน้า 1
  fetchPipelineDetail(group, yearSel, monthNum, 1);
}

//     (ปีคงที่ตลอดทุกหน้า — จำนวนหน้าจริงมาจาก data.totalPages ที่ API ตอบกลับ)
function fetchPipelineDetail(group, year, monthNum, page) {
  try {
    var basePath = '';
    var pageNum = (page > 0) ? page : 1;

    // ★ ปีคงที่ตาม year ที่ส่งเข้ามา (จาก openPipelineModal) — ไม่เปลี่ยนตาม page อีกต่อไป
    var baseYear = parseInt(year, 10);
    if (!baseYear || isNaN(baseYear)) baseYear = new Date().getFullYear();
    var yearParam = String(baseYear);

    var qs = '?year='          + encodeURIComponent(yearParam)
           + '&month='         + encodeURIComponent(monthNum || 'all')
           + '&group='         + encodeURIComponent(group || 'all')
           + '&employee='      + encodeURIComponent((FILTERS && FILTERS.employee)      || 'all')
           + '&chanel='        + encodeURIComponent((FILTERS && FILTERS.chanel)        || 'all')
           + '&country='       + encodeURIComponent((FILTERS && FILTERS.country)       || 'all')
           + '&occupation='    + encodeURIComponent((FILTERS && FILTERS.occupation)    || 'all')
           + '&province='      + encodeURIComponent((FILTERS && FILTERS.province)      || 'all')
           + '&movementtype='  + encodeURIComponent((FILTERS && FILTERS.movementtype)  || 'all')
           // ★ 24/08/2026 — เพิ่ม datebasis ตามที่ user สั่ง (เดิม endpoint นี้จุดเดียวที่ตกหล่น
           //   ไม่ส่งค่านี้ ทั้งที่ fetchPipelinePage/fetchEmployeePerformanceByGroup ส่งอยู่แล้ว)
           + '&datebasis='     + encodeURIComponent((FILTERS && FILTERS.datebasis)     || 'contact')
           + '&search='
           + '&page='          + encodeURIComponent(pageNum);
    var url = _sunEndpoint('pipeline/detail', qs);
    console.log('[Dashboard] pipeline-detail GET (page=' + pageNum + ', year=' + yearParam + ')', url);

    // Loading state ใน tbody
    var tbodyLoad = document.getElementById('pipelineListBody');
    if (tbodyLoad) tbodyLoad.innerHTML = '<tr><td colspan="9" class="text-muted text-center py-4">กำลังโหลด...</td></tr>';

    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        data = _sunPeopleList(data, group, yearParam, monthNum);
        if (!data || typeof data !== 'object') {
          console.warn('[Dashboard] pipeline-detail: bad shape', data);
          return;
        }
        _pipelineCurrentPeople = data.people || [];
        // ★ Update context — page/totalPages = ค่าจริงจาก server (data.totalPages มาจาก _sunPeopleList)
        var totalPagesReal = (data.totalPages != null) ? (parseInt(data.totalPages, 10) || 1) : 1;
        _pipelineCtx.page = pageNum;
        _pipelineCtx.totalPages = totalPagesReal;

        // ★ Override title + subtitle ด้วยปี/เดือน/กลุ่มจาก context (ปีคงที่ทุกหน้า)
        var titleEl = document.getElementById('pipelineModalTitle');
        var subEl   = document.getElementById('pipelineModalSub');
        var monthLbl = (_pipelineCtx.month >= 1 && _pipelineCtx.month <= 12)
                       ? _THAI_MONTHS_FULL[_pipelineCtx.month - 1] : '';
        if (titleEl) {
          titleEl.textContent = _pipelineCtx.group + ' - ' + monthLbl + ' ' + yearParam;
        }
        if (subEl) {
          var totalRec = (data.totalRecords != null) ? data.totalRecords : (data.count || 0);
          subEl.textContent = totalRec + ' รายชื่อ · ปี ' + yearParam
                            + ' · หน้า ' + pageNum + '/' + totalPagesReal;
        }

        renderPipelineList(_pipelineCurrentPeople);
        // ★ ใช้จำนวนหน้าจริงจาก server (data.totalPages) แทน fixed year-pages เดิม
        renderPipelineModalPagination(pageNum, totalPagesReal, data.totalRecords);
      })
      .catch(function (err) {
        console.error('[Dashboard] pipeline-detail failed:', err);
        var subEl = document.getElementById('pipelineModalSub');
        if (subEl) subEl.textContent = 'โหลดข้อมูลไม่สำเร็จ — ' + (err.message || err);
        var tbodyErr = document.getElementById('pipelineListBody');
        if (tbodyErr) tbodyErr.innerHTML = '<tr><td colspan="9" class="text-muted text-center py-4">โหลดข้อมูลไม่สำเร็จ</td></tr>';
      });
  } catch (e) {
    console.error('[Dashboard] fetchPipelineDetail threw:', e);
  }
}

//   2. Status mode (_statusModalContext=true): pagination ปกติจาก server (within one csCode's records)
function renderPipelineModalPagination(currentPage, totalPagesFromServer, totalRecords) {
  var pagEl = document.getElementById('pipelineModalPagination');
  if (!pagEl) return;
  var p  = parseInt(currentPage, 10) || 1;

  // ★ ใช้ totalPages จริงจาก server เสมอ (ไม่ override ด้วยค่า fixed อีกต่อไป)
  var isStatus = !!_statusModalContext;
  var tp = parseInt(totalPagesFromServer, 10) || 1;

  if (tp <= 1) {
    pagEl.innerHTML = '';
    pagEl.style.display = 'none';
    return;
  }
  pagEl.style.display = 'flex';

  function btn(label, page, opts) {
    opts = opts || {};
    var cls = 'pmp-btn' + (opts.active ? ' active' : '');
    var attr = (opts.disabled ? ' disabled' : '') + ' data-page="' + page + '"';
    var title = opts.title ? ' title="' + opts.title + '"' : '';
    return '<button class="' + cls + '"' + attr + title + ' type="button">' + label + '</button>';
  }

  // ★ Build page list (ellipsis pattern สำหรับ status mode ถ้า pages > 7)
  function pageList(cur, total) {
    if (total <= 7) {
      var arr = [];
      for (var i = 1; i <= total; i++) arr.push(i);
      return arr;
    }
    if (cur <= 4) return [1, 2, 3, 4, 5, '…', total];
    if (cur >= total - 3) return [1, '…', total-4, total-3, total-2, total-1, total];
    return [1, '…', cur - 1, cur, cur + 1, '…', total];
  }

  var html = '';
  if (isStatus) {
    // Status mode: info แบบปกติ
    html += '<span class="pmp-info">รวม ' + (totalRecords || 0) + ' รายการ · หน้า '
          + p + ' / ' + tp + '</span>';
    html += btn('<i class="fa-solid fa-chevron-left"></i>', p - 1, { disabled: p <= 1 });
    pageList(p, tp).forEach(function (it) {
      if (it === '…') {
        html += '<span class="pmp-ellipsis">…</span>';
      } else {
        html += btn(String(it), it, { active: it === p });
      }
    });
    html += btn('<i class="fa-solid fa-chevron-right"></i>', p + 1, { disabled: p >= tp });
  } else {
    // ★ Pipeline mode: pagination ปกติของรายชื่อภายในปีเดิม (ปีคงที่ทุกหน้า) — จำนวนหน้าจริงจาก server
    var yearLabel = parseInt(_pipelineCtx.year, 10) || (new Date().getFullYear());
    html += '<span class="pmp-info">ปี ' + yearLabel + ' · ' + (totalRecords || 0)
          + ' รายการ · หน้า ' + p + ' / ' + tp + '</span>';
    html += btn('<i class="fa-solid fa-chevron-left"></i>', p - 1, { disabled: p <= 1 });
    pageList(p, tp).forEach(function (it) {
      if (it === '…') {
        html += '<span class="pmp-ellipsis">…</span>';
      } else {
        html += btn(String(it), it, { active: it === p });
      }
    });
    html += btn('<i class="fa-solid fa-chevron-right"></i>', p + 1, { disabled: p >= tp });
  }
  pagEl.innerHTML = html;

  // Bind click → fetch หน้าใหม่ตาม mode
  pagEl.querySelectorAll('.pmp-btn').forEach(function (b) {
    if (b.disabled) return;
    b.addEventListener('click', function () {
      var goPage = parseInt(b.dataset.page, 10) || 1;
      if (isStatus) {
        if (goPage === _statusCtx.page) return;
        fetchEmployeeLeads(_statusCtx.group, _statusCtx.csCode, _statusCtx.empName,
                           _statusCtx.type, _statusCtx.year, goPage);
      } else {
        if (goPage === _pipelineCtx.page) return;
        fetchPipelineDetail(_pipelineCtx.group, _pipelineCtx.year, _pipelineCtx.month, goPage);
      }
    });
  });
}

// ★ Sort state for pipeline popup
var _pipelineSortKey = null;     // 'code' | 'name' | 'step' | 'date' | null
var _pipelineSortDir = 'asc';    // 'asc' | 'desc'

function renderPipelineList(people) {
  // ★ Render เป็น table 8 columns: รหัส / ชื่อ / ขั้นตอน / วันค้าง / ผู้รับผิดชอบ / อาชีพ / ประเทศ / วันติดต่อ
  var tbody = document.getElementById('pipelineListBody');
  var legacyList = document.getElementById('pipelineList');
  if (legacyList) legacyList.innerHTML = '';

  if (!tbody) return;

  // ★ คอลัมน์ "วันค้าง" ใช้ตัวแปรต่างกันตาม popup ที่เปิด (header เหมือนเดิม แค่สลับ field ข้อมูล):
  //   - popup "ค้างอยู่ (คน)"        (_statusModalContext=true, type=pending)   → daysPending
  //   - popup "จำนวนลีดที่ทำเสร็จ"    (_statusModalContext=true, type=completed) → daysToComplete
  //   - popup Pipeline (เดือน/กลุ่ม) (_statusModalContext=false)                → daysInStep (เดิม)
  var dayField = 'daysInStep';
  if (_statusModalContext) {
    dayField = (_statusCtx && _statusCtx.type === 'completed') ? 'daysToComplete' : 'daysPending';
  }

  if (!people || people.length === 0) {
    tbody.innerHTML = '<tr><td colspan="9" class="text-muted text-center py-4">ไม่พบรายชื่อที่ตรงกับคำค้นหา</td></tr>';
    _updatePipelineSortIcons();
    return;
  }

  // ★ Apply sort
  var sortedPeople = people.slice();
  if (_pipelineSortKey) {
    var key = _pipelineSortKey;
    var dir = (_pipelineSortDir === 'desc') ? -1 : 1;
    var isDate    = (key === 'date' || key === 'lastContactDate');
    var isNumeric = (key === 'daysInStep');
    // ★ sort key ของ header คอลัมน์ "วันค้าง" ยังชื่อ 'daysInStep' คงที่ (มาจาก HTML data-sort-key)
    //   แต่ต้องอ้างอิงค่าจริงตาม dayField ที่ resolve ไว้ข้างบน ไม่งั้น sort ไม่ตรงกับตัวเลขที่แสดง
    var sortField = isNumeric ? dayField : key;
    sortedPeople.sort(function (a, b) {
      if (isNumeric) {
        var na = Number((a && a[sortField]) || 0);
        var nb = Number((b && b[sortField]) || 0);
        return dir * (na - nb);
      }
      var va = (a && a[key] != null) ? String(a[key]) : '';
      var vb = (b && b[key] != null) ? String(b[key]) : '';
      if (isDate) return dir * va.localeCompare(vb);
      return dir * va.localeCompare(vb, 'th', { numeric: true, sensitivity: 'base' });
    });
  }

  var html = '';
  for (var i = 0; i < sortedPeople.length; i++) {
    var p = sortedPeople[i];
    var dayVal = p[dayField];
    var days = (dayVal != null && dayVal !== '') ? (dayVal + ' วัน') : '-';
    html +=
      '<tr>' +
        '<td class="pl-code-cell">' + escapeHtml(p.code || '-') + '</td>' +
        '<td class="pl-name-cell">' + escapeHtml(p.name || '-') + '</td>' +
        '<td class="pl-step-cell">' + escapeHtml(p.step || '-') + '</td>' +
        '<td class="pl-days-cell">' + escapeHtml(days) + '</td>' +
        '<td class="pl-assigned-cell">' + escapeHtml(p.assignedTo || '-') + '</td>' +
        '<td class="pl-occupation-cell">' + escapeHtml(p.occupation || '-') + '</td>' +
        '<td class="pl-country-cell">' + escapeHtml(p.country || '-') + '</td>' +
        '<td class="pl-date-cell">' + escapeHtml(p.date || '-') + '</td>' +
        '<td class="pl-lastcontact-cell">' + escapeHtml(p.lastContactDate || '-') + '</td>' +
      '</tr>';
  }
  tbody.innerHTML = html;
  _updatePipelineSortIcons();
}

// Helper: update arrows on TH headers based on current sort state
function _updatePipelineSortIcons() {
  var table = document.getElementById('pipelineListTable');
  if (!table) return;
  table.querySelectorAll('thead th').forEach(function (th) {
    th.classList.remove('sort-asc', 'sort-desc');
    if (th.dataset.sortKey === _pipelineSortKey) {
      th.classList.add(_pipelineSortDir === 'desc' ? 'sort-desc' : 'sort-asc');
    }
  });
}

// (STATUS_DEPT_COLORS และ _statusCurrentDept ย้ายไปไว้ด้านบนสุดของ script แล้ว)

function renderStatusKPIs() {
  const wrap = document.getElementById('statusKPIs');
  if (!wrap) return;
  const kpis = (ECDATA3 && ECDATA3.statusKpis) || [];
  let html = '';
  kpis.forEach(function (k) {
    const dc = STATUS_DEPT_COLORS[k.code] || { col: '#4f7cff', shadow: 'rgba(79,124,255,0.3)' };
    const completedText = fmt(k.completed);
    const completedDisplay = String(completedText) === '0' ? '-' : completedText;
    // ★ 01/09/2026 — บรรทัดล่าง (สีแดง) ของทั้ง 2 ฝั่ง เปลี่ยนจาก "เฉลี่ย <ค่าเดิมซ้ำบรรทัดบน>"
    //   มาเป็นค่า SLA จาก API ตามที่ user สั่ง: ซ้าย = slaDriftPending · ขวา = slaDriftCompleted
    //   null (ยังไม่มีข้อมูล SLA) → แสดง "-" เฉย ๆ ไม่ต่อหน่วย "วัน" เพื่อไม่ให้ดูเหมือนค่าจริงเป็น 0
    const slaText = function (v) {
      return (v === null || v === undefined)
        ? '-'
        : (Number(v).toFixed(1) + ' ' + DBSUN_I18N.days);
    };
    // ★ 01/09/2026 — ค่า SLA ของกลุ่ม แสดงมุมขวาบนของการ์ด (แถวเดียวกับ badge) ตามที่ user สั่ง
    //   รูปแบบเหมือนบล็อก "ค้างรวม/ทำเสร็จรวม" คือ ป้ายเล็ก + ตัวเลขใหญ่ (ใช้ class ชุดเดียวกัน)
    //   null (backend ยังไม่ส่งค่ามา) → แสดง "-" เหมือนบรรทัด SLA อื่น
    const slaValue = (k.sla === null || k.sla === undefined) ? '-' : escapeHtml(String(k.sla));
    // ★ ไม่ใช้ Bootstrap col-* wrapper แล้ว — CSS Grid (#statusKPIs) จัดความกว้างเท่ากันเอง
    html +=
      '<div class="status-kpi" style="--sk-col: ' + dc.col + '; --sk-shadow: ' + dc.shadow + ';">' +
        // ★ แถวหัวการ์ด: badge (คอลั่มน์ซ้าย) + SLA (คอลั่มน์ขวา) — ใช้ grid 1fr 1fr ให้ตรงกับ
        //   .status-kpi-cols ด้านล่าง SLA จึงอยู่ตรงกับคอลั่มน์ "ทำเสร็จรวม" พอดี
        '<div class="status-kpi-head">' +
          '<div class="status-kpi-badge">' + escapeHtml(k.code) + '</div>' +
          '<div class="status-kpi-sla">' +
            '<div class="status-kpi-col-label">SLA</div>' +
            '<div class="status-kpi-col-value">' + slaValue + '</div>' +
          '</div>' +
        '</div>' +
        '<div class="status-kpi-cols">' +
          '<div>' +
            '<div class="status-kpi-col-label">' + DBSUN_I18N.totalPending + '</div>' +
            '<div class="status-kpi-col-value">' + fmt(k.pending) + '</div>' +
            '<div class="status-kpi-col-sub">' + DBSUN_I18N.avg + ' ' + ((k.pendingAvg || 0).toFixed(1)) + ' ' + DBSUN_I18N.days + ' ' +
            // ★ 14/10/2026 — เอาหน่วย "วัน" ที่ต่อซ้ำออก: slaText() ต่อหน่วยให้แล้ว และจงใจไม่ต่อเมื่อไม่มีค่า
            //   ของเดิมจึงขึ้น "(SLA 34.0 วัน วัน )" และ "(SLA - วัน )" ทั้งที่ตั้งใจให้ขึ้น "-" เฉย ๆ
            '<span style="color:#C82909">(SLA' + ' ' + slaText(k.slaDriftPending) + ')</span></div>' +
          '</div>' +
          '<div>' +
            '<div class="status-kpi-col-label">' + DBSUN_I18N.totalCompleted + '</div>' +
            '<div class="status-kpi-col-value success">' + completedDisplay + '</div>' +
            '<div class="status-kpi-col-sub">' + DBSUN_I18N.avg + ' ' + ((k.completedAvg || 0).toFixed(1)) + ' ' + DBSUN_I18N.days + ' ' +
            '<span style="color:#C82909">(SLA' + ' ' + slaText(k.slaDriftCompleted) + ')</span></div>' +
            '' +
          '</div>' +
        '</div>' +
      '</div>';
  });
  wrap.innerHTML = html;
}

function statusSlaCell(value) {
  if (value === null || value === undefined || value === '') return '-';
  var num = Number(value);
  if (!isFinite(num)) return '-';
  return '≈ ' + num.toFixed(1) + ' วัน';
}

function renderStatusTable() {
  const tbody = document.getElementById('statusBody');
  if (!tbody) { console.warn('[Status] statusBody element not found'); return; }
  const dept = _statusCurrentDept || 'CS';
  // ★ ถ้ายังไม่เคย fetch จาก API → แสดง loading placeholder แทน mock data
  //   ป้องกัน mock data flash ก่อนข้อมูลจริงจาก API
  if (_statusFetchedKey === null) {
    tbody.innerHTML = '<tr><td colspan="8" class="text-center py-5 text-muted">' +
      '<i class="fa-solid fa-spinner fa-spin" style="margin-right:8px;color:var(--c4);"></i>' +
      DBSUN_I18N.loadingEmployeeData + '</td></tr>';
    return;
  }
  const rawEmployees = (ECDATA3 && ECDATA3.statusEmployees && ECDATA3.statusEmployees[dept]) || [];
  console.log('[Status] renderStatusTable dept=' + dept + ' employees=' + rawEmployees.length + ' sort=' + _statusSortDir);
  if (rawEmployees.length === 0) {
    tbody.innerHTML = '<tr><td colspan="8" class="text-center py-5 text-muted">ไม่มีพนักงานในแผนกนี้</td></tr>';
    return;
  }
  // ★ Sort by emp.total (ลีดทั้งหมด) ตาม _statusSortDir
  //   desc = มาก→น้อย, asc = น้อย→มาก. ใช้ slice() กัน mutate ECDATA3
  var sortMult = (_statusSortDir === 'asc') ? 1 : -1;
  var employees = rawEmployees.slice().sort(function (a, b) {
    var ta = Number((a && a.total) || 0);
    var tb = Number((b && b.total) || 0);
    return (ta - tb) * sortMult;
  });
  let html = '';
  employees.forEach(function (emp, idx) {
    // Master row — 8 cols (ลบ Transition ออก, เพิ่ม SLA drift หลังคอลัมน์เฉลี่ย)
    html +=
      '<tr class="status-row-emp" data-emp-idx="' + idx + '" data-emp-code="' + escapeHtml(emp.code) + '">' +
        '<td><span class="st-toggle-icon">▾</span> ' + escapeHtml(emp.code) + ' ' + escapeHtml(emp.name) + '</td>' +
        '<td class="text-end">' + fmt(emp.total) + '</td>' +
        '<td class="text-end"><span class="status-num-pending" data-dept="' + dept + '" data-emp="' + escapeHtml(emp.name) + '" data-emp-code="' + escapeHtml(emp.code) + '" data-type="pending">' + fmt(emp.pending) + '</span></td>' +
        '<td class="text-end">≈ ' + ((emp.pendingAvg || 0).toFixed(1)) + ' วัน</td>' +
        '<td class="text-end">' + statusSlaCell(emp.slaDriftPending) + '</td>' +
        '<td class="text-end"><span class="status-num-completed" data-dept="' + dept + '" data-emp="' + escapeHtml(emp.name) + '" data-emp-code="' + escapeHtml(emp.code) + '" data-type="completed">' + fmt(emp.completed) + '</span></td>' +
        '<td class="text-end">≈ ' + ((emp.completedAvg || 0).toFixed(1)) + ' วัน</td>' +
        '<td class="text-end">' + statusSlaCell(emp.slaDriftCompleted) + '</td>' +
      '</tr>';
    // Sub-rows (initially hidden — shown when master row expanded) — 8 cols (ลบ Transition)
    emp.steps.forEach(function (s) {
      html +=
        '<tr class="status-row-step" data-parent="' + idx + '" style="display:none;">' +
          '<td>' + escapeHtml(s.name) + '</td>' +
          '<td class="text-end">' + s.total + '</td>' +
          '<td class="text-end status-num-pending">' + s.pending + '</td>' +
          '<td class="text-end">≈ ' + ((s.pendingAvg || 0).toFixed(1)) + ' วัน</td>' +
          '<td class="text-end">' + statusSlaCell(s.slaDriftPending) + '</td>' +
          '<td class="text-end status-num-completed">' + s.completed + '</td>' +
          '<td class="text-end">' + (s.completedAvg == null ? '-' : '≈ ' + Number(s.completedAvg).toFixed(1) + ' วัน') + '</td>' +
          '<td class="text-end">' + statusSlaCell(s.slaDriftCompleted) + '</td>' +
        '</tr>';
    });
  });
  tbody.innerHTML = html;

  // Bind master-row click → toggle
  tbody.querySelectorAll('.status-row-emp').forEach(function (row) {
    row.addEventListener('click', function (e) {
      // Don't toggle when clicking on pending/completed number (popup handler will fire)
      if (e.target.classList.contains('status-num-pending') || e.target.classList.contains('status-num-completed')) return;
      var idx = row.dataset.empIdx;
      var nowExpanded = row.classList.contains('expanded');
      expandStatusRow(tbody, idx, !nowExpanded);
    });
  });

  // Bind popup triggers — pending + completed numbers
  tbody.querySelectorAll('.status-num-pending, .status-num-completed').forEach(function (el) {
    if (!el.dataset.emp) return;  // sub-rows don't have data — skip
    el.addEventListener('click', function (e) {
      e.stopPropagation();
      // ★ ใช้ data-emp-code (csCode) ส่งให้ API + ส่งชื่อไป display
      openStatusPopup(el.dataset.dept, el.dataset.emp, el.dataset.type, el.dataset.empCode);
    });
  });

  // ★ ไม่ auto-expand — แถวขั้นตอนซ่อนไว้จนกว่า user คลิกแถวพนักงาน (ปรับตามคำขอ 17/08 บ่าย)
  //   ข้อดี: เปิดแท็บแล้วไม่ยิง /employee_performance/steps ล่วงหน้าทุกคน — ยิงเฉพาะคนที่กดดู
}

function expandStatusRow(tbody, idx, expand) {
  var master = tbody.querySelector('.status-row-emp[data-emp-idx="' + idx + '"]');
  if (!master) return;
  master.classList.toggle('expanded', expand);

  // ★ Lazy load steps จาก /dashboard/employee_performance/steps API ตอนกดขยายครั้งแรก
  //   ใช้ data-emp-code ที่ฝังบนแถวโดยตรง — เดิม lookup ECDATA3[dept][idx] ซึ่งเป็นลำดับดิบ
  //   จาก API แต่ idx บนแถวเป็นลำดับหลัง sort → ลำดับไม่ตรงกันจะโหลด steps ผิดคน
  if (expand && master.dataset.stepsLoaded !== '1') {
    master.dataset.stepsLoaded = '1';
    var dept = _statusCurrentDept || 'CS';
    var empCode = master.dataset.empCode;
    if (empCode) {
      fetchEmployeeSteps(dept, empCode, idx, tbody);
    }
  }

  tbody.querySelectorAll('.status-row-step[data-parent="' + idx + '"]').forEach(function (r) {
    r.style.display = expand ? '' : 'none';
  });
}

// ★ สร้าง signature ของ filter ปัจจุบัน — ใช้เทียบว่าต้อง refetch หรือไม่
function _buildStatusFilterSig() {
  if (typeof FILTERS !== 'object' || !FILTERS) return 'default';
  return [
    FILTERS.year || 'all',
    FILTERS.month || 'all',
    FILTERS.fromdate || 'all',
    FILTERS.todate || 'all',
    FILTERS.datebasis || 'contact',
    FILTERS.employee || 'all',
    FILTERS.chanel || 'all',
    FILTERS.country || 'all',
    FILTERS.occupation || 'all',
    FILTERS.province || 'all',
    FILTERS.activity_group || 'all',
    FILTERS.movementtype || 'all'
  ].join('|');
}

function fetchEmployeePerformanceByGroup(group) {
  try {
    var basePath = '';
    var qs = '?year='          + encodeURIComponent((FILTERS && FILTERS.year)          || 'all')
           + '&group='         + encodeURIComponent(group || 'CS')
           + '&month='         + encodeURIComponent((FILTERS && FILTERS.month)         || 'all')
           + '&fromdate='      + encodeURIComponent((FILTERS && FILTERS.fromdate)      || 'all')
           + '&todate='        + encodeURIComponent((FILTERS && FILTERS.todate)        || 'all')
           + '&datebasis='     + encodeURIComponent((FILTERS && FILTERS.datebasis)     || 'contact')
           + '&employee='      + encodeURIComponent((FILTERS && FILTERS.employee)      || 'all')
           + '&chanel='        + encodeURIComponent((FILTERS && FILTERS.chanel)        || 'all')
           + '&country='       + encodeURIComponent((FILTERS && FILTERS.country)       || 'all')
           + '&occupation='    + encodeURIComponent((FILTERS && FILTERS.occupation)    || 'all')
           + '&province='      + encodeURIComponent((FILTERS && FILTERS.province)      || 'all')
           + '&movementtype='  + encodeURIComponent((FILTERS && FILTERS.movementtype)  || 'all')
           + '&activitygroup=' + encodeURIComponent((FILTERS && FILTERS.activity_group)|| 'all')
           + '&includeBlocked=' + (_statusIncludeBlocked ? 'true' : 'false');
    var url = _sunEndpoint('employee_performance', qs);
    console.log('[Dashboard] employee-performance GET (group=' + group + ')', url);

    // Show loading state ในตาราง
    var tbody = document.getElementById('statusBody');
    if (tbody) tbody.innerHTML = '<tr><td colspan="8" class="text-center py-5 text-muted">กำลังโหลด...</td></tr>';

    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        data = _sunEmployeePerformance(data, group);
        if (!data || typeof data !== 'object') {
          console.warn('[Dashboard] employee-performance: bad shape', data);
          return;
        }
        // Merge into ECDATA3.statusEmployees — ใช้ bucket ของ dept ที่ขอ
        if (typeof ECDATA3 !== 'object' || !ECDATA3) { window.ECDATA3 = {}; }
        if (!ECDATA3.statusEmployees) ECDATA3.statusEmployees = {};
        if (data[group] && Array.isArray(data[group])) {
          ECDATA3.statusEmployees[group] = data[group];
        } else {
          // ถ้า API คืน array เปล่าใต้ key ที่ขอ → set เป็น []
          ECDATA3.statusEmployees[group] = [];
        }
        // ★ Mark fetched key เป็น "group:filterSig" → renderStatusTable จะแสดงข้อมูลจริง
        _statusFetchedKey = group + ':' + _buildStatusFilterSig();
        if (typeof renderStatusTable === 'function') renderStatusTable();
      })
      .catch(function (err) {
        console.error('[Dashboard] employee-performance failed:', err);
        var tbody = document.getElementById('statusBody');
        if (tbody) tbody.innerHTML = '<tr><td colspan="8" class="text-center py-5 text-muted">โหลดข้อมูลไม่สำเร็จ — ' + (err.message || err) + '</td></tr>';
      });
  } catch (e) {
    console.error('[Dashboard] fetchEmployeePerformanceByGroup threw:', e);
  }
}

// ★ Fetch ขั้นตอนย่อยของพนักงานคนนี้ → inject เป็น sub-rows ใต้ master row
function fetchEmployeeSteps(group, csCode, idx, tbody) {
  try {
    var basePath = '';
    var qs = '?year='          + encodeURIComponent((FILTERS && FILTERS.year)          || 'all')
           + '&group='         + encodeURIComponent(group)
           + '&employeeCode='  + encodeURIComponent(csCode)
           + '&datebasis='     + encodeURIComponent((FILTERS && FILTERS.datebasis)     || 'contact')
           + '&month='         + encodeURIComponent((FILTERS && FILTERS.month)         || 'all')
           + '&fromdate='      + encodeURIComponent((FILTERS && FILTERS.fromdate)      || 'all')
           + '&todate='        + encodeURIComponent((FILTERS && FILTERS.todate)        || 'all')
           + '&employee='      + encodeURIComponent((FILTERS && FILTERS.employee)      || 'all')
           + '&chanel='        + encodeURIComponent((FILTERS && FILTERS.chanel)        || 'all')
           + '&country='       + encodeURIComponent((FILTERS && FILTERS.country)       || 'all')
           + '&occupation='    + encodeURIComponent((FILTERS && FILTERS.occupation)    || 'all')
           + '&province='      + encodeURIComponent((FILTERS && FILTERS.province)      || 'all')
           + '&activitygroup=' + encodeURIComponent((FILTERS && FILTERS.activity_group)|| 'all')
           + '&movementtype='  + encodeURIComponent((FILTERS && FILTERS.movementtype)  || 'all')
           + '&includeBlocked=' + (_statusIncludeBlocked ? 'true' : 'false');
    // ★ URL ตรงตาม external API path: /dashboard/employee_performance/steps
    //   (servlet mapping มี alias /dashboard/employee-steps ด้วย — backward compat)
    var url = _sunEndpoint('employee_performance/steps', qs);
    console.log('[Dashboard] employee_performance/steps GET (group=' + group + ', csCode=' + csCode + ')', url);

    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (steps) {
        steps = _sunEmployeeSteps(steps);
        if (!Array.isArray(steps)) steps = [];
        // ★ Update steps ใน cache — หาโดย code (idx บนแถวเป็นลำดับหลัง sort
        //   แต่ array ใน ECDATA3 เป็นลำดับดิบจาก API — ใช้ idx ตรงๆ จะเขียนผิดคน)
        if (ECDATA3 && ECDATA3.statusEmployees && ECDATA3.statusEmployees[group]) {
          var empArr = ECDATA3.statusEmployees[group];
          for (var k = 0; k < empArr.length; k++) {
            if (empArr[k] && empArr[k].code === csCode) { empArr[k].steps = steps; break; }
          }
        }
        // Append step rows AFTER master row + before next master row
        var master = tbody.querySelector('.status-row-emp[data-emp-idx="' + idx + '"]');
        if (!master) return;
        // Remove any existing step rows for this idx
        tbody.querySelectorAll('.status-row-step[data-parent="' + idx + '"]').forEach(function (r) { r.remove(); });
        // Build new step rows
        var stepHtml = '';
        steps.forEach(function (s) {
          stepHtml +=
            '<tr class="status-row-step" data-parent="' + idx + '">' +
              '<td>' + escapeHtml(s.name || '-') + '</td>' +
              '<td class="text-end">' + (s.total != null ? s.total : '-') + '</td>' +
              '<td class="text-end status-num-pending">' + (s.pending != null ? s.pending : '-') + '</td>' +
              '<td class="text-end">≈ ' + Number(s.pendingAvg || 0).toFixed(1) + ' วัน</td>' +
              '<td class="text-end">' + statusSlaCell(s.slaDriftPending) + '</td>' +
              '<td class="text-end status-num-completed">' + (s.completed != null ? s.completed : '-') + '</td>' +
              '<td class="text-end">' + (s.completedAvg == null || s.completedAvg === 0 ? '-' : '≈ ' + Number(s.completedAvg).toFixed(1) + ' วัน') + '</td>' +
              '<td class="text-end">' + statusSlaCell(s.slaDriftCompleted) + '</td>' +
            '</tr>';
        });
        if (stepHtml) {
          master.insertAdjacentHTML('afterend', stepHtml);
        }
      })
      .catch(function (err) {
        console.error('[Dashboard] employee_performance/steps failed:', err);
        // unlock so user can retry
        var master = tbody.querySelector('.status-row-emp[data-emp-idx="' + idx + '"]');
        if (master) master.dataset.stepsLoaded = '0';
      });
  } catch (e) {
    console.error('[Dashboard] fetchEmployeeSteps threw:', e);
  }
}

// ★ Status popup context — สำหรับ pagination (ผู้ใช้กดเปลี่ยนหน้าใน popup → fetch ใหม่)
var _statusCtx = { group: '', csCode: '', empName: '', type: 'pending', year: '', page: 1, totalPages: 1 };
// ★ Flag: บอกว่า popup ปัจจุบันเป็น "status" mode (ใช้ใน renderPipelineModalPagination)
var _statusModalContext = false;

function openStatusPopup(dept, emp, type, empCode) {
  // ★ Fetch: /dashboard/employee-leads?type=pending|completed&group=dept&search=empCode&page=N
  //   - type === 'pending'   → /employee_performance/pending_list
  //   - type === 'completed' → /employee_performance/completed_list
  //   ★ ใช้ table 8 columns เหมือน pipeline popup (renderPipelineList) + pagination
  var typeStr = (type === 'completed') ? 'completed' : 'pending';
  var titleEl = document.getElementById('pipelineModalTitle');
  var subEl   = document.getElementById('pipelineModalSub');
  var si      = document.getElementById('pipelineModalSearch');

  var yearSel = (typeof FILTERS !== 'undefined' && FILTERS.year && FILTERS.year !== 'all')
                ? FILTERS.year : String(new Date().getFullYear());
  var typeLabel = (typeStr === 'completed') ? 'ทำต่อแล้ว' : 'ค้างทำ';
  if (titleEl) titleEl.textContent = (emp || empCode || '-') + ' (' + (empCode || '') + ')';
  if (subEl)   subEl.textContent   = typeLabel + ' (' + dept + ') · กำลังโหลด… · ปี ' + yearSel;
  if (si) {
    si.value = '';
    si.placeholder = 'ค้นหาชื่อ / รหัส / ขั้นตอน / ผู้รับผิดชอบ / อาชีพ / ประเทศ...';
  }

  // ★ Context สำหรับ pagination (ใช้เปลี่ยนหน้า + reuse args)
  _statusCtx = { group: dept, csCode: empCode, empName: emp, type: typeStr,
                 year: yearSel, page: 1, totalPages: 1 };
  _statusModalContext = true;

  // ★ ใช้ table popup (renderPipelineList) แทน list popup
  _pipelineCurrentPeople = [];
  _pipelineModalRenderer = renderPipelineList;

  // ซ่อน legacy list, แสดง table
  var legacyList = document.getElementById('pipelineList');
  if (legacyList) { legacyList.innerHTML = ''; legacyList.style.display = 'none'; }
  var listTbl = document.getElementById('pipelineListTable');
  if (listTbl) listTbl.style.display = '';

  // ★ Loading state ใน tbody
  var tbody = document.getElementById('pipelineListBody');
  if (tbody) tbody.innerHTML = '<tr><td colspan="9" class="text-muted text-center py-4">กำลังโหลด...</td></tr>';

  // ★ Reset pagination footer
  var pagEl = document.getElementById('pipelineModalPagination');
  if (pagEl) { pagEl.innerHTML = ''; pagEl.style.display = 'none'; }

  // Show modal
  var modal = document.getElementById('pipelineModal');
  if (modal) {
    // ★ ย้าย modal ไปไว้ระดับ body (เหมือน filterModal) — escape ancestor ที่มี transform
    //   (pandora layout) ไม่งั้น position:fixed จะอ้างอิง ancestor นั้นแทน viewport จริง
    //   ทำให้ popup สถานะตามกลุ่มขั้นตอน ไม่อยู่กลางจอตามที่ user แจ้ง
    _dbHostModalAtBody(modal);
    modal.classList.add('show');
    modal.setAttribute('aria-hidden', 'false');
    tmo(function () { if (si) si.focus(); }, 100);
  }

  // Fetch leads page 1
  fetchEmployeeLeads(dept, empCode, emp, typeStr, yearSel, 1);
}

// Helper — fetch + render employee leads (pending/completed) ใน popup + pagination
function fetchEmployeeLeads(group, csCode, empName, type, yearSel, page) {
  try {
    var basePath = '';
    var pageNum = (page > 0) ? page : 1;
    var endpoint = (type === 'completed') ? 'employee_performance/completed_list' : 'employee_performance/pending_list';
    // ★ search กลับไปเป็นค่าว่างเสมอ (ไม่กรองด้วยชื่อ/รหัส) — ว่าง → ไม่ส่ง param search ไปเลย
    //   (เดิมเคยส่ง csCode แล้วเปลี่ยนเป็น empName — ตอนนี้เลิกส่งค่าใดๆ ใน search ทั้ง 2 เส้น)
    var searchVal = '';
    var qs = '?year='          + encodeURIComponent(yearSel || (FILTERS && FILTERS.year) || 'all')
           + '&group='         + encodeURIComponent(group  || 'CS')
           + (searchVal !== '' ? '&search=' + encodeURIComponent(searchVal) : '')
           + '&page='          + encodeURIComponent(pageNum)
           + '&perPage='       + encodeURIComponent('50')
           + '&datebasis='     + encodeURIComponent((FILTERS && FILTERS.datebasis)     || 'contact')
           + '&month='         + encodeURIComponent((FILTERS && FILTERS.month)         || 'all')
           + '&fromdate='      + encodeURIComponent((FILTERS && FILTERS.fromdate)      || 'all')
           + '&todate='        + encodeURIComponent((FILTERS && FILTERS.todate)        || 'all')
           // ★ employee = รหัสพนักงาน (csCode) เจ้าของแถวที่เปิด popup — ไม่ใช่ FILTERS.employee
           //   ของ header อีกต่อไป (popup นี้ผูกกับพนักงานคนเดียวเสมอ ต้อง scope ให้ตรงคนนั้น)
           + '&employee='      + encodeURIComponent(csCode || 'all')
           + '&chanel='        + encodeURIComponent((FILTERS && FILTERS.chanel)        || 'all')
           + '&country='       + encodeURIComponent((FILTERS && FILTERS.country)       || 'all')
           + '&occupation='    + encodeURIComponent((FILTERS && FILTERS.occupation)    || 'all')
           + '&province='      + encodeURIComponent((FILTERS && FILTERS.province)      || 'all')
           + '&movementtype='  + encodeURIComponent((FILTERS && FILTERS.movementtype)  || 'all')
           + '&includeBlocked=' + (_statusIncludeBlocked ? 'true' : 'false');
    // ★ เรียก endpoint ที่ถูกต้องตาม type (pending_list / completed_list)
    var url = _sunEndpoint(endpoint, qs);
    console.log('[Dashboard] employee-leads GET (type=' + type + ', group=' + group
                + ', csCode=' + csCode + ', page=' + pageNum + ')', url);

    // Loading state
    var tbodyLoad = document.getElementById('pipelineListBody');
    if (tbodyLoad) tbodyLoad.innerHTML = '<tr><td colspan="9" class="text-muted text-center py-4">กำลังโหลด...</td></tr>';

    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        data = _sunPeopleList(data, group, yearSel, 'all');
        if (!data || typeof data !== 'object') {
          console.warn('[Dashboard] employee-leads: bad shape', data);
          return;
        }
        _pipelineCurrentPeople = data.people || [];
        // Update context
        _statusCtx.page       = data.currentPage || pageNum;
        _statusCtx.totalPages = data.totalPages  || 1;

        var titleEl = document.getElementById('pipelineModalTitle');
        var subEl   = document.getElementById('pipelineModalSub');
        var typeLabel = (type === 'completed') ? 'ทำต่อแล้ว' : 'ค้างทำ';
        var totalRec = (data.totalRecords != null) ? data.totalRecords : (data.count || 0);
        if (titleEl) titleEl.textContent = (empName || csCode || '-') + ' (' + (csCode || '') + ')';
        if (subEl) {
          subEl.textContent = typeLabel + ' (' + group + ') · ' + totalRec + ' คน · ปี ' + (yearSel || '-')
                            + (data.totalPages > 1 ? ' · หน้า ' + (data.currentPage || pageNum)
                                                     + '/' + data.totalPages : '');
        }
        renderPipelineList(_pipelineCurrentPeople);
        // ★ Use server pagination (within one csCode's records, NOT year-pages)
        renderPipelineModalPagination(data.currentPage || pageNum, data.totalPages || 1, totalRec);
      })
      .catch(function (err) {
        console.error('[Dashboard] employee-leads failed:', err);
        var subEl = document.getElementById('pipelineModalSub');
        if (subEl) subEl.textContent = 'โหลดข้อมูลไม่สำเร็จ — ' + (err.message || err);
        var tbodyErr = document.getElementById('pipelineListBody');
        if (tbodyErr) tbodyErr.innerHTML = '<tr><td colspan="9" class="text-muted text-center py-4">โหลดข้อมูลไม่สำเร็จ</td></tr>';
      });
  } catch (e) {
    console.error('[Dashboard] fetchEmployeeLeads threw:', e);
  }
}

function renderStatusPopupList(people) {
  var list = document.getElementById('pipelineList');
  if (!list) return;
  // ★ ทำให้แน่ใจว่า list แสดง และ table popup ซ่อน
  list.style.display = '';
  var tbl = document.getElementById('pipelineListTable');
  if (tbl) tbl.style.display = 'none';

  if (!people || people.length === 0) {
    list.innerHTML = '<li class="text-muted text-center py-4">ไม่พบรายชื่อ</li>';
    return;
  }
  var html = '';
  for (var i = 0; i < people.length; i++) {
    var p = people[i];
    // ★ ใช้ field จาก API: name, code, group/badge, info, infoOk
    var badgeText  = p.badge || p.group || '';
    var badgeLower = (p.badgeLower || (badgeText || 'cs')).toLowerCase();
    var badgeCls   = 'pl-step-badge pl-step-' + badgeLower;
    var info       = p.info || '';
    var infoCls    = 'pl-info ' + (p.infoOk ? 'ok' : 'warn');
    var iconHtml   = p.infoOk
        ? '<i class="fa-solid fa-circle-check" style="margin-right:4px;"></i>'
        : '<i class="fa-solid fa-hourglass-half" style="margin-right:4px;color:#d68910;"></i>';
    html +=
      '<li class="status-popup-row">' +
        '<div style="display:flex; flex-direction:column; flex:1; min-width:0;">' +
          '<span class="pl-name">' + escapeHtml(p.name || '-') + '</span>' +
          '<span class="pl-code-sub">' + escapeHtml(p.code || '-') + '</span>' +
        '</div>' +
        '<span class="' + badgeCls + '">' + escapeHtml(badgeText) + '</span>' +
        '<span class="' + infoCls + '">' + iconHtml + escapeHtml(info) + '</span>' +
      '</li>';
  }
  list.innerHTML = html;
}

// LEADS_PAGE_SIZE, _leadsTablePage, _leadsTableSearch ย้ายไปด้านบนสุดของ script แล้ว

function renderLeadsTable() {
  // ★ Server-paginated — ECDATA3.leadsTable มี rows ของหน้าปัจจุบัน (20 rows)
  //   + currentPage + totalPages จาก API
  const lt = (ECDATA3 && ECDATA3.leadsTable) || {};
  const rows = lt.rows || [];
  const totalDisplay = lt.totalRows || rows.length;
  const currentPage = lt.currentPage || _leadsTablePage || 1;
  const totalPages  = lt.totalPages  || 1;
  _leadsTablePage = currentPage;

  // ★ Client-side search filter — กรองเฉพาะ rows ของหน้าปัจจุบัน
  //   (ถ้าต้องการ search ครอบทั้ง dataset → ต้องส่ง search ไป API ด้วย)
  const q = _leadsTableSearch.trim().toLowerCase();
  const filtered = q
    ? rows.filter(function (r) {
        const hay = ((r.name||'') + ' ' + (r.code||'') + ' ' + (r.country||'') + ' ' +
                     (r.job||'') + ' ' + (r.cs||'') + ' ' + (r.latest_assigned||'')).toLowerCase();
        return hay.indexOf(q) >= 0;
      })
    : rows;

  // Counts (top right shows total, near search shows filtered/page)
  const topCount = document.getElementById('leadsTableCountTop');
  const filCount = document.getElementById('leadsTableCountFiltered');
  if (topCount) topCount.textContent = totalDisplay;
  if (filCount) filCount.textContent = q ? filtered.length : totalDisplay;
  // ★ Update "ข้อมูลทั้งหมด - N" label ด้วย totalRecords
  const leadsTotalEl = document.getElementById('leadsTotalLabel');
  if (leadsTotalEl) {
    leadsTotalEl.textContent = 'ข้อมูลทั้งหมด ' + fmt(totalDisplay);
  }

  // Render rows
  const tbody = document.getElementById('leadsTableBody');
  if (!tbody) return;
  if (filtered.length === 0) {
    tbody.innerHTML = '<tr><td colspan="13" class="text-center py-5 text-muted">ไม่พบรายการ</td></tr>';
  } else {
    let html = '';
    filtered.forEach(function (r, idx) {
      const groupCls = 'lt-group-pill group-' + (r.group || 'cs').toLowerCase();
      const code = r.code || '';
      // ★ Main row — 13 columns: วันติดต่อ / รหัส / ชื่อ / ประเทศ / อาชีพ / แหล่งที่มา / CS /
      //   วันเก็บเงิน / กลุ่ม / ขั้นตอนล่าสุด / ผู้รับผิดชอบล่าสุด / วันที่ติดต่อล่าสุด / ตำแหน่งงาน
      html +=
        '<tr class="lt-main-row" data-lead-code="' + escapeHtml(code) + '" data-lead-idx="' + idx + '">' +
          '<td>' + escapeHtml(r.contact_date || '-') + '</td>' +
          '<td style="font-weight:600;">' + escapeHtml(code || '-') + '</td>' +
          '<td>' + escapeHtml(r.name || '-') + '</td>' +
          '<td>' + escapeHtml(r.country || '-') + '</td>' +
          '<td>' + escapeHtml(r.job || '-') + '</td>' +                       // ★ อาชีพ (แทนที่ จังหวัด)
          '<td>' + escapeHtml(r.source || '-') + '</td>' +
          '<td>' + escapeHtml(r.cs || '-') + '</td>' +
          '<td>' + escapeHtml(r.payment_date || '-') + '</td>' +
          '<td><span class="' + groupCls + '">' + escapeHtml(r.group || '-') + '</span></td>' +
          '<td>' + escapeHtml(r.last_step || '-') + '</td>' +
          '<td>' + escapeHtml(r.latest_assigned || '-') + '</td>' +           // ★ ผู้รับผิดชอบล่าสุด
          '<td>' + escapeHtml(r.latest_contact_date || '-') + '</td>' +       // ★ วันที่ติดต่อล่าสุด
          '<td>' + escapeHtml(r.position || '-') + '</td>' +
        '</tr>' +
      // ★ Detail row — hidden by default, shown on expand
        '<tr class="lt-detail-row" data-detail-for="' + idx + '" style="display:none;">' +
          '<td colspan="13">' +
            '<div class="lt-detail-wrap" data-detail-body="' + idx + '">' +
              '<div class="lt-timeline-loading">กำลังโหลด...</div>' +
            '</div>' +
          '</td>' +
        '</tr>';
    });
    tbody.innerHTML = html;

    // ★ Bind click on main rows → expand/collapse + lazy fetch
    tbody.querySelectorAll('.lt-main-row').forEach(function (row) {
      row.addEventListener('click', function () {
        var idx = row.dataset.leadIdx;
        var code = row.dataset.leadCode;
        toggleLeadDetail(row, idx, code);
      });
    });
  }

  // Render pagination (server-driven totalPages)
  renderLeadsPagination(totalPages);
}

// ★ Toggle expand/collapse detail row + lazy fetch timeline ครั้งแรก
function toggleLeadDetail(mainRow, idx, prospectCode) {
  if (!mainRow) return;
  var detailRow = document.querySelector('#leadsTableBody tr.lt-detail-row[data-detail-for="' + idx + '"]');
  if (!detailRow) return;
  var nowExpanded = mainRow.classList.contains('expanded');
  mainRow.classList.toggle('expanded', !nowExpanded);
  detailRow.style.display = nowExpanded ? 'none' : '';
  // ★ Lazy fetch — fetch ครั้งแรกตอน expand
  if (!nowExpanded && detailRow.dataset.loaded !== '1') {
    detailRow.dataset.loaded = '1';
    if (prospectCode && prospectCode !== '-' && prospectCode !== '') {
      fetchLeadDetail(prospectCode, idx);
    } else {
      var body = document.querySelector('[data-detail-body="' + idx + '"]');
      if (body) body.innerHTML = '<div class="lt-timeline-empty">ไม่มีรหัสลีดสำหรับโหลด timeline</div>';
    }
  }
}

// ★ Fetch lead_list/detail → render timeline table
function fetchLeadDetail(prospectCode, idx) {
  try {
    var basePath = '';
    var url = _sunEndpoint('lead_list/detail', '?prospectCode=' + encodeURIComponent(prospectCode));
    console.log('[Dashboard] lead-detail GET (prospectCode=' + prospectCode + ')', url);
    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        data = _sunLeadDetail(data, prospectCode);
        renderLeadDetail(idx, prospectCode, data);
      })
      .catch(function (err) {
        console.error('[Dashboard] lead-detail failed:', err);
        var body = document.querySelector('[data-detail-body="' + idx + '"]');
        if (body) body.innerHTML = '<div class="lt-timeline-error">โหลด timeline ไม่สำเร็จ — ' + escapeHtml(err.message || String(err)) + '</div>';
      });
  } catch (e) {
    console.error('[Dashboard] fetchLeadDetail threw:', e);
  }
}

// ★ Render timeline ของลีด — table มี 6 คอลั่ม: วันติดต่อ, รหัสtxn, กลุ่ม, ขั้นตอน, ผู้รับผิดชอบ, วันเปลี่ยนสถานะ
function renderLeadDetail(idx, prospectCode, data) {
  var body = document.querySelector('[data-detail-body="' + idx + '"]');
  if (!body) return;
  var timeline = (data && data.timeline) || [];
  var count = (data && data.count) || timeline.length;

  var header =
    '<div class="lt-detail-header">' +
      '<i class="fa-solid fa-clock-rotate-left" style="color:var(--c4);"></i>' +
      '<span>ประวัติขั้นตอน ลีด</span>' +
      '<span class="lt-detail-code">' + escapeHtml(prospectCode) + '</span>' +
      '<span class="lt-detail-count">' + count + ' รายการ</span>' +
    '</div>';

  if (!timeline.length) {
    body.innerHTML = header + '<div class="lt-timeline-empty">ไม่พบประวัติขั้นตอน</div>';
    return;
  }

  var html = header +
    '<table class="lt-timeline-table">' +
      '<thead><tr>' +
        '<th>วันติดต่อ</th>' +
        '<th>รหัส txn</th>' +
        '<th>กลุ่ม</th>' +
        '<th>ขั้นตอน</th>' +
        '<th>ผู้รับผิดชอบ</th>' +
        '<th>วันเปลี่ยนสถานะ</th>' +
      '</tr></thead><tbody>';

  for (var i = 0; i < timeline.length; i++) {
    var t = timeline[i];
    var grpCls = 'lt-group-pill group-' + ((t.group || 'cs') + '').toLowerCase();
    html +=
      '<tr>' +
        '<td>' + escapeHtml(t.contact_date || '-') + '</td>' +
        '<td style="font-family:ui-monospace,monospace;font-size:11.5px;">' + escapeHtml(t.lead_txno || '-') + '</td>' +
        '<td><span class="' + grpCls + '">' + escapeHtml(t.group || '-') + '</span></td>' +
        '<td>' + escapeHtml(t.step || '-') + '</td>' +
        '<td>' + escapeHtml(t.assigned_to || '-') + '</td>' +
        '<td>' + escapeHtml(t.change_date || '-') + '</td>' +
      '</tr>';
  }
  html += '</tbody></table>';
  body.innerHTML = html;
}

// ★ Global keyword สำหรับช่องค้นหา "ตารางลีดทั้งหมด" → ส่งเข้า lead_list API param search
var _leadsSearchKeyword = '';

// เรียกเมื่อกดปุ่ม "ค้นหา" หรือ Enter ในช่อง input — reset เป็นหน้า 1 + fetch ใหม่
function applyLeadsSearch() {
  var inp = document.getElementById('leadsSearchInput');
  _leadsSearchKeyword = inp ? (inp.value || '').trim() : '';
  fetchLeadsPage(1);
}

function fetchLeadsPage(page) {
  try {
    var basePath = '';
    var qs = '?year='          + encodeURIComponent((FILTERS && FILTERS.year)          || 'all')
           + '&month='         + encodeURIComponent((FILTERS && FILTERS.month)         || 'all')
           + '&fromdate='      + encodeURIComponent((FILTERS && FILTERS.fromdate)      || 'all')
           + '&todate='        + encodeURIComponent((FILTERS && FILTERS.todate)        || 'all')
           + '&datebasis='     + encodeURIComponent((FILTERS && FILTERS.datebasis)     || 'contact')
           + '&search='        + encodeURIComponent(_leadsSearchKeyword || '')
           + '&page='          + encodeURIComponent(page || 1)
           + '&perPage='       + encodeURIComponent('20')
           + '&employee='      + encodeURIComponent((FILTERS && FILTERS.employee)      || 'all')
           + '&chanel='        + encodeURIComponent((FILTERS && FILTERS.chanel)        || 'all')
           + '&country='       + encodeURIComponent((FILTERS && FILTERS.country)       || 'all')
           + '&occupation='    + encodeURIComponent((FILTERS && FILTERS.occupation)    || 'all')
           + '&province='      + encodeURIComponent((FILTERS && FILTERS.province)      || 'all')
           + '&activitygroup=' + encodeURIComponent((FILTERS && FILTERS.activity_group)|| 'all')
           + '&movementtype='  + encodeURIComponent((FILTERS && FILTERS.movementtype)  || 'all');
    var url = _sunEndpoint('lead_list', qs);
    console.log('[Dashboard] leads page → fetch', url);

    // Loading state
    var tbody = document.getElementById('leadsTableBody');
    if (tbody) tbody.innerHTML = '<tr><td colspan="13" class="text-center py-5 text-muted">กำลังโหลด...</td></tr>';

    env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        data = _sunLeadRows(data);
        if (!data || !data.rows) {
          console.warn('[Dashboard] leads page: bad shape', data);
          return;
        }
        if (typeof ECDATA3 !== 'object' || !ECDATA3) { window.ECDATA3 = {}; }
        ECDATA3.leadsTable = data;
        _leadsTablePage = parseInt(data.currentPage, 10) || page;
        renderLeadsTable();
      })
      .catch(function (err) {
        console.error('[Dashboard] leads page failed:', err);
        var tbody = document.getElementById('leadsTableBody');
        if (tbody) tbody.innerHTML = '<tr><td colspan="13" class="text-center py-5 text-muted">โหลดข้อมูลไม่สำเร็จ</td></tr>';
      });
  } catch (e) {
    console.error('[Dashboard] fetchLeadsPage threw:', e);
  }
}

function renderLeadsPagination(totalPages) {
  const pag = document.getElementById('leadsTablePagination');
  if (!pag) return;
  if (totalPages <= 1) { pag.innerHTML = ''; return; }
  var p = _leadsTablePage;

  function btn(label, page, opts) {
    opts = opts || {};
    var cls = 'lt-page-btn' + (opts.active ? ' active' : '');
    var attr = (opts.disabled ? ' disabled' : '') + ' data-page="' + page + '"';
    return '<button class="' + cls + '"' + attr + ' type="button">' + label + '</button>';
  }
  var html = '';
  html += btn('<i class="fa-solid fa-chevron-left"></i>', p - 1, { disabled: p <= 1 });

  // Page list with ellipsis
  var pages = [];
  for (var i = 1; i <= totalPages; i++) {
    if (i === 1 || i === totalPages || (i >= p - 1 && i <= p + 1)) pages.push(i);
  }
  var prev = 0;
  pages.forEach(function (i) {
    if (i - prev > 1) html += '<span class="lt-page-ellipsis">…</span>';
    html += btn(String(i), i, { active: i === p });
    prev = i;
  });

  html += btn('<i class="fa-solid fa-chevron-right"></i>', p + 1, { disabled: p >= totalPages });
  pag.innerHTML = html;

  pag.querySelectorAll('.lt-page-btn').forEach(function (b) {
    b.addEventListener('click', function () {
      if (b.hasAttribute('disabled')) return;
      var newPage = parseInt(b.dataset.page, 10);
      if (!isNaN(newPage) && newPage >= 1 && newPage <= totalPages) {
        // ★ Server-side: fetch หน้าใหม่จาก API → update ECDATA → render
        fetchLeadsPage(newPage);
      }
    });
  });
}

function closePipelineModal() {
  const modal = document.getElementById('pipelineModal');
  if (!modal) return;
  modal.classList.remove('show');
  modal.setAttribute('aria-hidden', 'true');
  // คืน focus ให้ document body ป้องกัน focus ค้างใน popup ที่ปิดแล้ว
  if (document.activeElement && typeof document.activeElement.blur === 'function') {
    document.activeElement.blur();
  }
}

