var GROUP_META = {
  CS:  { name: 'Customer Service', desc: 'บริการหลังการขาย' },
  AN:  { name: 'Analyze Service',  desc: 'วิเคราะห์' },
  PLS: { name: 'Pre-Loan Stage',   desc: 'ต่อยอดสู่สินเชื่อ' },
  LS:  { name: 'Loan Service',     desc: 'บริการสินเชื่อ' },
  FI:  { name: 'Financial',        desc: 'บริการสินเชื่อ' },
  LE:  { name: 'Loan Execution',   desc: 'ทำสัญญาสินเชื่อ' },
  CRM: { name: 'CRM',              desc: 'ลูกค้าสัมพันธ์' }
};

// สีกลุ่ม (canonical ฝั่ง frontend) — reuse STATUS_DEPT_COLORS
function _groupColor(code) {
  return (STATUS_DEPT_COLORS && STATUS_DEPT_COLORS[code])
      || { col: '#4f7cff', shadow: 'rgba(79,124,255,0.3)' };
}

// และ transformed shape (code/name/total/steps[].rank/.name/.count/.pct)
function renderGroupPanels(data) {
  var container = document.getElementById('groupPanelsContainer');
  if (!container) return;

  var panels = (ECDATA2 && ECDATA2.groupPanels) || [];
  // ★ ตัดกลุ่ม "000" ออก — ไม่ต้องแสดงกราฟ/พาเนลของ group code 000
  if (Array.isArray(panels)) {
    panels = panels.filter(function (p) {
      var c = String((p && (p.code || p.group)) || '').trim();
      return c !== '000';
    });
  }
  if (!Array.isArray(panels) || panels.length === 0) {
    container.innerHTML =
      '<div class="col-12"><div class="empty-state">' +
      '<i class="fa-solid fa-inbox d-block"></i>' + DBSUN_I18N.noData + '</div></div>';
    return;
  }

  var html = '';
  panels.forEach(function (p, idx) {
    var code = p.code || p.group || '';
    var meta = GROUP_META[code] || {};
    var name = p.name || p.groupName || meta.name || code;
    var desc = p.desc || p.subtitle || p.groupDescription || meta.desc || '';
    var col  = _groupColor(code);
    var total = (p.total != null) ? p.total : 0;
    var delay = 'delay-' + (((idx) % 4) + 1);

    var steps = p.steps || [];
    var stepsHtml;
    if (!steps.length) {
      stepsHtml = '<div class="empty-state"><i class="fa-solid fa-inbox d-block"></i>' +
                  DBSUN_I18N.noData + ' (' + escapeHtml(code) + ')</div>';
    } else {
      var max = 1;
      for (var i = 0; i < steps.length; i++) {
        var c0 = (steps[i].count != null) ? steps[i].count : 0;
        if (c0 > max) max = c0;
      }
      stepsHtml = '';
      for (var j = 0; j < steps.length; j++) {
        var s     = steps[j];
        var sName = s.name || s.step || '';
        var sCnt  = (s.count != null) ? s.count : 0;
        var sPct  = (s.pct != null) ? s.pct : ((s.percentage != null) ? s.percentage : 0);
        var sRank = (s.rank != null) ? s.rank : (j + 1);
        var barPct = (sCnt / max) * 100;
        stepsHtml +=
          '<div class="step-row">' +
            '<div class="step-rank">' + sRank + '</div>' +
            '<div class="step-content">' +
              '<div class="step-top">' +
                '<div class="step-name" title="' + escapeHtml(sName) + '">' + escapeHtml(sName) + '</div>' +
                '<div class="step-num">' + fmt(sCnt) + '<small>(' + Number(sPct).toFixed(1) + '%)</small></div>' +
              '</div>' +
              '<div class="step-track">' +
                '<div class="step-bar" style="width: ' + barPct + '%;"></div>' +
              '</div>' +
            '</div>' +
          '</div>';
      }
    }

    html +=
      '<div class="col-12 col-lg-6 fade-up ' + delay + '">' +
        '<div class="group-panel" id="groupPanel-' + escapeHtml(code) + '" ' +
             'style="--group-color: ' + col.col + '; --group-shadow: ' + col.shadow + ';">' +
          '<div class="group-panel-header">' +
            '<div class="group-badge">' + escapeHtml(code) + '</div>' +
            '<div class="group-info">' +
              '<h3 class="group-name">' + escapeHtml(name) + '</h3>' +
              '<div class="group-desc">' + escapeHtml(desc) + '</div>' +
            '</div>' +
            '<div class="group-stats">' +
              '<div class="group-count" id="groupCount-' + escapeHtml(code) + '">' + fmt(total) + '</div>' +
              '<div class="group-count-label">ลีด</div>' +
            '</div>' +
          '</div>' +
          '<div class="step-list" id="groupSteps-' + escapeHtml(code) + '">' + stepsHtml + '</div>' +
        '</div>' +
      '</div>';
  });

  container.innerHTML = html;
}

