/* ════════════════════════════════════════════════════════════════
 *  ★ ฐานวันที่ (datebasis) + ช่วงวันที่ (fromdate/todate) บน header
 *
 *  datebasis — คอลัมน์ที่ year/month/fromdate/todate ใช้กรอง:
 *    contact = ggwprospect.contact_date · lead = lead.txdate
 *    wfs     = workflowstep.txdate ใบแรกสุด
 *  - แท็บใน DB_BASIS_LOCKED_TABS → disable ทั้งกลุ่ม **และบังคับ datebasis = 'contact'**
 *    (แท็บพวกนี้ยึด contact อย่างเดียว — ไม่ใช่แค่กดไม่ได้ ค่าที่ค้างมาจากแท็บอื่นต้องถูกล้างด้วย
 *     ไม่งั้น API ของแท็บนี้จะถูกเรียกด้วย datebasis=lead/wfs ที่ผู้ใช้เลือกค้างไว้)
 *  - แท็บใน DB_BASIS_WFS_TABS → เห็น contact + wfs · แท็บอื่นเห็น contact + lead (CSS คุมการแสดงผล)
 *
 *  fromdate/todate — ขอบเขตผูกกับ dropdown ปี+เดือน แล้วส่ง 'YYYY-MM-DD'
 *  (API ใช้ AND ร่วมกับ year/month ไม่ได้แทนที่กัน)
 * ════════════════════════════════════════════════════════════════ */
// 21/08/2026: ปลดล็อกครบทุกแท็บก่อนหน้านี้ (list ว่าง) แล้ว user สั่งให้ล็อกเฉพาะ
// "สถานะตามกลุ่มขั้นตอน" (status) กลับมา + ต้องยิง employee_performance ด้วย datebasis=contact เสมอ
var DB_BASIS_LOCKED_TABS = ['status'];
var DB_BASIS_WFS_TABS    = ['customerGroup', 'statusByCustomer'];

function _dbPad2(n) { return (n < 10 ? '0' : '') + n; }

/* วันสุดท้ายของเดือน — month เป็น 1-12 (day 0 ของเดือนถัดไป = วันสุดท้ายของเดือนนี้) */
function _dbLastDayOfMonth(year, month) { return new Date(year, month, 0).getDate(); }

/* ★ แปลง format วันที่ — จอแสดง DD/MM/YYYY แต่ FILTERS/API ใช้ ISO (YYYY-MM-DD) เสมอ */
var DB_DMY_RE = /^([0-3]?\d)\/([01]?\d)\/(\d{4})$/;

function _dbIsoToDmy(iso) {
  if (!iso || iso === 'all') return '';
  var p = String(iso).split('-');
  return (p.length === 3) ? (p[2] + '/' + p[1] + '/' + p[0]) : '';
}

/* '31/01/2026' (หรือ '5/1/2026') → '2026-01-31' · format/วันที่ไม่จริง (32/13/…) → '' */
function _dbDmyToIso(dmy) {
  var m = DB_DMY_RE.exec(String(dmy || '').trim());
  if (!m) return '';
  var d = parseInt(m[1], 10), mo = parseInt(m[2], 10), y = parseInt(m[3], 10);
  if (mo < 1 || mo > 12 || d < 1 || d > _dbLastDayOfMonth(y, mo)) return '';
  return String(y) + '-' + _dbPad2(mo) + '-' + _dbPad2(d);
}

/* แท็บที่ active อยู่ตอนนี้ */
function _dbActiveTab() {
  var btn = document.querySelector('.tab-btn.active');
  return (btn && btn.dataset.tab) || 'overview';
}

/* ยิง API ใหม่หลัง filter เปลี่ยน — หน่วง 300ms รวบการเปลี่ยนที่ติด ๆ กันเป็นครั้งเดียว
   (ตั้งช่วงวันที่ = แก้ 2 ช่อง ถ้าไม่รวบจะ refresh 2 รอบ = ยิง API ซ้ำทั้งชุด) */
var _dbFilterChangeTimer = null;
function _dbApplyFilterChange() {
  if (_dbFilterChangeTimer) clearTimeout(_dbFilterChangeTimer);
  _dbFilterChangeTimer = tmo(_dbApplyFilterChangeNow, 300);
}

function _dbApplyFilterChangeNow() {
  var tab = _dbActiveTab();
  try {
    if (tab === 'overview') {
      if (typeof refreshAllChartsFromApi === 'function') refreshAllChartsFromApi();
      if (typeof fetchOverviewKpi === 'function') fetchOverviewKpi();
    } else if (tab === 'lead') {
      if (typeof _dbReloadLeadBreakdown === 'function') _dbReloadLeadBreakdown();
    } else if (tab === 'steps') {
      // ★ แท็บกลุ่มขั้นตอน → โหลด /activitygroup (groupPanels) ใหม่ด้วยค่าปัจจุบัน
      if (typeof _dbReloadGroupPanels === 'function') _dbReloadGroupPanels();
    } else if (tab === 'customerGroup' || tab === 'statusByCustomer') {
      if (typeof _refreshCustomerGroupIfActive === 'function') _refreshCustomerGroupIfActive();
    } else if (tab === 'table') {
      if (typeof fetchLeadsPage === 'function') fetchLeadsPage(1);
    } else if (tab === 'status') {
      // ★ ยิง employee_performance + stage_summary ใหม่ด้วยค่าปัจจุบัน
      if (typeof _refreshStatusIfActive === 'function') _refreshStatusIfActive();
    } else if (tab === 'pipeline') {
      // pipeline ไม่รองรับ year/month/fromdate/todate/datebasis แต่รองรับ filter อื่น → โหลดหน้าแรกใหม่
      if (typeof fetchPipelinePage === 'function') fetchPipelinePage(1);
    }
  } catch (e) {
    console.error('[Dashboard] _dbApplyFilterChange failed:', e);
  }
}

/* ติ๊ก radio ให้ตรงกับ FILTERS.datebasis */
function _dbSyncBasisRadioUi() {
  var value = (typeof FILTERS !== 'undefined' && FILTERS && FILTERS.datebasis) || 'contact';
  var target = document.querySelector('#dbBasisGroup input[name="dbDateBasis"][value="' + value + '"]');
  if (target) target.checked = true;
}

/* เปิด/ปิด radio + ดึงค่ากลับเป็น contact เมื่อค่าที่ค้างอยู่ใช้กับแท็บนั้นไม่ได้
   - แท็บ locked → disable ทั้งกลุ่ม + บังคับ contact เสมอ (ไม่สนว่าค้างค่าอะไรมาจากแท็บก่อนหน้า)
   - แท็บ wfs เห็น contact+wfs → ค่า lead ค้างไม่ได้ · แท็บอื่นเห็น contact+lead → ค่า wfs ค้างไม่ได้

   ★ เรียกจาก switchTab() "ก่อน" บล็อก fetch ของแต่ละแท็บเสมอ — ลำดับนี้สำคัญ เพราะทุก fetch
     (fetchEmployeePerformanceByGroup, _dbTabChartQs ฯลฯ) อ่าน FILTERS.datebasis สดตอนประกอบ URL */
function _dbApplyBasisForTab(tabName) {
  var group = document.getElementById('dbBasisGroup');
  if (!group) return;
  var locked  = DB_BASIS_LOCKED_TABS.indexOf(tabName) !== -1;
  var wfsTab  = DB_BASIS_WFS_TABS.indexOf(tabName) !== -1;

  group.querySelectorAll('input[name="dbDateBasis"]').forEach(function (radio) {
    radio.disabled = locked;
  });
  if (typeof FILTERS !== 'undefined' && FILTERS) {
    if (locked) {
      // ★ 21/08/2026 — แท็บ locked (ตอนนี้คือ "สถานะตามกลุ่มขั้นตอน") ยึด contact อย่างเดียว
      //   เดิมแค่ disable radio แต่ไม่ล้างค่า → ถ้าผู้ใช้เลือก lead/wfs ไว้จากแท็บอื่นแล้วสลับมา
      //   employee_performance จะโดนเรียกด้วย datebasis ค่านั้นทั้งที่ UI โชว์ contact (disabled)
      FILTERS.datebasis = 'contact';
    } else {
      var hidden = wfsTab ? 'lead' : 'wfs';
      if (FILTERS.datebasis === hidden) FILTERS.datebasis = 'contact';
    }
  }
  _dbSyncBasisRadioUi();
}

/* ════════════════════════════════════════════════════════════════
 *  ★ 21/08/2026 — ปิดใช้งานตัวกรอง header ทั้งแถบ (ตามที่ user สั่งสำหรับแท็บ "ปฏิทินงาน")
 *
 *  แท็บใน DB_FILTER_DISABLED_TABS ไม่ได้ใช้ FILTERS เลย (ปฏิทินเป็น iframe ที่มีตัวกรอง
 *  ของตัวเองอยู่ข้างใน) — ปล่อยให้กดได้จะทำให้เข้าใจผิดว่ากรองแล้วมีผล
 *
 *  ครอบ 3 กล่อง: #dbBasisGroup (radio ฐานวันที่) · .page-header-left (ปี/เดือน/ช่วงวันที่)
 *  · .page-header-right (แหล่งที่มา/กลุ่มสถานะ/อาชีพ/ประเทศ/พนักงาน)
 *
 *  ★ ใช้ inert + opacity ที่ "ตัวกล่อง" แทนการไล่ตั้ง .disabled ทีละ control โดยตั้งใจ —
 *    เพราะ .disabled ของ control ข้างในมีเจ้าของอยู่แล้วคนละที่:
 *      - radio ฐานวันที่ → _dbApplyBasisForTab() (disable ตาม DB_BASIS_LOCKED_TABS)
 *      - ช่องวันที่      → _dbSyncDateBounds()   (disable เมื่อปี = ทั้งหมด)
 *    ถ้าฟังก์ชันนี้ไปตั้ง/ล้าง .disabled ด้วย จะทับสถานะของ 2 เจ้าของนั้นแล้วเพี้ยน
 *    (เช่น ออกจากแท็บปฏิทินแล้วช่องวันที่กลับมากดได้ทั้งที่ปียังเป็น "ทั้งหมด")
 *    inert ปิดทั้ง subtree (คลิก + โฟกัสด้วยคีย์บอร์ด) โดยไม่แตะ .disabled ของใครเลย
 *    pointerEvents ใส่คู่ไว้เป็น fallback ให้เบราว์เซอร์เก่าที่ยังไม่รองรับ inert
 * ════════════════════════════════════════════════════════════════ */
// ★ 26/08/2026 — เพิ่ม 'kpi' (KPI-EventMovement เฉพาะสาขา Gold) ด้วยเหตุผลเดียวกับ 'calendar':
//   เป็น iframe ที่มีตัวกรองของตัวเองข้างใน ไม่ได้อ่าน FILTERS ของหน้านี้เลย
var DB_FILTER_DISABLED_TABS = ['calendar', 'kpi'];

function _dbApplyHeaderFilterState(tabName) {
  var off = DB_FILTER_DISABLED_TABS.indexOf(tabName) !== -1;
  var boxes = [
    document.getElementById('dbBasisGroup'),
    document.querySelector('.dbsun-root .page-header-left'),
    document.querySelector('.dbsun-root .page-header-right')
  ];
  boxes.forEach(function (el) {
    if (!el) return;
    if (off) {
      el.setAttribute('inert', '');
      el.setAttribute('aria-disabled', 'true');
      el.style.opacity = '0.45';
      el.style.pointerEvents = 'none';
    } else {
      el.removeAttribute('inert');
      el.removeAttribute('aria-disabled');
      el.style.opacity = '';
      el.style.pointerEvents = '';
    }
  });
  // เปิดเมนู dropdown ค้างไว้แล้วสลับมาแท็บที่ปิดตัวกรอง → เมนูจะลอยค้างกดไม่ได้ ปิดทิ้งก่อน
  if (off) {
    document.querySelectorAll('.dbsun-root .hdr-dd-menu.show').forEach(function (m) {
      m.classList.remove('show');
      var wrap = m.parentNode;
      if (wrap) wrap.classList.remove('is-open');
      var b = wrap && wrap.querySelector('.hdr-dd-btn');
      if (b) { b.classList.remove('hdr-dd-open'); b.setAttribute('aria-expanded', 'false'); }
    });
  }
}

/* ตั้งขอบเขต + ค่าของ input date ตาม dropdown ปี/เดือน — ช่องเป็น text (DD/MM/YYYY)
   ขอบเขตเก็บใน dataset.minIso/maxIso (ISO) + sync ไป native picker (min/max จริง)
   keepValues = true → เก็บค่าที่ user เลือกไว้ถ้ายังอยู่ในขอบเขตใหม่ */
function _dbSyncDateBounds(keepValues) {
  var fromEl = document.getElementById('hdrFromDate');
  var toEl   = document.getElementById('hdrToDate');
  if (!fromEl || !toEl) return;
  var fromNative = document.getElementById('hdrFromDateNative');
  var toNative   = document.getElementById('hdrToDateNative');
  var F = (typeof FILTERS !== 'undefined' && FILTERS) ? FILTERS : null;
  if (!F) return;

  var year  = String(F.year  || 'all');
  var month = String(F.month || 'all');

  // ปี = ทั้งหมด → ไม่มีขอบเขตให้ยึด ปิดช่องไว้แล้วส่ง 'all'
  if (!/^\d{4}$/.test(year)) {
    fromEl.value = ''; toEl.value = '';
    delete fromEl.dataset.minIso; delete fromEl.dataset.maxIso;
    delete toEl.dataset.minIso;   delete toEl.dataset.maxIso;
    fromEl.disabled = true; toEl.disabled = true;
    if (fromNative) { fromNative.value = ''; fromNative.disabled = true; }
    if (toNative)   { toNative.value = '';   toNative.disabled = true; }
    F.fromdate = 'all'; F.todate = 'all';
    return;
  }
  fromEl.disabled = false; toEl.disabled = false;
  if (fromNative) fromNative.disabled = false;
  if (toNative)   toNative.disabled = false;

  var monthNum = parseInt(month, 10);
  var hasMonth = month !== 'all' && !isNaN(monthNum) && monthNum >= 1 && monthNum <= 12;
  var minStr, maxStr;
  if (hasMonth) {
    minStr = year + '-' + _dbPad2(monthNum) + '-01';
    maxStr = year + '-' + _dbPad2(monthNum) + '-' + _dbPad2(_dbLastDayOfMonth(parseInt(year, 10), monthNum));
  } else {
    minStr = year + '-01-01';
    maxStr = year + '-12-31';
  }
  fromEl.dataset.minIso = minStr; fromEl.dataset.maxIso = maxStr;
  toEl.dataset.minIso   = minStr; toEl.dataset.maxIso   = maxStr;
  if (fromNative) { fromNative.min = minStr; fromNative.max = maxStr; }
  if (toNative)   { toNative.min = minStr;   toNative.max = maxStr; }

  // ★ เดือน = "ทั้งหมด" → บังคับ 01/01-31/12 ของปีที่เลือก (F.year) เสมอ ไม่ keep ค่าเดิม
  //   ตามที่ user สั่ง (ต่างจากกรณีเลือกเดือนเจาะจง ที่ยัง keep ค่าเดิมถ้ายังอยู่ในขอบเขตใหม่)
  var fromVal, toVal;
  if (!hasMonth) {
    fromVal = minStr; toVal = maxStr;
  } else {
    // ค่าเดิม (DD/MM/YYYY) ยังอยู่ในช่วงใหม่ไหม — ไม่อยู่ก็ดึงกลับไปคลุมทั้งช่วง
    var curFrom = _dbDmyToIso(fromEl.value);
    var curTo   = _dbDmyToIso(toEl.value);
    fromVal = (keepValues && curFrom && curFrom >= minStr && curFrom <= maxStr) ? curFrom : minStr;
    toVal   = (keepValues && curTo   && curTo   >= minStr && curTo   <= maxStr) ? curTo   : maxStr;
    if (fromVal > toVal) { fromVal = minStr; toVal = maxStr; }
  }

  fromEl.value = _dbIsoToDmy(fromVal); toEl.value = _dbIsoToDmy(toVal);
  if (fromNative) fromNative.value = fromVal;
  if (toNative)   toNative.value = toVal;
  F.fromdate = fromVal;   F.todate = toVal;
}

/* user แก้ค่าในช่อง (พิมพ์ DD/MM/YYYY หรือเลือกจากปฏิทิน) → parse + clamp เข้าขอบเขต
   + กันสลับหัวท้าย แล้วยิง API ใหม่ — พิมพ์ format ผิด/วันที่ไม่จริง → กลับไปค่าขอบ */
function _dbOnDateInputChange(changedEl) {
  var fromEl = document.getElementById('hdrFromDate');
  var toEl   = document.getElementById('hdrToDate');
  if (!fromEl || !toEl) return;
  var minStr = fromEl.dataset.minIso || '';
  var maxStr = fromEl.dataset.maxIso || '';

  var iso = _dbDmyToIso(changedEl.value);
  if (!iso) iso = (changedEl === fromEl) ? minStr : maxStr;
  if (minStr && iso < minStr) iso = minStr;
  if (maxStr && iso > maxStr) iso = maxStr;

  var fromIso = (changedEl === fromEl) ? iso : (_dbDmyToIso(fromEl.value) || minStr);
  var toIso   = (changedEl === toEl)   ? iso : (_dbDmyToIso(toEl.value)   || maxStr);
  // เริ่มต้นมาหลังสิ้นสุด → ดันอีกฝั่งตาม ไม่ให้ได้ช่วงติดลบ
  if (fromIso && toIso && fromIso > toIso) {
    if (changedEl === fromEl) { toIso = fromIso; } else { fromIso = toIso; }
  }

  fromEl.value = _dbIsoToDmy(fromIso); toEl.value = _dbIsoToDmy(toIso);
  var fromNative = document.getElementById('hdrFromDateNative');
  var toNative   = document.getElementById('hdrToDateNative');
  if (fromNative) fromNative.value = fromIso;
  if (toNative)   toNative.value = toIso;

  if (typeof FILTERS !== 'undefined' && FILTERS) {
    FILTERS.fromdate = fromIso || 'all';
    FILTERS.todate   = toIso   || 'all';
    console.log('[Dashboard] date range →', FILTERS.fromdate, '..', FILTERS.todate);
  }
  _dbApplyFilterChange();
}

/* bind ครั้งเดียว — เรียกจาก initDashboard */
function _dbBindBasisAndDateRange() {
  var group = document.getElementById('dbBasisGroup');
  if (group && group.dataset.bpBound !== '1') {
    group.dataset.bpBound = '1';
    group.querySelectorAll('input[name="dbDateBasis"]').forEach(function (radio) {
      radio.addEventListener('change', function () {
        if (!radio.checked) return;
        if (typeof FILTERS !== 'undefined' && FILTERS) FILTERS.datebasis = radio.value;
        console.log('[Dashboard] datebasis →', radio.value);
        _dbApplyFilterChange();
      });
    });
  }
  [document.getElementById('hdrFromDate'), document.getElementById('hdrToDate')].forEach(function (el) {
    if (!el || el.dataset.bpBound === '1') return;
    el.dataset.bpBound = '1';
    el.addEventListener('change', function () { _dbOnDateInputChange(el); });
    // Enter = ยืนยันค่าที่พิมพ์ทันที (change ปกติรอ blur)
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') { e.preventDefault(); _dbOnDateInputChange(el); }
    });
  });
  // ★ ปุ่มปฏิทิน → เปิด native date picker (ซ่อนไว้) · เลือกแล้ว copy กลับช่อง text เป็น DD/MM/YYYY
  [['hdrFromDateCal', 'hdrFromDateNative', 'hdrFromDate'],
   ['hdrToDateCal', 'hdrToDateNative', 'hdrToDate']].forEach(function (ids) {
    var calBtn = document.getElementById(ids[0]);
    var native = document.getElementById(ids[1]);
    var textEl = document.getElementById(ids[2]);
    if (!calBtn || !native || !textEl || calBtn.dataset.bpBound === '1') return;
    calBtn.dataset.bpBound = '1';
    var openPicker = function () {
      if (native.disabled || textEl.disabled) return;
      // sync ค่าที่พิมพ์ค้างไว้ (ยังไม่ commit) เข้า native ก่อน — ปฏิทินจะเปิดที่วันนั้น
      var iso = _dbDmyToIso(textEl.value);
      if (iso) native.value = iso;
      try {
        if (typeof native.showPicker === 'function') { native.showPicker(); }
        else { native.focus(); native.click(); }
      } catch (e) { try { native.focus(); } catch (e2) { } }
    };
    calBtn.addEventListener('click', openPicker);
    // ★ กดส่วนไหนของช่อง input ก็เปิดปฏิทิน — native โปร่งใสคลุมทั้งช่อง (CSS inset:0)
    //   คลิกจึงลงที่ native โดยตรง = user gesture บน element ตัวเอง → showPicker() ผ่านแน่นอน
    //   (bind textEl ด้วยเผื่อเบราว์เซอร์ที่ไม่มี native overlay — ไม่มีผลข้างเคียง)
    native.addEventListener('click', openPicker);
    textEl.addEventListener('click', openPicker);
    native.addEventListener('change', function () {
      if (!native.value) return;
      textEl.value = _dbIsoToDmy(native.value);
      _dbOnDateInputChange(textEl);
    });
  });
  _dbApplyBasisForTab(_dbActiveTab());
  _dbSyncDateBounds(false);
  _dbApplyHeaderFilterState(_dbActiveTab());   // ★ ต้องหลัง 2 บรรทัดบน (เจ้าของ .disabled ของ control ข้างใน)
}

/* ════════════════════════════════════════════════════════════════
 *  ★ Dropdown "พนักงาน" — multi-select + ช่องค้นหา
 *  ค่าที่ส่ง API: employee=NE134,NE107 (comma-separated, OR กัน — ตามสเปก 2026-08-06)
 *  ไม่เลือกใครเลย = 'all' · ติ๊ก "ทั้งหมด" = ล้างทุกตัวที่เลือก
 * ════════════════════════════════════════════════════════════════ */

/* FILTERS.employee → array ของ code ที่เลือกอยู่ ('all'/ว่าง → []) */
function _dbEmployeeSelected() {
  var v = (typeof FILTERS !== 'undefined' && FILTERS && FILTERS.employee) || 'all';
  if (!v || v === 'all') return [];
  return String(v).split(',').filter(function (x) { return x !== ''; });
}

/* สร้าง HTML ของเมนู: ช่องค้นหา + "ทั้งหมด" + รายชื่อ (ติ๊กตามที่เลือกค้างไว้ใน FILTERS) */
function _dbEmployeeMenuHtml(items) {
  var sel = {};
  _dbEmployeeSelected().forEach(function (c) { sel[c] = 1; });
  var any = Object.keys(sel).length > 0;
  var html = '<div class="hdr-dd-search">'
           + '<input type="text" class="hdr-dd-search-input" placeholder="' + (DBSUN_I18N.searchWord || 'ค้นหา') + '..." autocomplete="off" />'
           + '</div>'
           + '<div class="hdr-dd-item' + (any ? '' : ' active') + '" data-value="all">'
           + DBSUN_I18N.all + ' <i class="fa-solid fa-check"></i></div>';
  items.forEach(function (it) {
    var v = (it && it.value != null) ? String(it.value) : '';
    var l = (it && it.label != null) ? String(it.label) : v;
    if (!v) return;
    html += '<div class="hdr-dd-item' + (sel[v] ? ' active' : '') + '" data-value="' + v.replace(/"/g, '&quot;') + '">'
          + l.replace(/</g, '&lt;').replace(/>/g, '&gt;')
          + ' <i class="fa-solid fa-check"></i></div>';
  });
  return html;
}

/* toggle 1 รายการ → คืนค่า employee ใหม่ ('all' หรือ 'A,B,C') + sync .active ในเมนู */
function _dbEmployeeToggle(menu, item) {
  var value = item.dataset.value;
  var allItem = menu.querySelector('.hdr-dd-item[data-value="all"]');
  if (value === 'all') {
    menu.querySelectorAll('.hdr-dd-item.active').forEach(function (x) { x.classList.remove('active'); });
    if (allItem) allItem.classList.add('active');
    return 'all';
  }
  if (item.classList.contains('active')) { item.classList.remove('active'); }
  else { item.classList.add('active'); }
  var codes = [];
  menu.querySelectorAll('.hdr-dd-item.active').forEach(function (x) {
    if (x.dataset.value && x.dataset.value !== 'all') codes.push(x.dataset.value);
  });
  if (allItem) {
    if (codes.length === 0) allItem.classList.add('active');
    else allItem.classList.remove('active');
  }
  return codes.length ? codes.join(',') : 'all';
}

/* label บนปุ่ม: ไม่เลือก → "พนักงาน" · 1 คน → ชื่อคนนั้น · หลายคน → "พนักงาน (N)" */
function _dbEmployeeLabel(menu) {
  var names = [];
  menu.querySelectorAll('.hdr-dd-item.active').forEach(function (x) {
    if (x.dataset.value && x.dataset.value !== 'all') names.push(x.textContent.trim().replace(/\s+/g, ' '));
  });
  if (names.length === 0) return DBSUN_I18N.employee;
  if (names.length === 1) return names[0];
  return DBSUN_I18N.employee + ' (' + names.length + ')';
}

/* กรองรายชื่อตามคำค้น (ชื่อหรือรหัส) — "ทั้งหมด" โชว์เสมอ */
function _dbEmployeeFilterList(menu, term) {
  term = String(term || '').trim().toLowerCase();
  menu.querySelectorAll('.hdr-dd-item').forEach(function (x) {
    if (x.dataset.value === 'all') return;
    var hit = !term
           || x.textContent.toLowerCase().indexOf(term) !== -1
           || String(x.dataset.value).toLowerCase().indexOf(term) !== -1;
    x.style.display = hit ? '' : 'none';
  });
}

/* ════════════════════════════════════════════════════════════════
 *  ★ Dropdown "ขั้นตอน" (activitystep) — แท็บสถานะตามลูกค้า
 *  multi-select + ช่องค้นหา (โครงเดียวกับ dropdown พนักงาน)
 *  รายการขึ้นกับแผนกที่เลือก → โหลดใหม่ทุกครั้งที่เปลี่ยน sbcDeptSelect
 *  ค่าที่ส่ง /customer_status_list: activitystep=all หรือ CS01,CS02 (comma)
 * ════════════════════════════════════════════════════════════════ */
var _sbcStepSel = 'all';     // ค่าที่เลือก ('all' หรือ csv เช่น 'CS01,CS02')
var _sbcStepItems = [];      // [{value,label}] ของแผนกปัจจุบัน

function _sbcStepMenuHtml(items) {
  var sel = {};
  if (_sbcStepSel && _sbcStepSel !== 'all') {
    String(_sbcStepSel).split(',').forEach(function (c) { if (c) sel[c] = 1; });
  }
  var any = Object.keys(sel).length > 0;
  var html = '<div class="hdr-dd-search">'
           + '<input type="text" class="hdr-dd-search-input" placeholder="' + (DBSUN_I18N.searchWord || 'ค้นหา') + '..." autocomplete="off" />'
           + '</div>'
           + '<div class="hdr-dd-item' + (any ? '' : ' active') + '" data-value="all">'
           + DBSUN_I18N.all + ' <i class="fa-solid fa-check"></i></div>';
  (items || []).forEach(function (it) {
    var v = (it && it.value != null) ? String(it.value) : '';
    var l = (it && it.label != null) ? String(it.label) : v;
    if (!v) return;
    html += '<div class="hdr-dd-item' + (sel[v] ? ' active' : '') + '" data-value="' + v.replace(/"/g, '&quot;') + '">'
          + l.replace(/</g, '&lt;').replace(/>/g, '&gt;')
          + ' <i class="fa-solid fa-check"></i></div>';
  });
  return html;
}

/* label ปุ่ม: ไม่เลือก → "ขั้นตอน" · 1 ขั้นตอน → ชื่อขั้นตอน · หลายขั้นตอน → "ขั้นตอน (N)" */
function _sbcStepLabel(menu) {
  var names = [];
  menu.querySelectorAll('.hdr-dd-item.active').forEach(function (x) {
    if (x.dataset.value && x.dataset.value !== 'all') names.push(x.textContent.trim().replace(/\s+/g, ' '));
  });
  if (names.length === 0) return DBSUN_I18N.activityStep;
  if (names.length === 1) return names[0];
  return DBSUN_I18N.activityStep + ' (' + names.length + ')';
}

/* สร้างเมนูใหม่จาก _sbcStepItems + bind ช่องค้นหา + รีเซ็ต label ปุ่ม */
function _sbcRenderStepMenu() {
  var menu = document.getElementById('sbcStepMenu');
  if (!menu) return;
  menu.innerHTML = _sbcStepMenuHtml(_sbcStepItems);
  var searchIn = menu.querySelector('.hdr-dd-search-input');
  if (searchIn) {
    searchIn.addEventListener('input', function () { _dbEmployeeFilterList(menu, searchIn.value); });
    searchIn.addEventListener('click', function (e) { e.stopPropagation(); });
  }
  var btn = document.getElementById('sbcStepBtn');
  var lbl = btn && btn.querySelector('.hdr-dd-label');
  if (lbl) lbl.textContent = _sbcStepLabel(menu);
}

/* ════════════════════════════════════════════════════════════════
 *  ★ Widget "เลือกแผนก" — ปุ่ม+เมนู+ช่องค้นหา (ใช้ 3 แท็บ):
 *    ลูกค้าตามกลุ่มขั้นตอน   → cgDeptSelect/cgDeptMenu/cgDeptBtn
 *    สถานะตามลูกค้า         → sbcDeptSelect/sbcDeptMenu/sbcDeptBtn
 *    สถานะตามกลุ่มขั้นตอน   → statusDeptSelect/statusDeptMenu/statusDeptBtn (เพิ่ม 10/09/2026
 *                              ให้เรียก API masterdata เหมือน 2 ตัวข้างบน — เดิมมีแค่ select
 *                              เปล่าๆ ไม่มี widget เลย)
 *  native select ถูกซ่อน แต่ยังเป็นตัวเก็บค่า/ตัวยิง change (logic เดิมทั้งหมด
 *  ผูกกับมัน) — widget นี้แค่แสดงผลแล้ว proxy ค่าที่เลือกกลับเข้า select
 * ════════════════════════════════════════════════════════════════ */
function _sbcDeptRenderMenu() { _dbDeptWidgetRender('sbcDeptSelect', 'sbcDeptMenu', 'sbcDeptBtn'); }
function _cgDeptRenderMenu() { _dbDeptWidgetRender('cgDeptSelect', 'cgDeptMenu', 'cgDeptBtn'); }
function _statusDeptRenderMenu() { _dbDeptWidgetRender('statusDeptSelect', 'statusDeptMenu', 'statusDeptBtn'); }

function _dbDeptWidgetRender(selId, menuId, btnId) {
  var sel = document.getElementById(selId);
  var menu = document.getElementById(menuId);
  var btn = document.getElementById(btnId);
  if (!sel || !menu) return;
  var html = '<div class="hdr-dd-search">'
           + '<input type="text" class="hdr-dd-search-input" placeholder="' + (DBSUN_I18N.searchWord || 'ค้นหา') + '..." autocomplete="off" />'
           + '</div>';
  for (var i = 0; i < sel.options.length; i++) {
    var o = sel.options[i];
    var v = String(o.value || '');
    var l = String(o.text || v);
    if (!v) continue;
    html += '<div class="hdr-dd-item' + (v === sel.value ? ' active' : '') + '" data-value="' + v.replace(/"/g, '&quot;') + '">'
          + l.replace(/</g, '&lt;').replace(/>/g, '&gt;')
          + ' <i class="fa-solid fa-check"></i></div>';
  }
  menu.innerHTML = html;
  var searchIn = menu.querySelector('.hdr-dd-search-input');
  if (searchIn) {
    searchIn.addEventListener('input', function () { _dbEmployeeFilterList(menu, searchIn.value); });
    searchIn.addEventListener('click', function (e) { e.stopPropagation(); });
  }
  // label ปุ่ม = ชื่อแผนกที่เลือกอยู่
  var lbl = btn && btn.querySelector('.hdr-dd-label');
  var cur = sel.options[sel.selectedIndex];
  if (lbl && cur) lbl.textContent = String(cur.text || cur.value);
}

/* โหลดรายการขั้นตอนของแผนกที่เลือก — GET /dashboard/masterdata-activitystep?activitygroup={group}
   (DashboardActivityStepServlet → DashboardView.fetchActivityStepMasterJson → normalize {value,label}) */
function _sbcLoadActivitySteps(group) {
  var base = (typeof DB_API_BASE !== 'undefined' && DB_API_BASE) ? DB_API_BASE : '/dashboard';
  // ★ 27/08/2026 — เติม ggwBranch (ss_branch_code) เหมือนเส้นอื่นทั้งหมดของหน้านี้
  var url = _dbGgwbranchParam(base + '/masterdata-activitystep?activitygroup=' + encodeURIComponent(group || 'CS'));
  console.log('[Dashboard] masterdata-activitystep → fetch', url);
  return env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
    .then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    })
    .then(function (items) {
      _sbcStepItems = Array.isArray(items) ? items : [];
      _sbcRenderStepMenu();
      console.log('[Dashboard] activitystep(' + group + ') loaded: ' + _sbcStepItems.length + ' items');
    })
    .catch(function (err) {
      console.warn('[Dashboard] masterdata-activitystep failed:', err);
      _sbcStepItems = [];
      _sbcRenderStepMenu();   // เหลือแค่ "ทั้งหมด"
    });
}

/* ════════════════════════════════════════════════════════════════
 *  ★ 21/08/2026 — Prefetch frame ปฏิทิน (แก้อาการ "กดแท็บปฏิทินแล้วช้า")
 *
 *  ทำไมถึงช้า: dashboard_calendar_frame.xhtml เป็นหน้า JSF ที่ผูก EL 4 ตัวซึ่ง
 *  "ยิง remote API แบบ blocking" ตอน server render (calendarDataJson / myTaskListJson /
 *  myCalendarListJson / myTaskCalendarListJson → kpi-gold-service พอร์ต 3302)
 *  เดิมเราเพิ่งเริ่ม fetch ตอน "กดแท็บ" ผู้ใช้จึงต้องนั่งรอทั้งก้อนตรงนั้น
 *  (ตอน service 3302 ล่ม ยิ่งหนัก — แต่ละ call เสียเวลา ~2 วิกับการ connect ที่ล้มเหลว)
 *
 *  แก้ 2 ชั้น:
 *   - ชั้น server: ใส่ TTL cache ใน CalendarDashboardView (ดูคอมเมนต์ในไฟล์นั้น)
 *     → render ครั้งถัดๆ ไปไม่ต้องยิง remote ซ้ำ
 *   - ชั้นนี้: เริ่ม fetch ล่วงหน้าตั้งแต่ตอนโหลดหน้า dashboard (ยิงตอน idle ไม่แย่ง
 *     API ของแท็บภาพรวม) พอผู้ใช้กดแท็บ HTML มักพร้อมอยู่แล้ว → ใส่ srcdoc ได้ทันที
 *
 *  คืน promise ตัวเดิมเสมอ → กดแท็บรัวๆ ระหว่างที่ยัง fetch ไม่เสร็จก็ไม่ยิงซ้ำ
 *  ถ้า fetch พลาด เคลียร์ตัวแปรทิ้งเพื่อให้กดครั้งหน้า retry ใหม่ได้
 * ════════════════════════════════════════════════════════════════ */
var _calFrameFetch = null;
function _dbPrefetchCalendarFrame() {
  if (_calFrameFetch) return _calFrameFetch;
  _calFrameFetch = env.frame('calendar')
    .catch(function (err) {
      _calFrameFetch = null;          // ล้มเหลว → ให้ครั้งหน้าเริ่มใหม่ได้ (ไม่ค้าง promise ที่ reject)
      throw err;
    });
  return _calFrameFetch;
}

function _dbLoadKpiFrame(reason) {
  try {
    var _kpiFrame = document.getElementById('kpiFrame');
    var _kpiLoad  = document.getElementById('kpiFrameLoading');
    if (_kpiFrame && _kpiFrame.getAttribute('data-loaded') !== '1'
                  && _kpiFrame.getAttribute('data-loading') !== '1') {
      _kpiFrame.setAttribute('data-loading', '1');
      if (_kpiLoad) _kpiLoad.style.display = '';
      _kpiFrame.addEventListener('load', function () {
        if (_kpiLoad) _kpiLoad.style.display = 'none';
      }, { once: true });
      var _kpiCtx = '' + env.ctx + '';
      console.log('[Dashboard] KPI frame load (' + (reason || 'switch-tab') + ') → fetch',
                  'dashboard_kpi_frame (generated: tools/sync-dashboard-frames.mjs)',
                  '| API paths:',
                  '/eventmovements?page=1&perPage=20&ggwBranch=' + encodeURIComponent(DB_GGWBRANCH || 'all'),
                  '/masters/task-types?ggwBranch=' + encodeURIComponent(DB_GGWBRANCH || 'all'),
                  '/masters/pillar-tasks?ggwBranch=' + encodeURIComponent(DB_GGWBRANCH || 'all'),
                  '/masters/prospects?ggwBranch=' + encodeURIComponent(DB_GGWBRANCH || 'all'),
                  '/masters/products?ggwBranch=' + encodeURIComponent(DB_GGWBRANCH || 'all'));
      env.frame('kpi')
        .then(function (html) {
          // ★ 09/09/2026 — แทน __GOLDAPI__ ด้วย path ของ GoldApiProxyServlet (same-origin) แทนที่จะ
          //   เป็น raw IP ตรงๆ อย่างเดิม (http://192.168.24.177:3307/...) — raw IP เดิมทำให้ browser
          //   (ซึ่งรัน srcdoc นี้อยู่) ยิง fetch ตรงไปหา private IP จากหน้าเว็บที่ deploy จริงบนโฮสต์
          //   สาธารณะ (acedemo.acecloud.co.th:52339) → โดน Chrome "Local Network Access" permission
          //   prompt บล็อก/ถามสิทธิ์ทุกครั้งที่โหลดหน้า (ยิง _dbLoadKpiFrame('page-entry') ทันทีตอน
          //   DOMContentLoaded อยู่แล้ว ไม่ต้องกดแท็บ KPI-EventMovement เลยด้วยซ้ำ) — ตอน dev/test บน
          //   เครื่องที่อยู่ใน network เดียวกับ 192.168.24.177 ไม่เจอปัญหานี้ เพราะ browser มองว่า
          //   origin ของหน้าเองก็เป็น private เหมือนกัน (private→private ไม่ต้องขอสิทธิ์)
          //   GoldApiProxyServlet (/goldapi/*) เป็น generic proxy ไป dashboard-triplesale-service
          //   อยู่แล้ว (ใช้กับปฏิทินงาน) รองรับ path ที่ตัว dashboard_kpi_frame.xhtml ต้องการครบ
          //   (/masters/*, /eventmovements*) โดยไม่ต้องแก้ servlet เพิ่ม — แค่เปลี่ยนจุดที่ประกอบ URL นี้
          // - __GOLDAPI__ → base URL สำหรับ API masters/eventmovements (ผ่าน proxy same-origin แล้ว)
          // - __GGW_BRANCH__ → ค่า ss_branch_code (SUN/Gold/ACE/ฯลฯ) เพื่อเป็น query param ggwBranch
          html = html.replace(/__GOLDAPI__/g, env.goldApi);
          html = html.replace(/__GGW_BRANCH__/g, DB_GGWBRANCH);
          _kpiFrame.removeAttribute('src');
          _kpiFrame.srcdoc = html;
          _kpiFrame.setAttribute('data-loaded', '1');
          _kpiFrame.removeAttribute('data-loading');
        })
        .catch(function (err) {
          console.error('[Dashboard] kpi list load failed:', err);
          _kpiFrame.removeAttribute('data-loading');
          if (_kpiLoad) _kpiLoad.style.display = 'none';
          _kpiFrame.srcdoc = '<div style="font-family:sans-serif;padding:24px;color:#b00">โหลดรายการงาน KPI ไม่สำเร็จ — ' + (err.message || err) + '</div>';
        });
    } else if (_kpiLoad) {
      _kpiLoad.style.display = 'none';
    }
  } catch (e) { console.error('[Dashboard] kpi frame load threw:', e); }
}

function switchTab(tabName) {
  document.querySelectorAll('.tab-btn').forEach(btn => {
    const active = btn.dataset.tab === tabName;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-selected', active);
  });
  document.querySelectorAll('.tab-pane').forEach(pane => {
    pane.classList.toggle('active', pane.id === 'tab' + tabName.charAt(0).toUpperCase() + tabName.slice(1));
  });
  // ★ Toggle body class — ใช้ใน CSS ซ่อน เดือน + กลุ่มสถานะ dropdowns ตอนอยู่ tab Pipeline/Status
  document.body.classList.toggle('tab-pipeline-active', tabName === 'pipeline');
  document.body.classList.toggle('tab-status-active',   tabName === 'status');
  // ★ ใช้ใน CSS โชว์ dropdown "ประเภทการรายการ" เฉพาะ tab กลุ่มขั้นตอน
  document.body.classList.toggle('tab-steps-active',    tabName === 'steps');
  // ★ ซ่อน dropdown "กลุ่มสถานะ" เมื่ออยู่ tab "ลูกค้าตามกลุ่มขั้นตอน"
  document.body.classList.toggle('tab-customer-group-active', tabName === 'customerGroup');
  // ★ ซ่อน dropdown "กลุ่มสถานะ" เมื่ออยู่ tab "สถานะตามลูกค้า" (ใช้ dropdown แผนกในแท็บแทน)
  document.body.classList.toggle('tab-status-by-customer-active', tabName === 'statusByCustomer');

  // ★ 21/08/2026 — เปลี่ยน menu/tab → "คงค่า" filter header เดิมไว้ (ไม่รีเซ็ตเป็น all อีกต่อไป)
  //   ตามที่ user สั่ง: filter ที่เลือกไว้ในแท็บเก่าต้องยังอยู่ตอนสลับแท็บ แล้วให้แท็บใหม่ยิง API
  //   ด้วยค่าที่เลือกไว้นั้น (โค้ดเฉพาะแท็บด้านล่างยังคง fetch ด้วยค่าปัจจุบันของ FILTERS ตามเดิม)

  // ★ ฐานวันที่: เปิด/ปิด radio ตามแท็บ (lock + บังคับ contact เฉพาะ "สถานะตามกลุ่มขั้นตอน" · wfs เฉพาะ 2 แท็บ)
  //   ต้องเรียก "ก่อน" บล็อก fetch ของแต่ละแท็บด้านล่าง — ทุก fetch อ่าน FILTERS.datebasis สดตอนประกอบ URL
  //   แล้วตั้งขอบเขต input date ใหม่ตามปี/เดือนปัจจุบันใน FILTERS (ค่าที่คงไว้จากแท็บก่อนหน้า)
  if (typeof _dbApplyBasisForTab === 'function') _dbApplyBasisForTab(tabName);
  if (typeof _dbSyncDateBounds === 'function') _dbSyncDateBounds(false);

  // ★ ปิดใช้งานตัวกรอง header ทั้งแถบสำหรับแท็บที่ไม่ได้ใช้ FILTERS (ตอนนี้คือ "ปฏิทินงาน")
  //   ★ ต้องเรียก "หลัง" 2 บรรทัดบน — เพราะทั้งคู่เป็นเจ้าของ .disabled ของ radio/ช่องวันที่
  //     ถ้าเรียกก่อน สถานะที่ตั้งไว้จะถูกเขียนทับ (ดูคำอธิบายที่ _dbApplyHeaderFilterState)
  if (typeof _dbApplyHeaderFilterState === 'function') _dbApplyHeaderFilterState(tabName);

  // ★ Pipeline ไม่ใช้ fromdate/todate (API เส้นนี้ไม่รองรับ) → ซ่อนช่องช่วงวันที่ทั้งก้อน
  //   (มีกฎ CSS body.tab-pipeline-active ซ่อนอยู่แล้ว — ตั้ง inline ซ้ำอีกชั้นกันพลาด)
  var _drEl = document.getElementById('dbDateRange');
  if (_drEl) _drEl.style.display = (tabName === 'pipeline') ? 'none' : '';

  // Resize ECharts ของ tab ที่เพิ่ง active (canvas ใน tab ที่ซ่อนอยู่ต้องคำนวณขนาดใหม่)
  if (tabName === 'overview') {
    tmo(function () {
      if (typeof echartsInstances === 'object' && echartsInstances) {
        Object.keys(echartsInstances).forEach(function (k) {
          try { echartsInstances[k].resize(); } catch (e) { /* ignore */ }
        });
      }
    }, 80);
    // ★ ดึงข้อมูล chart/KPI ใหม่ด้วยค่า filter ปัจจุบันใน FILTERS (คงไว้จากแท็บก่อนหน้า)
    if (typeof refreshAllChartsFromApi === 'function') { try { refreshAllChartsFromApi(); } catch (e) {} }
    if (typeof fetchOverviewKpi === 'function')        { try { fetchOverviewKpi(); } catch (e) {} }
  }

  // ★ เปิด tab "Lead" → โหลดเฉพาะ lead_breakdown แล้ว render กราฟ lead ทั้ง 6 ตัว
  if (tabName === 'lead') {
    try {
      if (typeof _dbReloadLeadBreakdown === 'function') {
        _dbReloadLeadBreakdown();
      } else if (typeof renderLeadBreakdownCharts === 'function') {
        renderLeadBreakdownCharts();
      }
    } catch (e) { console.error('[Dashboard] lead tab init threw:', e); }
  }

  // ★ เปิด tab "Pipeline" → เรียก pipeline API (page=1) ด้วยค่า filter ปัจจุบัน
  //   21/08/2026: เดิมบังคับ filter ทั้งหมด = all/2026 ทุกครั้งที่เข้าแท็บนี้ — เอาออกตามที่ user สั่ง
  //   ให้ filter ที่เลือกไว้จากแท็บก่อนหน้ายังคงอยู่ (fetchPipelinePage คำนวณ year จาก page เอง ไม่ได้อ่านจาก FILTERS.year)
  if (tabName === 'pipeline') {
    try {
      if (typeof fetchPipelinePage === 'function') fetchPipelinePage(1);
    } catch (e) { console.error('[Dashboard] pipeline tab init threw:', e); }
  }

  // ★ เปิด tab "ลูกค้าตามกลุ่มขั้นตอน" → โหลดข้อมูลหน้าแรก (page=1)
  if (tabName === 'customerGroup') {
    try {
      // ★ activitygroup ตาม dropdown แผนก (default CS → cs)
      //   21/08/2026: เลิกบังคับ year=2026 ทุกครั้งที่เข้าแท็บนี้ — ให้ปีที่เลือกไว้จากแท็บก่อนหน้ายังคงอยู่ตามที่ user สั่ง
      if (typeof FILTERS !== 'undefined') {
        var _cgSel0 = document.getElementById('cgDeptSelect');
        // ★ ใช้ code ตรงตาม masterdata (ตัวใหญ่ เช่น CS) — เดิม .toLowerCase() เป็น 'cs'
        FILTERS.activity_group = (_cgSel0 && _cgSel0.value) || 'CS';
      }
      if (typeof fetchCustomerGroupPage === 'function') {
        fetchCustomerGroupPage(1);
      } else if (typeof renderCustomerGroup === 'function') {
        renderCustomerGroup();
      }
    } catch (e) { console.error('[Dashboard] customerGroup tab init threw:', e); }
  }

  // ★ เปิด tab "สถานะตามลูกค้า" → เซ็ต activitygroup=CS (default แผนก) แล้วโหลดหน้าแรก
  //   21/08/2026: เลิกบังคับ year=2026 ทุกครั้งที่เข้าแท็บนี้ — ให้ปีที่เลือกไว้จากแท็บก่อนหน้ายังคงอยู่ตามที่ user สั่ง
  if (tabName === 'statusByCustomer') {
    try {
      if (typeof FILTERS !== 'undefined') {
        // ★ ใช้ code ตรงตาม masterdata (ตัวใหญ่) — เดิมส่ง 'cs' ตัวเล็ก
        FILTERS.activity_group = 'CS';
      }
      // sync dropdown แผนก → CS (ตรงกับ activitygroup=CS)
      var _sbcSel = document.getElementById('sbcDeptSelect');
      if (_sbcSel) _sbcSel.value = 'CS';
      // ★ sync widget แสดงผลของแผนกให้ตรง (label + active item)
      if (typeof _sbcDeptRenderMenu === 'function') _sbcDeptRenderMenu();
      // ★ รีเซ็ต + โหลดรายการ "ขั้นตอน" ของแผนก CS (รายการขึ้นกับแผนก)
      _sbcStepSel = 'all';
      if (typeof _sbcLoadActivitySteps === 'function') _sbcLoadActivitySteps('CS');
      if (typeof fetchStatusByCustomerPage === 'function') {
        fetchStatusByCustomerPage(1);
      } else if (typeof renderStatusByCustomer === 'function') {
        renderStatusByCustomer();
      }
    } catch (e) { console.error('[Dashboard] statusByCustomer tab init threw:', e); }
  }

  // Lazy-load status data ตอนเปิด tab — render pills + fetch API
  if (tabName === 'status') {
    try {
      // ★ 21/08/2026: เลิกบังคับ chanel=all/activitygroup=all ทุกครั้งที่เข้าแท็บนี้ — ให้ filter
      //   ที่เลือกไว้จากแท็บก่อนหน้ายังคงอยู่แล้วใช้เรียก API ของแท็บนี้ตามที่ user สั่ง
      //   ★ ยกเว้น datebasis — แท็บนี้อยู่ใน DB_BASIS_LOCKED_TABS จึงถูก _dbApplyBasisForTab()
      //     (เรียกไปแล้วด้านบนก่อนถึงบล็อกนี้) disable radio + บังคับเป็น 'contact' ให้เรียบร้อย
      //     → employee_performance / stage_summary ด้านล่างจึงยิงด้วย datebasis=contact เสมอ
      if (typeof renderStatusYearFilters === 'function') renderStatusYearFilters();
      // ★ SKIPPED: loadStatusForCurrentYear() — เป็น function เก่าที่ compute จาก RAW_DATA (mock)
      //   แล้ว setTimeout 80ms เรียก renderStatus() ที่ทับ statusBody ด้วย mock data
      //   ตอนนี้เรา fetch จาก API จริงแล้ว → ข้าม loadStatusForCurrentYear() ทั้งหมด
      // ★ Fetch /employee_performance?group=CS (default) — ตอนเปิด tab ครั้งแรก หรือ filter เปลี่ยน
      //   ระหว่างรอ API → renderStatusTable() จะแสดง "กำลังโหลด..." (เพราะ _statusFetchedKey === null)
      //   หลัง fetch สำเร็จ → set _statusFetchedKey เป็น "group:filterSig" → แสดงข้อมูลจริง
      var defaultDept = (typeof _statusCurrentDept !== 'undefined' && _statusCurrentDept) ? _statusCurrentDept : 'CS';
      // ★ บังคับ renderStatusTable ทันทีเพื่อแสดง loading placeholder (กัน mock ค้าง)
      if (typeof renderStatusTable === 'function') renderStatusTable();
      // ★ เปลี่ยนมาที่แท็บนี้ → เรียก API ใหม่เสมอ (ไม่เช็ค cache)
      if (typeof fetchEmployeePerformanceByGroup === 'function') {
        fetchEmployeePerformanceByGroup(defaultDept);
      }
      // ★ การ์ด KPI ด้านบน (statusKPIs) — ดึง statusKpis (stage_summary) → renderStatusKPIs
      //   ใช้ servlet /dashboard/chart-single (same-origin) ไม่ต้องขอ local network permission
      _dbReloadStatusKpis();
    } catch (e) { console.error('[Dashboard] status tab init threw:', e); }
  }

  // ★ เปิด tab "กลุ่มขั้นตอน" (steps) → ดึง groupPanels (activitygroup) → renderGroupPanels
  //   (refreshAllChartsFromApi ของ overview ไม่ได้ดึง groupPanels ให้ จึงต้องดึงเองที่นี่)
  if (tabName === 'steps') {
    try {
      _dbReloadGroupPanels();
    } catch (e) { console.error('[Dashboard] steps tab init threw:', e); }
  }

  // ★ เปิด tab "ตารางลีดทั้งหมด" (table) → ดึงข้อมูลลีดหน้าแรกใหม่จาก API
  if (tabName === 'table') {
    try {
      if (typeof fetchLeadsPage === 'function') fetchLeadsPage(1);
    } catch (e) { console.error('[Dashboard] table tab init threw:', e); }
  }

  // ★ เปิด tab "ปฏิทินงาน" (calendar) → ใส่ HTML ที่ prefetch ไว้ลง iframe ผ่าน srcdoc
  //   หมายเหตุ: เซิร์ฟเวอร์ตั้ง header X-Frame-Options: DENY → โหลดผ่าน iframe.src ตรง ๆ ไม่ได้
  //   จึง fetch เนื้อหามาแล้วใส่ใน srcdoc (ไม่ผ่าน network navigation จึงไม่โดนบล็อก)
  //   ตัว fetch จริงอยู่ใน _dbPrefetchCalendarFrame() ซึ่งถูกยิงล่วงหน้าตั้งแต่ตอนโหลดหน้า
  //   → กดแท็บแล้วมักได้ HTML ทันที (ดูคำอธิบายเต็มที่ฟังก์ชันนั้น)
  if (tabName === 'calendar') {
    try {
      var _calFrame = document.getElementById('calendarFrame');
      var _calLoad  = document.getElementById('calendarFrameLoading');
      // data-loading กันเคสกดแท็บรัวๆ ตอนยัง fetch ไม่เสร็จ → ไม่ให้เซ็ต srcdoc ซ้ำ (iframe จะ reload 2 รอบ)
      if (_calFrame && _calFrame.getAttribute('data-loaded') !== '1'
                    && _calFrame.getAttribute('data-loading') !== '1') {
        _calFrame.setAttribute('data-loading', '1');
        if (_calLoad) _calLoad.style.display = '';
        // ซ่อน placeholder ตอน iframe render เสร็จจริง (srcdoc ยังต้อง parse + โหลดฟอนต์ต่ออีก)
        _calFrame.addEventListener('load', function () {
          if (_calLoad) _calLoad.style.display = 'none';
        }, { once: true });
        _dbPrefetchCalendarFrame()
          .then(function (html) {
            _calFrame.removeAttribute('src');
            _calFrame.srcdoc = html;
            _calFrame.setAttribute('data-loaded', '1');
            _calFrame.removeAttribute('data-loading');
          })
          .catch(function (err) {
            console.error('[Dashboard] calendar load failed:', err);
            _calFrame.removeAttribute('data-loading');   // ปลดล็อกให้กดใหม่แล้ว retry ได้
            if (_calLoad) _calLoad.style.display = 'none';
            _calFrame.srcdoc = '<div style="font-family:sans-serif;padding:24px;color:#b00">โหลดปฏิทินไม่สำเร็จ — ' + (err.message || err) + '</div>';
          });
      } else if (_calLoad) {
        _calLoad.style.display = 'none';   // โหลดไว้แล้ว — iframe เดิมยังอยู่ ไม่ต้องโชว์ placeholder
      }
    } catch (e) { console.error('[Dashboard] calendar tab init threw:', e); }
  }

  // ★ เปิด tab "KPI-EventMovement" (kpi) → โหลดเนื้อหา kpi_list.xhtml เข้า iframe ผ่าน srcdoc
  //   (วิธีเดียวกับแท็บปฏิทิน — X-Frame-Options: DENY ทำให้โหลดผ่าน iframe.src ตรง ๆ ไม่ได้)
  //   ★ 26/08/2026 — เปิดใช้แท็บนี้จริง (เฉพาะสาขา Gold) แก้ของเดิมที่เป็น dead code 3 จุด:
  //     (1) **ไม่ได้แทน placeholder `__GOLDAPI__`** — frame นี้ต่างจากปฏิทิน: ข้างในมี
  //         `var KPI_GOLD_API = '__GOLDAPI__'` + จุดที่ประกอบ URL รวม 8 แห่ง ถ้ายัด srcdoc
  //         ดิบๆ ค่าจะยังเป็น literal "__GOLDAPI__" → fetch ทุกเส้นในนั้น 404 หมด
  //         (บั๊กเดียวกับที่เคยเจอ+แก้ไปแล้วในหน้า gold — ตัวนี้ยังค้างอยู่เพราะไม่เคยถูกเรียก)
  //     (2) path อิง window.location (พังถ้าเข้าหน้าผ่าน URL อื่น) → ใช้ contextPath
  //     (3) ไม่มี guard → สลับแท็บกลับมาทีไร fetch ใหม่ทับ srcdoc ทุกครั้ง งานที่พิมพ์ค้างไว้หาย
  if (tabName === 'kpi') {
    _dbLoadKpiFrame('switch-tab');
  }
}

/* ════════════════════════════════════════════════════════════════
 *  ★ TAB EXTENSION — routing override + nav wiring (main-app adapt)
 *  _sunEndpoint: source ยิงตรง SUN_API(external) → main route ผ่าน servlet
 *  same-origin (เลี่ยง CORS/403) + map ชื่อ endpoint → path ของ servlet ใน main
 * ════════════════════════════════════════════════════════════════ */
/* ★ Proxy ทุก endpoint ไปยัง Spring RestController DashboardSunApiController
   Frontend → /dashboard/api/v1/sundashboard/{endpoint}
   Controller proxy → http://192.168.24.177:3307/dashboard-triplesale-service/api/v1/sundashboard/{endpoint} */
function _sunEndpoint(endpoint, qs) {
  var base = (typeof DB_API_BASE !== 'undefined' && DB_API_BASE) ? DB_API_BASE : '/dashboard';
  // ★ 24/08/2026 — เติม ggwbranch ที่จุดรวมนี้จุดเดียว ครอบทุกเส้นที่ยิงผ่าน proxy
  //   (pipeline, pipeline/detail, customer_step_groups, customer_status_list,
  //    employee_performance*, lead_list, lead_list/detail, overview)
  //   proxy forward query string ทั้งก้อนตรงๆ → ggwbranch ถึง SUN API ครบ
  //   ★ 26/08/2026 (รอบ 2) — เปลี่ยนชื่อ param จาก branch → ggwbranch ตามที่ user สั่ง
  return _dbGgwbranchParam(base + '/api/v1/sundashboard/' + endpoint + (qs || ''));
}

/* query string จาก FILTERS ปัจจุบัน (ใช้กับ chart-single ของแท็บ steps/status) */
function _dbTabChartQs() {
  var F = (typeof FILTERS !== 'undefined' && FILTERS) ? FILTERS : {};
  return 'year='          + encodeURIComponent(F.year           || '2026')
       + '&month='        + encodeURIComponent(F.month          || 'all')
       + '&fromdate='     + encodeURIComponent(F.fromdate       || 'all')
       + '&todate='       + encodeURIComponent(F.todate         || 'all')
       + '&datebasis='    + encodeURIComponent(F.datebasis      || 'contact')
       + '&employee='     + encodeURIComponent(F.employee       || 'all')
       + '&chanel='       + encodeURIComponent(F.chanel         || 'all')
       + '&country='      + encodeURIComponent(F.country        || 'all')
       + '&occupation='   + encodeURIComponent(F.occupation     || 'all')
       + '&province='     + encodeURIComponent(F.province       || 'all')
       + '&activitygroup='+ encodeURIComponent(F.activity_group || 'all')
       + '&movementtype=' + encodeURIComponent(F.movementtype   || 'all');
}

/* fetch chart-single 1 ตัว → set ECDATA → render (สำหรับ groupPanels / statusKpis
   ที่ refreshAllChartsFromApi ของ overview ไม่ได้ดึงให้)
   extraQs (optional) — ต่อท้าย query string ปกติ เช่น '&group=CS' สำหรับ statusKpis เท่านั้น
   (ไม่ยัดใส่ _dbTabChartQs() ตรงๆ เพราะฟังก์ชันนั้นใช้ร่วมกับ groupPanels ของแท็บ "กลุ่มขั้นตอน"
   ด้วย ซึ่งไม่เกี่ยวกับ group/แผนกเลย) */
function _dbLoadTabChart(chartName, apply, extraQs, onError) {
  var base = (typeof DB_API_BASE !== 'undefined' && DB_API_BASE) ? DB_API_BASE : '/dashboard';
  // ★ 27/08/2026 — เติม ggwBranch (ss_branch_code) เหมือนกราฟหน้าภาพรวม (ดู refreshAllChartsFromApi)
  var url = _dbGgwbranchParam(base + '/chart-single?chart=' + encodeURIComponent(chartName)
          + '&' + _dbTabChartQs() + (extraQs || ''));
  env.fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } })
    .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
    .then(function (resp) {
      var arr = (resp && resp.data) || [];
      try { apply(arr); } catch (e) { console.error('[Dashboard] apply ' + chartName + ' failed:', e); }
    })
    .catch(function (err) {
      console.error('[Dashboard] chart-single(' + chartName + ') failed:', err);
      if (typeof onError === 'function') {
        try { onError(err); } catch (e) { console.error('[Dashboard] onError ' + chartName + ' failed:', e); }
      }
    });
}

