/* ย้าย modal ไปไว้ระดับ body ใน host .dbsun-root (display:contents) — escape ancestor
   ที่มี transform (pandora layout) เพื่อให้ position:fixed อ้างอิง viewport → กลางจอเสมอ */
function _dbHostModalAtBody(el) {
  if (!el) return;
  var host = document.getElementById('dbsunModalHost');
  if (!host) {
    host = document.createElement('div');
    host.id = 'dbsunModalHost';
    host.className = 'dbsun-root';
    host.style.display = 'contents';
    document.body.appendChild(host);
  }
  if (el.parentNode !== host) host.appendChild(el);
}

